insert into public.reference_texts (ref_key, source_type, title, book_or_section, body)
values
  ('Gn 6,14', 'biblia', 'Génesis 6, 14', 'Antiguo Testamento · Pentateuco', '«Hazte un arca de madera resinosa; la dividirás en compartimentos y la calafatearás por dentro y por fuera con brea.»'),
  ('CIC 1219', 'cic', 'Catecismo de la Iglesia Católica · N.° 1219', 'Segunda Parte · El sacramento del Bautismo', 'La Iglesia ha visto en el arca de Noé una prefiguración de la salvación por el Bautismo. En efecto, por medio de ella «unos pocos, es decir, ocho personas, fueron salvados a través del agua» (1 P 3,20).'),
  ('Éx 19,20; 20,1-17', 'biblia', 'Éxodo 19,20 y 20,1-3', 'Antiguo Testamento · Pentateuco', '«El Señor descendió sobre la cumbre del monte Sinaí y llamó a Moisés hacia la cima. Moisés subió... Entonces pronunció Dios todas estas palabras diciendo: "Yo soy el Señor, tu Dios, que te saqué de la tierra de Egipto, de la casa de servidumbre. No tendrás otros dioses delante de mí."»'),
  ('CIC 2056', 'cic', 'Catecismo de la Iglesia Católica · N.° 2056', 'Tercera Parte · Los Diez Mandamientos', 'La palabra «Decálogo» significa literalmente «diez palabras» (Éx 34,28). Estas «diez palabras» Dios las reveló a su pueblo en la santa montaña. Las escribió «con su dedo» (Éx 31,18), a diferencia de los otros preceptos escritos por Moisés. Constituyen palabras de Dios en un sentido eminente.'),
  ('Gn 12,1-4', 'biblia', 'Génesis 12, 1-4', 'Antiguo Testamento · Vocación de Abraham', '«El Señor dijo a Abram: "Deja tu tierra natal y la casa de tu padre, y ve al país que yo te mostraré. Yo haré de ti una gran nación y te bendeciré; engrandeceré tu nombre y serás una bendición." Abram partió, como el Señor se lo había ordenado.»'),
  ('CIC 145', 'cic', 'Catecismo de la Iglesia Católica · N.° 145', 'Primera Parte · La obediencia de la fe', 'La carta a los Hebreos, en el gran elogio de la fe de los antepasados, insiste particularmente en la fe de Abraham: «Por la fe, Abraham obedeció y salió para el lugar que había de recibir en herencia, y salió sin saber a dónde iba» (Hb 11,8). Por la fe, vivió como extranjero y peregrino en la tierra prometida.'),
  ('CIC 2579', 'cic', 'Catecismo de la Iglesia Católica · N.° 2579', 'Cuarta Parte · La oración en el Antiguo Testamento', 'David es por excelencia el rey «según el corazón de Dios», el pastor que ora por su pueblo y en su nombre, aquel cuya sumisión a la voluntad de Dios, cuya alabanza y arrepentimiento serán modelo de la oración del pueblo. Su oración, inspirada por el Espíritu Santo, es el primer modelo de la oración de los Salmos.'),
  ('Is 7,14', 'biblia', 'Isaías 7, 14', 'Antiguo Testamento · Libros Proféticos', '«Por eso, el Señor mismo les dará una señal: Miren, la joven concebirá y dará a luz un hijo, y lo llamará con el nombre de Emmanuel.»'),
  ('Mt 1,22-23', 'biblia', 'Mateo 1, 22-23', 'Nuevo Testamento · Evangelio según san Mateo', '«Todo esto sucedió para que se cumpliera lo que el Señor había anunciado por el profeta: "La Virgen concebirá y dará a luz un hijo, a quien pondrán el nombre de Emmanuel", que traducido significa: "Dios con nosotros".»'),
  ('2 Mac 12,43-46', 'biblia', 'Segundo libro de los Macabeos 12, 43-46', 'Antiguo Testamento · Libros Deuterocanónicos', '«Después de haber reunido entre sus hombres cerca de dos mil dracmas, las mandó a Jerusalén para ofrecer un sacrificio por el pecado, obrando muy hermosa y noblemente, pensando en la resurrección... Por eso mandó hacer este sacrificio expiatorio en favor de los muertos, para que quedaran liberados del pecado.»'),
  ('CIC 1032', 'cic', 'Catecismo de la Iglesia Católica · N.° 1032', 'Primera Parte · La purificación final o Purgatorio', 'Esta enseñanza se apoya también en la práctica de la oración por los difuntos, de la que ya habla la Escritura (2 M 12,46). Desde los primeros tiempos, la Iglesia ha honrado la memoria de los difuntos y ha ofrecido sufragios en su favor, en particular el sacrificio eucarístico, para que, una vez purificados, puedan llegar a la visión beatífica de Dios.'),
  ('Jn 2,1-11', 'biblia', 'Juan 2, 1-11', 'Nuevo Testamento · Las bodas de Caná', '«Al tercer día se celebraron unas bodas en Caná de Galilea, y la madre de Jesús estaba allí... Su madre dijo a los sirvientes: "Hagan todo lo que él les diga."... Así, en Caná de Galilea, dio Jesús comienzo a sus signos. Y manifestó su gloria, y creyeron en él sus discípulos.»'),
  ('CIC 2618', 'cic', 'Catecismo de la Iglesia Católica · N.° 2618', 'Cuarta Parte · La oración de la Virgen María', 'El Evangelio nos revela cómo María ora e intercede en la fe: en Caná, la madre de Jesús ruega a su hijo por las necesidades de un banquete de bodas, signo de otro banquete, el de las bodas del Cordero que da su Cuerpo y su Sangre a petición de la Iglesia, su Esposa.'),
  ('Mt 16,18-19', 'biblia', 'Mateo 16, 18-19', 'Nuevo Testamento · Confesión de Pedro', '«Y yo te digo: Tú eres Pedro, y sobre esta piedra edificaré mi Iglesia, y el poder de la Muerte no prevalecerá contra ella. Yo te daré las llaves del Reino de los Cielos.»'),
  ('CIC 552', 'cic', 'Catecismo de la Iglesia Católica · N.° 552', 'Primera Parte · Las llaves del Reino', 'En el colegio de los Doce, Simón Pedro ocupa el primer lugar. Jesús le confió una misión única. Gracias a una revelación venida del Padre, Pedro había confesado: «Tú eres el Cristo, el Hijo de Dios vivo». Entonces nuestro Señor le declaró: «Tú eres Pedro, y sobre esta piedra edificaré mi Iglesia».'),
  ('Jn 6,9-13', 'biblia', 'Juan 6, 9-13', 'Nuevo Testamento · Multiplicación de los panes', '«"Aquí hay un muchacho que tiene cinco panes de cebada y dos pescados, pero ¿qué es esto para tanta gente?"... Jesús tomó los panes, dio gracias y los distribuyó a los que estaban sentados. Lo mismo hizo con los pescados, dándoles todo lo que quisieron.»'),
  ('CIC 1335', 'cic', 'Catecismo de la Iglesia Católica · N.° 1335', 'Segunda Parte · La Eucaristía', 'Los milagros de la multiplicación de los panes, cuando el Señor dijo la bendición, partió y distribuyó los panes por medio de sus discípulos para alimentar la multitud, prefiguran la sobreabundancia de este único pan de su Eucaristía.'),
  ('Lc 15,11-32', 'biblia', 'Lucas 15, 20-24', 'Nuevo Testamento · Parábola del Padre Misericordioso', '«Cuando todavía estaba lejos, su padre lo vio y se conmovió profundamente; corrió a su encuentro, lo abrazó y lo besó... "Porque este hijo mío estaba muerto y ha vuelto a la vida; estaba perdido y fue encontrado."»'),
  ('CIC 1439', 'cic', 'Catecismo de la Iglesia Católica · N.° 1439', 'Segunda Parte · La penitencia interior', 'El proceso de la conversión y de la penitencia fue descrito maravillosamente por Jesús en la parábola llamada «del hijo pródigo», cuyo centro es «el padre misericordioso» (Lc 15,11-24). Solo el corazón de Cristo que conoce las profundidades del amor de su Padre pudo revelarnos el abismo de su misericordia.'),
  ('Hch 2,1-4', 'biblia', 'Hechos de los Apóstoles 2, 1-4', 'Nuevo Testamento · Pentecostés', '«Al llegar el día de Pentecostés, estaban todos reunidos en el mismo lugar. De pronto, vino del cielo un ruido, semejante a una fuerte ráfaga de viento... Vieron aparecer unas lenguas como de fuego, que descendieron por separado sobre cada uno de ellos. Todos quedaron llenos del Espíritu Santo.»'),
  ('CIC 731', 'cic', 'Catecismo de la Iglesia Católica · N.° 731', 'Primera Parte · Pentecostés', 'El día de Pentecostés (al término de las siete semanas pascuales), la Pascua de Cristo se consuma con la efusión del Espíritu Santo que se manifiesta, da y comunica como Persona divina: desde su plenitud, Cristo, el Señor, derrama profusamente el Espíritu.'),
  ('1 Cor 13,4-13', 'biblia', 'Primera carta a los Corintios 13, 4-8.13', 'Nuevo Testamento · Himno a la caridad', '«El amor es paciente, es servicial; el amor no es envidioso, no hace alarde, no se envanece... El amor no pasará jamás... En una palabra, ahora existen tres cosas: la fe, la esperanza y el amor, pero la más grande todas es el amor.»'),
  ('CIC 1826', 'cic', 'Catecismo de la Iglesia Católica · N.° 1826', 'Tercera Parte · La caridad', 'Si no tengo caridad —dice también el Apóstol— «nada soy». Y todo lo que es privilegio, servicio, virtud misma... si no tengo caridad, «nada me aprovecha». La caridad es superior a todas las virtudes. Es la primera de las virtudes teologales.'),
  ('CIC 344', 'cic', 'Catecismo de la Iglesia Católica · N.° 344', 'Primera Parte · La Creación', 'Existe una solidaridad entre todas las criaturas por el hecho de que todas tienen el mismo Creador, y que todas están ordenadas a su gloria. San Francisco de Asís lo cantó de modo admirable en su Cántico de las Criaturas.'),
  ('CIC 2011', 'cic', 'Catecismo de la Iglesia Católica · N.° 2011', 'Tercera Parte · La gracia y el mérito', 'La caridad de Cristo es en nosotros la fuente de todos nuestros méritos ante Dios. La gracia, uniéndonos a Cristo con un amor activo, asegura el carácter sobrenatural de nuestros actos y, por consiguiente, su mérito tanto ante Dios como ante los hombres.'),
  ('Mt 1,19-24', 'biblia', 'Mateo 1, 19-24', 'Nuevo Testamento · San José', '«José, su esposo, que era un hombre justo... Al despertar, José hizo lo que el Ángel del Señor le había ordenado, y llevó a María a su casa.»'),
  ('CIC 437', 'cic', 'Catecismo de la Iglesia Católica · N.° 437', 'Primera Parte · El nacimiento de Jesús', 'El ángel anunció a los pastores el nacimiento de Jesús como el del Mesías prometido a Israel. Desde el comienzo, Él es «aquel a quien el Padre ha santificado y enviado al mundo», concebido como «santo» en el seno virginal de María. José fue llamado por Dios para «tomar consigo a María su esposa».'),
  ('CIC 30', 'cic', 'Catecismo de la Iglesia Católica · N.° 30', 'Primera Parte · El deseo de Dios', '«Alégrese el corazón de los que buscan a Dios» (Sal 105,3). Como decía san Agustín en sus Confesiones: «Tú mismo le excitas a ello, haciendo que se deleite en alabarte, porque nos has hecho para ti y nuestro corazón está inquieto mientras no descanse en ti».'),
  ('CIC 1381', 'cic', 'Catecismo de la Iglesia Católica · N.° 1381', 'Segunda Parte · La presencia real de Cristo', 'La presencia del verdadero Cuerpo de Cristo y de la verdadera Sangre de Cristo en este sacramento «no se conoce por los sentidos, dice santo Tomás, sino solo por la fe, la cual se apoya en la autoridad de Dios».'),
  ('CIC 1210', 'cic', 'Catecismo de la Iglesia Católica · N.° 1210', 'Segunda Parte · Los siete sacramentos', 'Los sacramentos de la Nueva Ley fueron instituidos por Cristo y son siete, a saber: Bautismo, Confirmación, Eucaristía, Penitencia, Unción de los enfermos, Orden sacerdotal y Matrimonio. Los siete sacramentos corresponden a todas las etapas y todos los momentos importantes de la vida del cristiano.'),
  ('CIC 1213', 'cic', 'Catecismo de la Iglesia Católica · N.° 1213', 'Segunda Parte · El Bautismo', 'El santo Bautismo es el fundamento de toda la vida cristiana, el pórtico de la vida en el espíritu y la puerta que abre el acceso a los otros sacramentos. Por el Bautismo somos liberados del pecado y regenerados como hijos de Dios, llegamos a ser miembros de Cristo y somos incorporados a la Iglesia.'),
  ('CIC 1324', 'cic', 'Catecismo de la Iglesia Católica · N.° 1324', 'Segunda Parte · La Eucaristía', 'La Eucaristía es «fuente y culmen de toda la vida cristiana» (LG 11). Los demás sacramentos, como también todos los ministerios eclesiales y las obras de apostolado, están unidos a la Eucaristía y a ella se ordenan.'),
  ('CIC 1421', 'cic', 'Catecismo de la Iglesia Católica · N.° 1421', 'Segunda Parte · Los sacramentos de curación', 'El Señor Jesucristo, médico de nuestras almas y de nuestros cuerpos, el que perdonó los pecados al paralítico y le devolvió la salud del cuerpo, quiso que su Iglesia continuase, con la fuerza del Espíritu Santo, su obra de curación y de salvación mediante los sacramentos de la Penitencia y de la Unción de los enfermos.'),
  ('CIC 1300', 'cic', 'Catecismo de la Iglesia Católica · N.° 1300', 'Segunda Parte · La Confirmación', 'Sigue el rito esencial del sacramento. En el rito latino, «el sacramento de la Confirmación es conferido por la unción del santo crisma en la frente, hecha imponiendo la mano, y con estas palabras: "Recibe por esta señal el don del Espíritu Santo"».'),
  ('CIC 1121', 'cic', 'Catecismo de la Iglesia Católica · N.° 1121', 'Segunda Parte · El carácter sacramental', 'Los tres sacramentos del Bautismo, de la Confirmación y del Orden confieren, además de la gracia, un carácter sacramental o «sello» por el cual el cristiano participa del sacerdocio de Cristo y forma parte de la Iglesia según estados y funciones diversos. Este sello espiritual es indeleble y por eso estos sacramentos no se reiteran.'),
  ('CIC 1346', 'cic', 'Catecismo de la Iglesia Católica · N.° 1346', 'Segunda Parte · El desarrollo de la celebración', 'La liturgia de la Eucaristía se desarrolla conforme a una estructura fundamental que se ha conservado a través de los siglos hasta nosotros. Comprende dos grandes momentos que forman una unidad básica: la reunión, la liturgia de la Palabra y la liturgia eucarística.'),
  ('CIC 524', 'cic', 'Catecismo de la Iglesia Católica · N.° 524', 'Primera Parte · El tiempo de Adviento', 'Al celebrar anualmente la liturgia de Adviento, la Iglesia actualiza esta espera del Mesías: participando en la larga preparación de la primera venida del Salvador, los fieles renuevan el ardiente deseo de su segunda venida.'),
  ('CIC 1169', 'cic', 'Catecismo de la Iglesia Católica · N.° 1169', 'Segunda Parte · El año litúrgico', 'Por eso la Pascua no es simplemente una fiesta entre otras: es la «Fiesta de las fiestas», «Solemnidad de las solemnidades», como la Eucaristía es el Sacramento de los sacramentos.'),
  ('IGMR 346', 'igmr', 'Instrucción General del Misal Romano · N.° 346', 'Liturgia · Colores de las vestiduras sagradas', 'La diversidad de colores en las vestiduras sagradas pretende expresar con más eficacia el carácter propio de los misterios de la fe que se celebran: blanco en Pascua y Navidad; rojo en Domingo de Ramos, Viernes Santo, Pentecostés y mártires; verde en el Tiempo Ordinario; morado en Adviento y Cuaresma.'),
  ('CIC 1174-1175', 'cic', 'Catecismo de la Iglesia Católica · N.° 1174–1175', 'Segunda Parte · La Liturgia de las Horas', 'El misterio de Cristo, su Encarnación y su Pascua, que celebramos en la Eucaristía, penetra y transfigura el tiempo de cada día mediante la celebración de la Liturgia de las Horas, «el Oficio divino». Está destinada a llegar a ser la oración de todo el Pueblo de Dios.'),
  ('CIC 882', 'cic', 'Catecismo de la Iglesia Católica · N.° 882', 'Primera Parte · El Papa y el colegio episcopal', 'El Papa, obispo de Roma y sucesor de san Pedro, «es el principio y fundamento perpetuo y visible de unidad, tanto de los obispos como de la muchedumbre de los fieles» (LG 23).'),
  ('CIC 1202-1203', 'cic', 'Catecismo de la Iglesia Católica · N.° 1202–1203', 'Segunda Parte · Tradiciones litúrgicas y catolicidad', 'Las diversas tradiciones litúrgicas nacieron por razón misma de la misión de la Iglesia. Las tradiciones litúrgicas, o ritos, actualmente en uso en la Iglesia son el rito latino y los ritos orientales (bizantino, alejandrino, siríaco, armenio, maronita y caldeo).'),
  ('CIC 1808', 'cic', 'Catecismo de la Iglesia Católica · N.° 1808', 'Tercera Parte · Las virtudes cardinales', 'La fortaleza es la virtud moral que asegura en las dificultades la firmeza y la constancia en la búsqueda del bien. Reafirma la resolución de resistir a las tentaciones y de superar los obstáculos en la vida moral.'),
  ('Lc 2,4-7', 'biblia', 'Lucas 2, 4-7', 'Nuevo Testamento · Nacimiento de Jesús en Belén', '«También José subió desde Galilea, de la ciudad de Nazaret, a Judea, a la ciudad de David, llamada Belén... Y María dio a luz a su hijo primogénito, lo envolvió en pañales y lo acostó en un pesebre.»'),
  ('1 Cor 9,24-25', 'biblia', 'Primera carta a los Corintios 9, 24-25', 'Nuevo Testamento · Cartas de san Pablo', '«¿No saben que en el estadio todos corren, pero uno solo gana el premio? Corran, entonces, de manera que lo ganen. Los atletas se privan de todo por una corona corruptible; nosotros, en cambio, por una incorruptible.»'),
  ('Gn 1,27', 'biblia', 'Génesis 1, 27', 'Antiguo Testamento · Creación del ser humano', '«Y Dios creó al ser humano a su imagen; lo creó a imagen de Dios, los creó varón y mujer.»'),
  ('Gn 3,15', 'biblia', 'Génesis 3, 15 (Protoevangelio)', 'Antiguo Testamento · Promesa de salvación', '«Pondré enemistad entre ti y la mujer, entre tu linaje y el suyo. Él te aplastará la cabeza y tú le acecharás el talón.»'),
  ('Gn 32,29', 'biblia', 'Génesis 32, 29', 'Antiguo Testamento · Jacob recibe el nombre de Israel', '«Él le dijo: "En adelante ya no te llamarás Jacob, sino Israel, porque has luchado con Dios y con los hombres, y has vencido."»'),
  ('Éx 3,1-14', 'biblia', 'Éxodo 3, 2-14', 'Antiguo Testamento · La zarza ardiente', '«El Ángel del Señor se le apareció en una llama de fuego, que salía de en medio de la zarza... Dios dijo a Moisés: "Yo soy el que soy. Así hablarás a los israelitas: Yo Soy me envía a ustedes."»'),
  ('Éx 14,21-22', 'biblia', 'Éxodo 14, 21-22', 'Antiguo Testamento · El paso del mar Rojo', '«Moisés extendió su mano sobre el mar... las aguas se dividieron, y los israelitas entraron en medio del mar a pie enjuto, mientras las aguas formaban una muralla a derecha e izquierda.»'),
  ('Éx 16,14-15', 'biblia', 'Éxodo 16, 14-15', 'Antiguo Testamento · El maná en el desierto', '«Al evaporarse el rocío, apareció sobre la superficie del desierto una cosa fina y granulada... Moisés les dijo: "Éste es el pan que el Señor les da para comer."»'),
  ('Éx 25,10-16', 'biblia', 'Éxodo 25, 10-16', 'Antiguo Testamento · El Arca de la Alianza', '«Harán un arca de madera de acacia... La recubrirás de oro puro por dentro y por fuera... Dentro del arca pondrás el Testimonio que yo te daré.»'),
  ('Jos 1,1-6', 'biblia', 'Josué 1, 1-6', 'Antiguo Testamento · Vocación de Josué', '«Después de la muerte de Moisés, el Señor dijo a Josué: "Prepárate para pasar el Jordán con todo este pueblo, hacia la tierra que yo doy a los israelitas. Sé fuerte y valiente."»'),
  ('2 Sam 23,1-2', 'biblia', 'Segundo libro de Samuel 23, 1-2', 'Antiguo Testamento · David, el cantor de Israel', '«Oráculo de David, hijo de Jesé, el favorito de los cantos de Israel: "El espíritu del Señor habla por mí y su palabra está en mi lengua."»'),
  ('1 Re 3,9', 'biblia', 'Primer libro de los Reyes 3, 9', 'Antiguo Testamento · Oración de Salomón', '«Concede a tu servidor un corazón comprensivo, para juzgar a tu pueblo y discernir entre el bien y el mal.»'),
  ('1 Re 19,11-13', 'biblia', 'Primer libro de los Reyes 19, 11-13', 'Antiguo Testamento · Elías en el monte Horeb', '«Vino un viento impetuoso, pero el Señor no estaba en el viento; luego un terremoto, y tampoco; después un fuego, y tampoco; y después del fuego, el susurro de una brisa suave. Al oírlo, Elías se cubrió el rostro con el manto.»'),
  ('Neh 8,4', 'biblia', 'Nehemías 8, 4-5', 'Antiguo Testamento · Proclamación de la Palabra', '«El escriba Esdras estaba de pie sobre un estrado de madera construido para la ocasión... Abrió el libro a la vista de todo el pueblo, y al abrirlo, todo el pueblo se puso de pie.»'),
  ('Tob 12,15', 'biblia', 'Tobías 12, 15', 'Antiguo Testamento · Libros Deuterocanónicos', '«Yo soy Rafael, uno de los siete ángeles que están siempre presentes y tienen entrada ante la gloria del Señor.»'),
  ('Job 19,25', 'biblia', 'Job 19, 25', 'Antiguo Testamento · Libros Sapienciales', '«Yo sé que mi Redentor vive y que al final se alzará sobre el polvo.»'),
  ('Sal 63,2', 'biblia', 'Salmo 63, 2', 'Antiguo Testamento · Salmos', '«Oh Dios, tú eres mi Dios, yo te busco ardientemente; mi alma tiene sed de ti, por ti suspira mi carne como tierra sedienta, reseca y sin agua.»'),
  ('Sal 119,105', 'biblia', 'Salmo 119, 105', 'Antiguo Testamento · Salmos', '«Tu palabra es una lámpara para mis pasos y una luz en mi camino.»'),
  ('Sal 119,164', 'biblia', 'Salmo 119, 164', 'Antiguo Testamento · Salmos', '«Siete veces al día te alabo por tus justas decisiones.»'),
  ('Sal 141,2', 'biblia', 'Salmo 141, 2', 'Antiguo Testamento · Oración de la tarde', '«Suba mi oración como incienso en tu presencia, y mis manos levantadas como la ofrenda de la tarde.»'),
  ('Prov 9,10', 'biblia', 'Proverbios 9, 10', 'Antiguo Testamento · Libros Sapienciales', '«El principio de la sabiduría es el temor del Señor, y el conocimiento del Santo es la inteligencia.»'),
  ('Is 40,3', 'biblia', 'Isaías 40, 3', 'Antiguo Testamento · Anuncio de Adviento', '«Una voz clama: "Preparen en el desierto el camino del Señor, tracen en la estepa un sendero para nuestro Dios."»'),
  ('Is 52,7', 'biblia', 'Isaías 52, 7', 'Antiguo Testamento · Mensajero de la paz', '«¡Qué hermosos son sobre las montañas los pies del mensajero que anuncia la paz, que trae la Buena Noticia, que proclama la salvación y dice a Sión: "¡Tu Dios reina!"»'),
  ('Is 63,19', 'biblia', 'Isaías 63, 19b', 'Antiguo Testamento · Súplica de Adviento', '«¡Ojalá rasgaras el cielo y descendieras, haciendo temblar las montañas ante tu rostro!»'),
  ('Is 64,7', 'biblia', 'Isaías 64, 7', 'Antiguo Testamento · Dios nuestro Padre y alfarero', '«Sin embargo, Señor, tú eres nuestro Padre; nosotros somos la arcilla, y tú nuestro alfarero: todos somos obra de tus manos.»'),
  ('Ez 34,11-16', 'biblia', 'Ezequiel 34, 11-16', 'Antiguo Testamento · El Señor, Pastor de su pueblo', '«Así habla el Señor: "Yo mismo iré a buscar mis ovejas y me ocuparé de ellas... Buscaré a la perdida, haré volver a la descarriada, vendaré a la herida y fortaleceré a la débil."»'),
  ('Dn 6,17-23', 'biblia', 'Daniel 6, 17-23', 'Antiguo Testamento · Daniel en el foso de los leones', '«Daniel respondió al rey: "Mi Dios envió a su ángel y cerró la boca de los leones para que no me hicieran ningún daño, porque ante Él fui hallado inocente."»'),
  ('Jl 2,12-13', 'biblia', 'Joel 2, 12-13', 'Antiguo Testamento · Llamado a la conversión', '«Vuelvan a mí de todo corazón, con ayuno, llantos y lamentos. Rasguen su corazón y no sus vestiduras, y vuelvan al Señor, su Dios, porque es bondadoso y compasivo.»'),
  ('Sof 3,12', 'biblia', 'Sofonías 3, 12', 'Antiguo Testamento · El resto humilde de Israel', '«Dejaré en medio de ti un pueblo pobre y humilde, que buscará refugio en el nombre del Señor.»'),
  ('Mt 5,1-12', 'biblia', 'Mateo 5, 1-12 (Las Bienaventuranzas)', 'Nuevo Testamento · Sermón de la Montaña', '«Felices los que tienen alma de pobres, porque a ellos les pertenece el Reino de los Cielos... Felices los que tienen el corazón puro, porque verán a Dios. Felices los que trabajan por la paz, porque serán llamados hijos de Dios.»'),
  ('Mt 5,9', 'biblia', 'Mateo 5, 9', 'Nuevo Testamento · Las Bienaventuranzas', '«Felices los que trabajan por la paz, porque serán llamados hijos de Dios.»'),
  ('Mt 6,9-13', 'biblia', 'Mateo 6, 9-13 (El Padrenuestro)', 'Nuevo Testamento · Oración del Señor', '«Ustedes oren así: Padre nuestro, que estás en el cielo, santificado sea tu Nombre; venga tu Reino; hágase tu voluntad así en la tierra como en el cielo. Danos hoy nuestro pan de cada día; perdona nuestras ofensas...»'),
  ('Mt 9,9-13', 'biblia', 'Mateo 9, 9-13', 'Nuevo Testamento · Vocación de san Mateo', '«Jesús vio a un hombre llamado Mateo, sentado en la mesa de recaudación de impuestos, y le dijo: "Sígueme." Él se levantó y lo siguió... "Porque yo no vine a llamar a justos, sino a pecadores."»'),
  ('Mt 10,32', 'biblia', 'Mateo 10, 32', 'Nuevo Testamento · Confesar a Cristo', '«Al que me reconozca abiertamente ante los hombres, yo lo reconoceré ante mi Padre que está en el cielo.»'),
  ('Mt 13,1-23', 'biblia', 'Mateo 13, 3-23 (Parábola del sembrador)', 'Nuevo Testamento · Parábolas del Reino', '«Salió el sembrador a sembrar... La semilla que cayó en tierra buena es el que escucha la Palabra y la comprende; éste produce fruto, uno ciento, otro sesenta, otro treinta.»'),
  ('Mt 16,16', 'biblia', 'Mateo 16, 16', 'Nuevo Testamento · Confesión de fe de Pedro', '«Simón Pedro tomó la palabra y dijo: "Tú eres el Mesías, el Hijo de Dios vivo."»'),
  ('Mt 18,3', 'biblia', 'Mateo 18, 3', 'Nuevo Testamento · Infancia espiritual', '«Les aseguro que si no cambian y no se hacen como los niños, no entrarán en el Reino de los Cielos.»'),
  ('Mt 19,21', 'biblia', 'Mateo 19, 21', 'Nuevo Testamento · Seguimiento radical de Cristo', '«Jesús le respondió: "Si quieres ser perfecto, ve, vende todo lo que tienes y dalo a los pobres: así tendrás un tesoro en el cielo. Después, ven y sígueme."»'),
  ('Mt 25,40', 'biblia', 'Mateo 25, 40', 'Nuevo Testamento · El servicio a los pequeños', '«Les aseguro que cada vez que lo hicieron con el más pequeño de mis hermanos, lo hicieron conmigo.»'),
  ('Mt 28,19', 'biblia', 'Mateo 28, 19', 'Nuevo Testamento · Mandato misionero', '«Vayan, y hagan que todos los pueblos sean mis discípulos, bautizándolos en el nombre del Padre y del Hijo y del Espíritu Santo.»'),
  ('Mt 28,19-20', 'biblia', 'Mateo 28, 19-20', 'Nuevo Testamento · Envío de los apóstoles', '«Vayan y hagan discípulos a todas las naciones, bautizándolos en el nombre del Padre y del Hijo y del Espíritu Santo... Y yo estaré siempre con ustedes hasta el fin del mundo.»'),
  ('Mt 28,20', 'biblia', 'Mateo 28, 20', 'Nuevo Testamento · Presencia permanente de Cristo', '«Y sepan que yo estoy con ustedes todos los días hasta el fin del mundo.»'),
  ('Mc 4,35-41', 'biblia', 'Marcos 4, 35-41 (La tempestad calmada)', 'Nuevo Testamento · Milagros de Jesús', '«Jesús se despertó, increpó al viento y dijo al mar: "¡Silencio, cálmate!" El viento se aplacó y sobrevino una gran calma. Después les dijo: "¿Por qué tienen miedo? ¿Todavía no tienen fe?"»'),
  ('Mc 10,14', 'biblia', 'Marcos 10, 14', 'Nuevo Testamento · Jesús bendice a los niños', '«Dejen que los niños se acerquen a mí y no se lo impidan, porque el Reino de Dios pertenece a los que son como ellos.»'),
  ('Mc 13,33-37', 'biblia', 'Marcos 13, 33-37', 'Nuevo Testamento · Llamado a velar en Adviento', '«Tengan cuidado y estén prevenidos porque no saben cuándo llegará el momento... Lo que les digo a ustedes, se lo digo a todos: ¡Estén prevenidos!»'),
  ('Mc 16,15', 'biblia', 'Marcos 16, 15', 'Nuevo Testamento · Misión universal', '«Y les dijo: "Vayan por todo el mundo, anuncien la Buena Noticia a toda la creación."»'),
  ('Lc 1,26-38', 'biblia', 'Lucas 1, 26-38 (La Anunciación)', 'Nuevo Testamento · Evangelio según san Lucas', '«El ángel Gabriel fue enviado por Dios a una virgen llamada María... "Alégrate, llena de gracia, el Señor está contigo."... María dijo entonces: "Yo soy la servidora del Señor, que se cumpla en mí lo que has dicho."»'),
  ('Lc 1,28', 'biblia', 'Lucas 1, 28', 'Nuevo Testamento · Saludo del ángel a María', '«El ángel entró en su casa y la saludó, diciendo: "¡Alégrate, llena de gracia, el Señor está contigo!"»'),
  ('Lc 1,34-35', 'biblia', 'Lucas 1, 34-35', 'Nuevo Testamento · Concepción virginal de Jesús', '«María dijo al ángel: "¿Cómo puede ser eso, si yo no tengo relaciones con ningún hombre?" El ángel le respondió: "El Espíritu Santo descenderá sobre ti y el poder del Altísimo te cubrirá con su sombra."»'),
  ('Lc 1,39-45', 'biblia', 'Lucas 1, 39-45 (La Visitación)', 'Nuevo Testamento · María visita a Isabel', '«Isabel quedó llena del Espíritu Santo y exclamó en alta voz: "¡Tú eres bendita entre todas las mujeres y bendito es el fruto de tu vientre! ¡Feliz de ti por haber creído!"»'),
  ('Lc 1,43', 'biblia', 'Lucas 1, 43', 'Nuevo Testamento · La Madre de mi Señor', '«¿Quién soy yo, para que la madre de mi Señor venga a visitarme?»'),
  ('Lc 1,46-55', 'biblia', 'Lucas 1, 46-55 (El Magníficat)', 'Nuevo Testamento · Cántico de María', '«María dijo entonces: "Mi alma canta la grandeza del Señor, y mi espíritu se estremece de gozo en Dios, mi Salvador, porque Él miró con bondad la pequeñez de su servidora."»'),
  ('Lc 1,48', 'biblia', 'Lucas 1, 48', 'Nuevo Testamento · Todas las generaciones', '«En adelante todas las generaciones me llamarán feliz, porque el Todopoderoso ha hecho en mí grandes cosas.»'),
  ('Lc 4,18', 'biblia', 'Lucas 4, 18', 'Nuevo Testamento · Misión de Jesús en Nazaret', '«El Espíritu del Señor está sobre mí, porque me ha consagrado por la unción. Él me envió a llevar la Buena Noticia a los pobres.»'),
  ('Lc 9,23', 'biblia', 'Lucas 9, 23', 'Nuevo Testamento · Tomar la cruz cada día', '«El que quiera venir detrás de mí, que renuncie a sí mismo, que cargue con su cruz cada día y me siga.»'),
  ('Lc 10,29-37', 'biblia', 'Lucas 10, 29-37 (El Buen Samaritano)', 'Nuevo Testamento · Parábola de la misericordia', '«Un samaritano que viajaba por allí, al verlo, se conmovió, se acercó y vendó sus heridas... Jesús le dijo: "Ve y procede tú de la misma manera."»'),
  ('Lc 11,1', 'biblia', 'Lucas 11, 1', 'Nuevo Testamento · Enséñanos a orar', '«Un día, Jesús estaba orando en cierto lugar, y cuando terminó, uno de sus discípulos le dijo: "Señor, enséñanos a orar."»'),
  ('Lc 17,11-19', 'biblia', 'Lucas 17, 11-19 (Los diez leprosos)', 'Nuevo Testamento · Gratitud y fe', '«Uno de ellos, al comprobar que estaba curado, volvió atrás alabando a Dios en voz alta y se arrojó a los pies de Jesús dándole gracias. Era un samaritano. Jesús le dijo: "Levántate y vete, tu fe te ha salvado."»'),
  ('Lc 18,1', 'biblia', 'Lucas 18, 1', 'Nuevo Testamento · Perseverancia en la oración', '«Jesús les propuso una parábola para enseñarles que debían orar siempre sin desanimarse.»'),
  ('Lc 21,1-4', 'biblia', 'Lucas 21, 1-4 (La ofrenda de la viuda)', 'Nuevo Testamento · Evangelio según san Lucas', '«Vio también a una viuda de condición muy humilde que ponía dos pequeñas monedas de cobre, y dijo: "Les aseguro que esta pobre viuda ha dado más que nadie... ella, en su indigencia, dio todo lo que tenía para vivir."»'),
  ('Lc 21,5-11', 'biblia', 'Lucas 21, 5-11', 'Nuevo Testamento · Discernimiento y confianza', '«Jesús les respondió: "Tengan cuidado de no dejarse engañar... Cuando oigan hablar de guerras y revoluciones no se alarmen."»'),
  ('Lc 21,12-19', 'biblia', 'Lucas 21, 12-19', 'Nuevo Testamento · Perseverancia en el testimonio', '«Eso les dará ocasión de dar testimonio de mí... Porque yo les daré una elocuencia y una sabiduría que ninguno de sus adversarios podrá resistir... Con su perseverancia salvarán sus vidas.»'),
  ('Lc 21,20-28', 'biblia', 'Lucas 21, 25-28', 'Nuevo Testamento · Venida gloriosa del Hijo del hombre', '«Entonces verán al Hijo del hombre venir sobre una nube, lleno de poder y de gloria. Cuando comience a suceder esto, tengan ánimo y levanten la cabeza, porque está por llegarles la liberación.»'),
  ('Lc 21,29-33', 'biblia', 'Lucas 21, 29-33', 'Nuevo Testamento · La higuera y la Palabra eterna', '«Miren la higuera y todos los árboles: cuando ven que brotan, saben que el verano está cerca... El cielo y la tierra pasarán, pero mis palabras no pasarán.»'),
  ('Lc 21,34-36', 'biblia', 'Lucas 21, 34-36', 'Nuevo Testamento · Vigilancia y oración constante', '«Tengan cuidado de no dejarse aturdir por los excesos, la embriaguez y las preocupaciones de la vida... Estén prevenidos y oren incesantemente.»'),
  ('Lc 22,19-20', 'biblia', 'Lucas 22, 19-20 (Institución de la Eucaristía)', 'Nuevo Testamento · La Última Cena', '«Luego tomó el pan, dio gracias, lo partió y lo dio a sus discípulos, diciendo: "Esto es mi Cuerpo, que se entrega por ustedes. Hagan esto en memoria mía." Después hizo lo mismo con la copa.»'),
  ('Lc 22,42', 'biblia', 'Lucas 22, 42', 'Nuevo Testamento · Oración de Jesús en Getsemaní', '«Padre, si quieres, aleja de mí este cáliz; pero que no se haga mi voluntad, sino la tuya.»'),
  ('Lc 23,26', 'biblia', 'Lucas 23, 26', 'Nuevo Testamento · Simón de Cirene', '«Mientras lo llevaban, detuvieron a un tal Simón de Cirene, que volvía del campo, y lo cargaron con la cruz, para que la llevara detrás de Jesús.»'),
  ('Lc 24,27-35', 'biblia', 'Lucas 24, 27-35 (Los discípulos de Emaús)', 'Nuevo Testamento · Palabra y Fracción del Pan', '«Les explicó lo que se refería a Él en todas las Escrituras... Y cuando estuvo a la mesa con ellos, tomó el pan, pronunció la bendición, lo partió y se lo dio. Entonces se les abrieron los ojos y lo reconocieron.»'),
  ('Lc 24,30-35', 'biblia', 'Lucas 24, 30-35', 'Nuevo Testamento · Reconocido al partir el pan', '«Al estar sentado a la mesa con ellos, tomó el pan, pronunció la bendición, lo partió y se lo dio. Entonces se les abrieron los ojos y lo reconocieron... "¿No ardía acaso nuestro corazón mientras nos explicaba las Escrituras?"»'),
  ('Jn 1,14', 'biblia', 'Juan 1, 14 (La Encarnación)', 'Nuevo Testamento · Prólogo de san Juan', '«Y la Palabra se hizo carne y habitó entre nosotros. Y nosotros hemos visto su gloria, la gloria que recibe del Padre como Hijo único, lleno de gracia y de verdad.»'),
  ('Jn 1,16', 'biblia', 'Juan 1, 16', 'Nuevo Testamento · Plenitud de la gracia', '«De su plenitud todos nosotros hemos participado y hemos recibido gracia sobre gracia.»'),
  ('Jn 1,39', 'biblia', 'Juan 1, 39', 'Nuevo Testamento · Primeros discípulos', '«"Vengan y lo verán", les dijo Jesús. Fueron, vieron dónde vivía y se quedaron con Él aquel día.»'),
  ('Jn 2,5', 'biblia', 'Juan 2, 5', 'Nuevo Testamento · Las bodas de Caná', '«Su madre dijo a los sirvientes: "Hagan todo lo que él les diga."»'),
  ('Jn 3,5', 'biblia', 'Juan 3, 5', 'Nuevo Testamento · Renacer del agua y del Espíritu', '«Jesús le respondió: "Te aseguro que el que no nace del agua y del Espíritu no puede entrar en el Reino de Dios."»'),
  ('Jn 6,31-35', 'biblia', 'Juan 6, 31-35', 'Nuevo Testamento · El verdadero Pan del cielo', '«Jesús les dijo: "Yo soy el pan de vida. El que viene a mí jamás tendrá hambre; el que cree en mí jamás tendrá sed."»'),
  ('Jn 6,51', 'biblia', 'Juan 6, 51 (Discurso del Pan de Vida)', 'Nuevo Testamento · Promesa de la Eucaristía', '«Yo soy el pan vivo bajado del cielo. El que coma de este pan vivirá eternamente, y el pan que yo daré es mi carne para la vida del mundo.»'),
  ('Jn 6,68', 'biblia', 'Juan 6, 68', 'Nuevo Testamento · Palabras de vida eterna', '«Simón Pedro le respondió: "Señor, ¿a quién iremos? Tú tienes palabras de vida eterna."»'),
  ('Jn 8,12', 'biblia', 'Juan 8, 12', 'Nuevo Testamento · Cristo, Luz del mundo', '«Jesús les habló de nuevo diciendo: "Yo soy la luz del mundo. El que me sigue no andará en tinieblas, sino que tendrá la luz de la Vida."»'),
  ('Jn 10,11', 'biblia', 'Juan 10, 11-14 (El Buen Pastor)', 'Nuevo Testamento · Evangelio según san Juan', '«Yo soy el buen Pastor. El buen Pastor da su vida por las ovejas... Yo conozco a mis ovejas, y mis ovejas me conocen a mí.»'),
  ('Jn 10,30', 'biblia', 'Juan 10, 30', 'Nuevo Testamento · Unidad del Hijo con el Padre', '«El Padre y yo somos una sola cosa.»'),
  ('Jn 11,25-44', 'biblia', 'Juan 11, 25-44 (Resurrección de Lázaro)', 'Nuevo Testamento · Milagros de Jesús', '«Jesús le dijo: "Yo soy la Resurrección y la Vida. El que cree en mí, aunque muera, vivirá."... Y gritó con voz fuerte: "¡Lázaro, sal afuera!" El muerto salió.»'),
  ('Jn 13,12-15', 'biblia', 'Juan 13, 12-15 (El lavatorio de los pies)', 'Nuevo Testamento · La Última Cena', '«Después de haberles lavado los pies, les dijo: "Les he dado el ejemplo, para que hagan lo mismo que yo hice con ustedes."»'),
  ('Jn 15,1-8', 'biblia', 'Juan 15, 1-8 (La Vid y los sarmientos)', 'Nuevo Testamento · Discurso de despedida', '«Yo soy la vid, ustedes los sarmientos. El que permanece en mí, y yo en él, da mucho fruto, porque separados de mí, nada pueden hacer.»'),
  ('Jn 15,13', 'biblia', 'Juan 15, 13', 'Nuevo Testamento · El amor más grande', '«No hay amor más grande que dar la vida por los amigos.»'),
  ('Jn 15,15', 'biblia', 'Juan 15, 15', 'Nuevo Testamento · Amistad con Cristo', '«Ya no los llamo servidores... los llamo amigos, porque les he dado a conocer todo lo que oí de mi Padre.»'),
  ('Jn 17,21', 'biblia', 'Juan 17, 21 (Oración sacerdotal de Jesús)', 'Nuevo Testamento · Unidad de los creyentes', '«Que todos sean uno: como tú, Padre, estás en mí y yo en ti, que también ellos sean uno en nosotros, para que el mundo crea que tú me enviaste.»'),
  ('Jn 19,25-27', 'biblia', 'Juan 19, 25-27 (María al pie de la cruz)', 'Nuevo Testamento · Maternidad espiritual de María', '«Jesús, al ver a su Madre y cerca de ella al discípulo a quien amaba, dijo a su Madre: "Mujer, aquí tienes a tu hijo." Luego dijo al discípulo: "Aquí tienes a tu madre."»'),
  ('Jn 20,11-18', 'biblia', 'Juan 20, 11-18 (Aparición a María Magdalena)', 'Nuevo Testamento · Resurrección del Señor', '«Jesús le dijo: "¡María!" Ella lo reconoció y le dijo en hebreo: "¡Rabboni!", que quiere decir "Maestro". Jesús le dijo: "Ve a decir a mis hermanos: Subo hacia mi Padre y el Padre de ustedes."»'),
  ('Jn 20,22-23', 'biblia', 'Juan 20, 22-23 (Institución de la Reconciliación)', 'Nuevo Testamento · El perdón de los pecados', '«Sopló sobre ellos y les dijo: "Reciban el Espíritu Santo. Los pecados serán perdonados a los que ustedes se los perdonen, y serán retenidos a los que ustedes se los retengan."»'),
  ('Jn 20,23', 'biblia', 'Juan 20, 23', 'Nuevo Testamento · Ministerio de la reconciliación', '«Los pecados serán perdonados a los que ustedes se los perdonen, y serán retenidos a los que ustedes se los retengan.»'),
  ('Jn 20,28', 'biblia', 'Juan 20, 28', 'Nuevo Testamento · Profesión de fe de santo Tomás', '«Tomás le respondió: "¡Señor mío y Dios mío!"»'),
  ('Hch 1,14', 'biblia', 'Hechos de los Apóstoles 1, 14', 'Nuevo Testamento · María en oración con los apóstoles', '«Todos ellos, íntimamente unidos, se dedicaban a la oración, en compañía de algunas mujeres, de María, la madre de Jesús, y de sus hermanos.»'),
  ('Hch 2,1', 'biblia', 'Hechos de los Apóstoles 2, 1', 'Nuevo Testamento · Día de Pentecostés', '«Al llegar el día de Pentecostés, estaban todos reunidos en el mismo lugar.»'),
  ('Hch 2,3-4', 'biblia', 'Hechos de los Apóstoles 2, 3-4', 'Nuevo Testamento · Lenguas de fuego', '«Se les aparecieron unas lenguas como de fuego que se repartieron y se posaron sobre cada uno de ellos. Todos quedaron llenos del Espíritu Santo.»'),
  ('Hch 7,55-60', 'biblia', 'Hechos de los Apóstoles 7, 55-60 (Martirio de san Esteban)', 'Nuevo Testamento · Primer mártir cristiano', '«Esteban, lleno del Espíritu Santo, miró al cielo... Luego cayó de rodillas y gritó en voz alta: "Señor, no les tengas en cuenta este pecado." Y dicho esto, se durmió en el Señor.»'),
  ('Hch 8,14-17', 'biblia', 'Hechos de los Apóstoles 8, 14-17', 'Nuevo Testamento · Imposición de manos y Espíritu Santo', '«Pedro y Juan oraron por ellos para que recibieran el Espíritu Santo... Entonces les impusieron las manos y recibieron el Espíritu Santo.»'),
  ('Hch 9,1-6', 'biblia', 'Hechos de los Apóstoles 9, 3-6 (Conversión de san Pablo)', 'Nuevo Testamento · Camino de Damasco', '«Al acercarse a Damasco, una luz del cielo lo envolvió... Oyó una voz que le decía: "Saulo, Saulo, ¿por qué me persigues?" Él preguntó: "¿Quién eres, Señor?" Y le respondió: "Yo soy Jesús, a quien tú persigues."»'),
  ('Hch 11,26', 'biblia', 'Hechos de los Apóstoles 11, 26', 'Nuevo Testamento · El nombre de cristianos', '«En Antioquía fue donde por primera vez los discípulos recibieron el nombre de "cristianos".»'),
  ('Hch 15,28', 'biblia', 'Hechos de los Apóstoles 15, 28 (Concilio de Jerusalén)', 'Nuevo Testamento · Comunión apostólica', '«El Espíritu Santo y nosotros mismos hemos decidido no imponerles ninguna carga más que las indispensables.»'),
  ('Rm 6,4', 'biblia', 'Romanos 6, 4', 'Nuevo Testamento · Bautizados en la Pascua de Cristo', '«Por el bautismo fuimos sepultados con Él en la muerte, para que así como Cristo resucitó por la gloria del Padre, también nosotros llevemos una vida nueva.»'),
  ('Rm 10,14-15', 'biblia', 'Romanos 10, 14-15', 'Nuevo Testamento · El anuncio de la Palabra', '«¿Cómo creerán en Aquel a quien no han oído? ¿Cómo oirán sin alguien que les predique? ¿Y cómo predicarán si no son enviados?»'),
  ('Rm 10,17', 'biblia', 'Romanos 10, 17', 'Nuevo Testamento · La fe nace de la escucha', '«Así pues, la fe nace de la predicación, y la predicación se realiza en virtud de la Palabra de Cristo.»'),
  ('Rm 15,13', 'biblia', 'Romanos 15, 13', 'Nuevo Testamento · Dios de la esperanza', '«Que el Dios de la esperanza los llene de alegría y de paz en la fe, para que abunden en la esperanza por la fuerza del Espíritu Santo.»'),
  ('1 Cor 3,7', 'biblia', 'Primera carta a los Corintios 3, 7', 'Nuevo Testamento · Dios da el crecimiento', '«De modo que ni el que planta ni el que riega son nada, sino solo Dios, que hace crecer.»'),
  ('1 Cor 10,31', 'biblia', 'Primera carta a los Corintios 10, 31', 'Nuevo Testamento · Todo para gloria de Dios', '«Ya sea que coman, que beban o que hagan cualquier otra cosa, háganlo todo para gloria de Dios.»'),
  ('1 Cor 11,27-29', 'biblia', 'Primera carta a los Corintios 11, 27-29', 'Nuevo Testamento · Disposición para la Comunión', '«Examínese cada uno a sí mismo antes de comer este pan y beber esta copa, porque el que come y bebe sin discernir el Cuerpo, come y bebe su propia condenación.»'),
  ('1 Cor 12,7', 'biblia', 'Primera carta a los Corintios 12, 7', 'Nuevo Testamento · Los carismas para el bien común', '«A cada uno se le otorga la manifestación del Espíritu para el bien común.»'),
  ('1 Cor 12,31', 'biblia', 'Primera carta a los Corintios 12, 31', 'Nuevo Testamento · El camino más excelente', '«Aspiren a los dones más elevados. Y ahora les voy a mostrar un camino incomparablemente superior.»'),
  ('1 Cor 15,14', 'biblia', 'Primera carta a los Corintios 15, 14', 'Nuevo Testamento · Centralidad de la Resurrección', '«Si Cristo no resucitó, es vana nuestra predicación y vana también la fe de ustedes.»'),
  ('2 Cor 1,21-22', 'biblia', 'Segunda carta a los Corintios 1, 21-22', 'Nuevo Testamento · El sello del Espíritu', '«El que nos afianza con ustedes en Cristo y nos ha ungido es Dios, el cual nos marcó con su sello y puso las arras del Espíritu en nuestros corazones.»'),
  ('Gál 4,4-5', 'biblia', 'Gálatas 4, 4-5', 'Nuevo Testamento · Plenitud de los tiempos', '«Cuando se cumplió el tiempo establecido, Dios envió a su Hijo, nacido de una mujer y sujeto a la Ley, para redimir a los que estaban sometidos a la Ley y hacernos hijos adoptivos.»'),
  ('Ef 4,3-4', 'biblia', 'Efesios 4, 3-4', 'Nuevo Testamento · Unidad del Cuerpo de Cristo', '«Esfuércense por mantener la unidad del Espíritu mediante el vínculo de la paz. Hay un solo Cuerpo y un solo Espíritu.»'),
  ('Ef 5,31-32', 'biblia', 'Efesios 5, 31-32', 'Nuevo Testamento · El gran sacramento del Matrimonio', '«Por eso el hombre dejará a su padre y a su madre para unirse a su mujer, y los dos serán una sola carne. Este es un gran misterio: y yo digo que se refiere a Cristo y a la Iglesia.»'),
  ('Flp 4,4', 'biblia', 'Filipenses 4, 4', 'Nuevo Testamento · Alegría cristiana', '«Alégrense siempre en el Señor. Vuelvo a insistir, ¡alégrense!»'),
  ('Col 3,1-2', 'biblia', 'Colosenses 3, 1-2', 'Nuevo Testamento · Buscar los bienes de lo alto', '«Ya que ustedes han resucitado con Cristo, busquen los bienes del cielo, donde Cristo está sentado a la derecha de Dios.»'),
  ('Col 3,23', 'biblia', 'Colosenses 3, 23', 'Nuevo Testamento · Santificar el trabajo cotidiano', '«Todo lo que hagan, háganlo de buen grado, como para el Señor y no para los hombres.»'),
  ('1 Tes 5,17', 'biblia', 'Primera carta a los Tesalonicenses 5, 17', 'Nuevo Testamento · Oración continua', '«Oren sin cesar. Den gracias a Dios en toda ocasión: esto es lo que Dios quiere de todos ustedes en Cristo Jesús.»'),
  ('1 Tim 2,1-2', 'biblia', 'Primera carta a Timoteo 2, 1-2', 'Nuevo Testamento · Oración por la paz civil', '«Ante todo, te recomiendo que se hagan peticiones, oraciones, súplicas y acciones de gracias por todos los hombres... para que podamos llevar una vida tranquila y en paz.»'),
  ('1 Tim 2,4', 'biblia', 'Primera carta a Timoteo 2, 4', 'Nuevo Testamento · Voluntad salvífica universal', '«Dios, nuestro Salvador, quiere que todos los hombres se salven y lleguen al conocimiento de la verdad.»'),
  ('1 Tim 3,1-13', 'biblia', 'Primera carta a Timoteo 3, 1-8', 'Nuevo Testamento · Los ministerios en la Iglesia', '«El que aspira a presidir la comunidad (episcopado) desea una noble función... Asimismo, los diáconos deben ser hombres respetables y sinceros.»'),
  ('2 Tim 1,14', 'biblia', 'Segunda carta a Timoteo 1, 14', 'Nuevo Testamento · Custodiar el depósito de la fe', '«Conserva el precioso depósito que se te ha confiado, con la ayuda del Espíritu Santo que habita en nosotros.»'),
  ('2 Tim 3,16', 'biblia', 'Segunda carta a Timoteo 3, 16', 'Nuevo Testamento · Inspiración de las Escrituras', '«Toda Escritura está inspirada por Dios y es útil para enseñar, para argüir, para corregir y para educar en la justicia.»'),
  ('Sant 2,14-17', 'biblia', 'Santiago 2, 14-17', 'Nuevo Testamento · La fe viva y las obras', '«¿De qué le sirve a uno, hermanos míos, decir que tiene fe, si no tiene obras?... Así también la fe, si no va acompañada de obras, está completamente muerta.»'),
  ('Sant 5,4', 'biblia', 'Santiago 5, 4', 'Nuevo Testamento · Justicia social y salario justo', '«El salario que ustedes han defraudado a los trabajadores que segaron sus campos está clamando, y los gritos de los segadores han llegado a los oídos del Señor.»'),
  ('Sant 5,14-15', 'biblia', 'Santiago 5, 14-15 (Unción de los Enfermos)', 'Nuevo Testamento · Oración y unción por los enfermos', '«¿Está enfermo alguno de ustedes? Llame a los presbíteros de la Iglesia, para que oren por él y lo unjan con aceite en el nombre del Señor. La oración de la fe salvará al enfermo.»'),
  ('1 P 2,9', 'biblia', 'Primera carta de san Pedro 2, 9', 'Nuevo Testamento · Sacerdocio común de los fieles', '«Ustedes son una raza elegida, un sacerdocio real, una nación santa, un pueblo adquirido para anunciar las maravillas de Aquel que los llamó de las tinieblas a su admirable luz.»'),
  ('2 P 1,4', 'biblia', 'Segunda carta de san Pedro 1, 4', 'Nuevo Testamento · Partícipes de la naturaleza divina', '«Dios nos ha concedido las preciosas y grandísimas promesas, para que por ellas lleguen a ser partícipes de la naturaleza divina.»'),
  ('1 Jn 1,9', 'biblia', 'Primera carta de san Juan 1, 9', 'Nuevo Testamento · Confesión y perdón', '«Si confesamos nuestros pecados, Él es fiel y justo para perdonarnos y purificarnos de toda maldad.»'),
  ('1 Jn 3,18', 'biblia', 'Primera carta de san Juan 3, 18', 'Nuevo Testamento · Amar con obras y de verdad', '«Hijos míos, no amemos solamente con la lengua y de palabra, sino con obras y de verdad.»'),
  ('Ap 1,9', 'biblia', 'Apocalipsis 1, 9', 'Nuevo Testamento · San Juan en Patmos', '«Yo, Juan, hermano de ustedes... me encontraba en la isla de Patmos, a causa de la Palabra de Dios y del testimonio de Jesús.»'),
  ('Ap 12,1', 'biblia', 'Apocalipsis 12, 1', 'Nuevo Testamento · La Mujer vestida de sol', '«Y apareció en el cielo un gran signo: una Mujer revestida del sol, con la luna bajo sus pies y una corona de doce estrellas en su cabeza.»'),
  ('Ap 14,1-5', 'biblia', 'Apocalipsis 14, 1-5', 'Nuevo Testamento · El Cordero sobre el monte Sión', '«Vi al Cordero que estaba de pie sobre el monte Sión, acompañado de ciento cuarenta y cuatro mil personas... Son los que siguen al Cordero adondequiera que va; en su boca no se halló mentira.»'),
  ('Ap 14,14-19', 'biblia', 'Apocalipsis 14, 14-16', 'Nuevo Testamento · La cosecha de la tierra', '«Miré, y vi una nube blanca, y sentado sobre la nube, alguien semejante a un Hijo de hombre, con una corona de oro en la cabeza... porque ha llegado la hora de cosechar.»'),
  ('Ap 15,1-4', 'biblia', 'Apocalipsis 15, 2-4', 'Nuevo Testamento · Cántico de Moisés y del Cordero', '«Cantaban el cántico de Moisés y el cántico del Cordero, diciendo: "¡Grandes y admirables son tus obras, Señor, Dios todopoderoso! Justos y verdaderos son tus caminos, Rey de las naciones."»'),
  ('Ap 18,21', 'biblia', 'Apocalipsis 18, 21', 'Nuevo Testamento · Caída de Babilonia', '«Un ángel poderoso levantó una piedra como una gran rueda de molino y la arrojó al mar, diciendo: "Así será arrojada con ímpetu Babilonia, la gran ciudad, y nunca más volverá a existir."»'),
  ('Ap 19,9', 'biblia', 'Apocalipsis 19, 9', 'Nuevo Testamento · Banquete de bodas del Cordero', '«El ángel me dijo: "Escribe: ¡Felices los que han sido invitados al banquete de bodas del Cordero!"»'),
  ('Ap 21,1-2', 'biblia', 'Apocalipsis 21, 1-2', 'Nuevo Testamento · Cielo nuevo y tierra nueva', '«Después vi un cielo nuevo y una tierra nueva... Y vi descender del cielo, desde junto a Dios, a la Ciudad Santa, la nueva Jerusalén, engalanada como una novia para su esposo.»'),
  ('Ap 22,1-7', 'biblia', 'Apocalipsis 22, 1-2', 'Nuevo Testamento · El río de agua viva', '«El ángel me mostró un río de agua viva, límpido como el cristal, que brotaba del trono de Dios y del Cordero... Las hojas del árbol sirven para la curación de las naciones.»'),
  ('Ap 22,20', 'biblia', 'Apocalipsis 22, 20', 'Nuevo Testamento · Conclusión de la Escritura', '«El que atestigua estas cosas dice: "Sí, volveré pronto." ¡Amén! ¡Ven, Señor Jesús!»'),
  ('IGMR 60', 'igmr', 'Instrucción General del Misal Romano · N.° 60', 'Liturgia de la Palabra · El Evangelio', 'La lectura del Evangelio constituye el punto culminante de la Liturgia de la Palabra. La misma liturgia enseña que se le debe tributar máxima veneración, y el pueblo con sus aclamaciones reconoce y confiesa que Cristo está presente y le habla.'),
  ('IGMR 309', 'igmr', 'Instrucción General del Misal Romano · N.° 309', 'Disposición del templo · El Ambón', 'La dignidad de la Palabra de Dios exige que en la iglesia haya un sitio conveniente para anunciarla, hacia el cual durante la Liturgia de la Palabra se vuelva espontáneamente la atención de los fieles. Conviene que este sitio sea un ambón estable.'),
  ('CIC 11', 'cic', 'Catecismo de la Iglesia Católica · N.° 11', 'Prólogo · Finalidad del Catecismo', 'Este Catecismo tiene por fin presentar una exposición orgánica y sintética de los contenidos esenciales y fundamentales de la doctrina católica, tanto sobre la fe como sobre la moral, a la luz del Concilio Vaticano II y del conjunto de la Tradición.'),
  ('CIC 103', 'cic', 'Catecismo de la Iglesia Católica · N.° 103', 'Primera Parte · Veneración de la Sagrada Escritura', 'La Iglesia siempre ha venerado la Sagrada Escritura como lo ha hecho con el Cuerpo del Señor. No cesa de presentar a los fieles el Pan de vida que se distribuye en la mesa de la Palabra de Dios y del Cuerpo de Cristo.'),
  ('CIC 104', 'cic', 'Catecismo de la Iglesia Católica · N.° 104', 'Primera Parte · La Palabra viva de Dios', 'En la Sagrada Escritura, la Iglesia encuentra sin cesar su alimento y su fuerza, porque en ella no recibe solamente una palabra humana, sino lo que es realmente: la Palabra de Dios.'),
  ('CIC 120', 'cic', 'Catecismo de la Iglesia Católica · N.° 120', 'Primera Parte · El Canon de las Escrituras', 'La Tradición apostólica hizo discernir a la Iglesia qué escritos constituyen la lista de los Libros Santos: 46 para el Antiguo Testamento y 27 para el Nuevo Testamento (73 libros en total).'),
  ('CIC 133', 'cic', 'Catecismo de la Iglesia Católica · N.° 133', 'Primera Parte · La Escritura en la vida de la Iglesia', 'La Iglesia exhorta con insistencia a todos los fieles a que aprendan el sublime conocimiento de Jesucristo con la lectura frecuente de las divinas Escrituras, porque «desconocer la Escritura es desconocer a Cristo» (san Jerónimo).'),
  ('CIC 206', 'cic', 'Catecismo de la Iglesia Católica · N.° 206', 'Primera Parte · Revelación del Nombre de Dios', 'Al revelar su nombre misterioso de YHWH («Yo soy el que soy»), Dios dice quién es y con qué nombre se le debe llamar. Este Nombre divino es misterioso como Dios es misterio, pero a la vez revela su fidelidad cercana a su pueblo.'),
  ('CIC 239', 'cic', 'Catecismo de la Iglesia Católica · N.° 239', 'Primera Parte · Dios es Padre', 'Al designar a Dios con el nombre de «Padre», el lenguaje de la fe indica principalmente que Dios es origen primero de todo y autoridad trascendente, y que es al mismo tiempo bondad y solicitud amorosa para todos sus hijos.'),
  ('CIC 332', 'cic', 'Catecismo de la Iglesia Católica · N.° 332', 'Primera Parte · Los ángeles en la historia de la salvación', 'Desde la creación y a lo largo de toda la historia de la salvación, encontramos a los ángeles anunciando de lejos o de cerca esta salvación y sirviendo al designio divino de su realización.'),
  ('CIC 355', 'cic', 'Catecismo de la Iglesia Católica · N.° 355', 'Primera Parte · El hombre a imagen de Dios', '«Dios creó al hombre a su imagen, a imagen de Dios lo creó, varón y mujer los creó» (Gn 1,27). El hombre ocupa un lugar único en la creación: está creado a imagen de Dios y llamado a la comunión con Él.'),
  ('CIC 410', 'cic', 'Catecismo de la Iglesia Católica · N.° 410', 'Primera Parte · El Protoevangelio', 'Tras la caída, el hombre no fue abandonado por Dios. Al contrario, Dios lo llama y le anuncia de modo misterioso la victoria sobre el mal y el levantamiento de su caída en Génesis 3,15, llamado el «Protoevangelio».'),
  ('CIC 430', 'cic', 'Catecismo de la Iglesia Católica · N.° 430', 'Primera Parte · El nombre de Jesús', 'Jesús quiere decir en hebreo «Dios salva». En la anunciación, el ángel Gabriel le dio como nombre propio el nombre de Jesús, que expresa a la vez su identidad y su misión.'),
  ('CIC 448', 'cic', 'Catecismo de la Iglesia Católica · N.° 448', 'Primera Parte · Jesús es el Señor', 'En los Evangelios, confesar a Jesús como «Señor» —como hace Tomás al exclamar «¡Señor mío y Dios mío!»— expresa la fe en su divinidad y su soberanía sobre toda la creación.'),
  ('CIC 451', 'cic', 'Catecismo de la Iglesia Católica · N.° 451', 'Primera Parte · Marana tha', 'La oración cristiana está marcada por el título «Señor», tanto en la invitación a orar como en el grito de esperanza y de espera de la Iglesia: «¡Marana tha! ¡Ven, Señor Jesús!»'),
  ('CIC 452', 'cic', 'Catecismo de la Iglesia Católica · N.° 452', 'Primera Parte · Resumen sobre el Nombre de Cristo', 'El nombre de Jesús significa «Dios salva». El niño nacido de la Virgen María se llama Jesús porque Él salvará a su pueblo de sus pecados.'),
  ('CIC 460', 'cic', 'Catecismo de la Iglesia Católica · N.° 460', 'Primera Parte · ¿Por qué el Verbo se hizo carne?', 'El Verbo se encarnó para hacernos «partícipes de la naturaleza divina» (2 P 1,4). Como afirmó san Atanasio: «El Hijo de Dios se hizo hombre para hacernos Dios».'),
  ('CIC 461', 'cic', 'Catecismo de la Iglesia Católica · N.° 461', 'Primera Parte · La Encarnación', 'La Iglesia llama «Encarnación» al hecho de que el Hijo de Dios haya asumido una naturaleza humana para llevar a cabo por ella nuestra salvación: «Y la Palabra se hizo carne, y habitó entre nosotros».'),
  ('CIC 465', 'cic', 'Catecismo de la Iglesia Católica · N.° 465', 'Primera Parte · Concilio de Nicea (325)', 'El primer Concilio Ecuménico de Nicea confesó en su Credo que el Hijo de Dios es «engendrado, no creado, de la misma naturaleza (consustancial) que el Padre», afirmando plenamente la divinidad de Cristo.'),
  ('CIC 467', 'cic', 'Catecismo de la Iglesia Católica · N.° 467', 'Primera Parte · Concilio de Calcedonia (451)', 'El Concilio de Calcedonia confesó un solo y mismo Hijo, nuestro Señor Jesucristo, perfecto en la divinidad y perfecto en la humanidad, reconocido en dos naturalezas sin confusión, sin cambio, sin división ni separación.'),
  ('CIC 490-499', 'cic', 'Catecismo de la Iglesia Católica · N.° 490-499', 'Primera Parte · Los dogmas marianos', 'La Iglesia honra a María con los dogmas de la Maternidad Divina (Éfeso, 431), la Virginidad Perpetua, la Inmaculada Concepción (1854) y la Asunción en cuerpo y alma al cielo (1950), todos iluminados por el misterio de Cristo.'),
  ('CIC 491', 'cic', 'Catecismo de la Iglesia Católica · N.° 491', 'Primera Parte · La Inmaculada Concepción', 'La santísima Virgen María fue preservada inmune de toda mancha de pecado original en el primer instante de su concepción por singular gracia y privilegio de Dios todopoderoso, en atención a los méritos de Jesucristo Salvador.'),
  ('CIC 494', 'cic', 'Catecismo de la Iglesia Católica · N.° 494', 'Primera Parte · El «Hágase» de María', 'Al anuncio de que dará a luz al Hijo del Altísimo, María respondió con la obediencia de la fe: «Hágase en mí según tu palabra». Así dio su consentimiento libre a la Palabra de Dios y se convirtió en Madre de Jesús.'),
  ('CIC 495', 'cic', 'Catecismo de la Iglesia Católica · N.° 495', 'Primera Parte · María, Madre de Dios (Theotokos)', 'En efecto, aquel que María concibió como hombre, por obra del Espíritu Santo, no es otro que el Hijo eterno del Padre, la segunda persona de la Santísima Trinidad. La Iglesia confiesa que María es verdaderamente Madre de Dios (Theotokos).'),
  ('CIC 497', 'cic', 'Catecismo de la Iglesia Católica · N.° 497', 'Primera Parte · Concepción virginal', 'Los relatos evangélicos presentan la concepción virginal de Jesús como una obra divina que sobrepasa toda comprensión y toda posibilidad humana, cumpliendo la profecía de Isaías sobre Emmanuel, «Dios con nosotros».'),
  ('CIC 499', 'cic', 'Catecismo de la Iglesia Católica · N.° 499', 'Primera Parte · María «siempre Virgen»', 'La profundización de la fe en la maternidad virginal ha llevado a la Iglesia a confesar la virginidad real y perpetua de María incluso en el parto del Hijo de Dios hecho hombre.'),
  ('CIC 525', 'cic', 'Catecismo de la Iglesia Católica · N.° 525', 'Primera Parte · El misterio de Navidad', 'Jesús nació en la humildad de un establo, de una familia pobre; unos sencillos pastores son los primeros testigos del acontecimiento. En esta pobreza se manifiesta la gloria del cielo.'),
  ('CIC 541', 'cic', 'Catecismo de la Iglesia Católica · N.° 541', 'Primera Parte · El anuncio del Reino de Dios', 'Para hacer la voluntad del Padre, Cristo inauguró el Reino de los cielos en la tierra. La Iglesia es el Reino de Cristo ya presente en misterio.'),
  ('CIC 545', 'cic', 'Catecismo de la Iglesia Católica · N.° 545', 'Primera Parte · Jesús invita a los pecadores', 'Jesús invita a los pecadores a la mesa del Reino: «No he venido a llamar a justos, sino a pecadores», llamándolos a la conversión y mostrándoles la misericordia infinita del Padre.'),
  ('CIC 546', 'cic', 'Catecismo de la Iglesia Católica · N.° 546', 'Primera Parte · Las parábolas del Reino', 'Jesús invita a entrar en el Reino a través de las parábolas, rasgo típico de su enseñanza. Por medio de ellas invita al banquete del Reino, pero exige también una elección radical y acogida generosa de la Palabra.'),
  ('CIC 547', 'cic', 'Catecismo de la Iglesia Católica · N.° 547', 'Primera Parte · Los signos del Reino', 'Jesús acompaña sus palabras con numerosos milagros, prodigios y signos que manifiestan que el Reino está presente en Él y atestiguan que es el Mesías anunciado.'),
  ('CIC 586', 'cic', 'Catecismo de la Iglesia Católica · N.° 586', 'Primera Parte · Jesús y el Templo', 'Jesús identificó su propio cuerpo con el Templo definitivo en el que habita Dios entre los hombres, anunciando que el templo de piedra daría paso al culto en Espíritu y en verdad.'),
  ('CIC 609', 'cic', 'Catecismo de la Iglesia Católica · N.° 609', 'Primera Parte · Ofrenda libre de Jesús', 'Al abrazar en su corazón humano el amor del Padre hacia los hombres, Jesús los amó hasta el extremo, ofreciendo libremente su vida por la salvación de todos.'),
  ('CIC 618', 'cic', 'Catecismo de la Iglesia Católica · N.° 618', 'Primera Parte · Participación en la Cruz de Cristo', 'La Cruz es el único sacrificio de Cristo, único mediador entre Dios y los hombres. Cristo asocia a sus discípulos a su ofrenda redentora llamándolos a cargar con su cruz y seguirlo.'),
  ('CIC 640', 'cic', 'Catecismo de la Iglesia Católica · N.° 640', 'Primera Parte · El sepulcro vacío y la Resurrección', 'La Resurrección de Jesús es la verdad culminante de nuestra fe en Cristo, creída y vivida por la primera comunidad cristiana como verdad central.'),
  ('CIC 641', 'cic', 'Catecismo de la Iglesia Católica · N.° 641', 'Primera Parte · Las primeras testigos de la Resurrección', 'María Magdalena y las santas mujeres que iban a embalsamar el cuerpo de Jesús fueron las primeras en encontrar al Resucitado y convertirse en mensajeras de la Resurrección para los propios apóstoles.'),
  ('CIC 668', 'cic', 'Catecismo de la Iglesia Católica · N.° 668', 'Primera Parte · Cristo reina y vendrá en gloria', 'Cristo es Señor del cosmos y de la historia. En Él la historia humana y toda la creación encuentran su recapitulación y plenitud en su venida gloriosa.'),
  ('CIC 672', 'cic', 'Catecismo de la Iglesia Católica · N.° 672', 'Primera Parte · El tiempo de la vigilancia', 'El tiempo presente es el tiempo del Espíritu y del testimonio, pero es también un tiempo marcado por la espera vigilante y la prueba mientras aguardamos la venida del Señor.'),
  ('CIC 675', 'cic', 'Catecismo de la Iglesia Católica · N.° 675', 'Primera Parte · Discernimiento ante la prueba', 'Antes del advenimiento de Cristo, la Iglesia deberá pasar por una prueba final que sacudirá la fe de numerosos creyentes, llamando a mantenerse fieles a la verdad del Evangelio sin dejarse engañar.'),
  ('CIC 677', 'cic', 'Catecismo de la Iglesia Católica · N.° 677', 'Primera Parte · El triunfo de Dios', 'La Iglesia entrará en la gloria del Reino a través de la Pascua siguiendo a su Señor. El triunfo definitivo de Dios sobre el mal se realizará en el juicio final.'),
  ('CIC 679', 'cic', 'Catecismo de la Iglesia Católica · N.° 679', 'Primera Parte · Cristo, Señor de la vida eterna', 'Cristo es Señor de la vida eterna. El pleno derecho de juzgar definitivamente las obras y los corazones de los hombres pertenece a Él como Redentor del mundo.'),
  ('CIC 754', 'cic', 'Catecismo de la Iglesia Católica · N.° 754', 'Primera Parte · La Iglesia, redil del Buen Pastor', 'La Iglesia es el redil cuya puerta única y necesaria es Cristo, y el rebaño cuyo Pastor será el mismo Dios, guiado y alimentado por Cristo, el Buen Pastor que da su vida por las ovejas.'),
  ('CIC 755', 'cic', 'Catecismo de la Iglesia Católica · N.° 755', 'Primera Parte · La Iglesia, viña de Dios', 'La Iglesia es labranza o campo de Dios. La verdadera vid es Cristo, que da vida y fecundidad a los sarmientos, es decir, a nosotros, que por medio de la Iglesia permanecemos en Él.'),
  ('CIC 795', 'cic', 'Catecismo de la Iglesia Católica · N.° 795', 'Primera Parte · Cristo y la Iglesia, el Cristo total', 'Cristo y la Iglesia forman el «Cristo total». La Iglesia es una con Cristo; por eso el Señor dijo a Saulo camino de Damasco: «¿Por qué me persigues?»'),
  ('CIC 799-800', 'cic', 'Catecismo de la Iglesia Católica · N.° 799-800', 'Primera Parte · Los carismas en la Iglesia', 'Extraordinarios o sencillos y humildes, los carismas son gracias del Espíritu Santo que tienen directa o indirectamente una utilidad eclesial, ordenados a la edificación de la Iglesia y al bien de los hombres, en comunión con los pastores.'),
  ('CIC 813', 'cic', 'Catecismo de la Iglesia Católica · N.° 813', 'Primera Parte · La Iglesia es Una', 'La Iglesia es una por su origen en la Santísima Trinidad, por su Fundador Jesucristo y por su alma, el Espíritu Santo. La unidad es de la esencia de la Iglesia.'),
  ('CIC 817', 'cic', 'Catecismo de la Iglesia Católica · N.° 817', 'Primera Parte · Las heridas a la unidad', 'De hecho, en esta única Iglesia de Dios aparecieron ya desde los primeros tiempos divisiones; las comunidades separadas son llamadas a la conversión y al diálogo ecuménico para restablecer la plena comunión.'),
  ('CIC 828', 'cic', 'Catecismo de la Iglesia Católica · N.° 828', 'Primera Parte · Los santos, modelos e intercesores', 'Al canonizar a ciertos fieles, la Iglesia reconoce el poder del Espíritu de santidad y sostiene la esperanza de los creyentes proponiéndolos como modelos e intercesores.'),
  ('CIC 830', 'cic', 'Catecismo de la Iglesia Católica · N.° 830', 'Primera Parte · ¿Qué significa «Católica»?', 'La palabra «católica» significa «universal» en el sentido de «según la totalidad». La Iglesia es católica porque en ella está presente Cristo y porque ha sido enviada a la totalidad del género humano.'),
  ('CIC 849', 'cic', 'Catecismo de la Iglesia Católica · N.° 849', 'Primera Parte · Mandato misionero', 'La Iglesia, enviada por Dios a las gentes para ser sacramento universal de salvación, se esfuerza en anunciar el Evangelio a todos los hombres obedeciendo el mandato de su Fundador.'),
  ('CIC 884', 'cic', 'Catecismo de la Iglesia Católica · N.° 884', 'Primera Parte · El Colegio Episcopal y los Concilios', 'El Colegio de los obispos ejerce de modo solemne el poder sobre toda la Iglesia en el Concilio Ecuménico, siempre en comunión con el Sucesor de Pedro, su Cabeza.'),
  ('CIC 900', 'cic', 'Catecismo de la Iglesia Católica · N.° 900', 'Primera Parte · El apostolado de los laicos', 'Los fieles laicos tienen el deber y el derecho de trabajar para que el mensaje divino de salvación sea conocido y recibido por todos los hombres en toda la tierra, individualmente o unidos en asociaciones y movimientos.'),
  ('CIC 905', 'cic', 'Catecismo de la Iglesia Católica · N.° 905', 'Primera Parte · Misión profética de los laicos', 'Los laicos cumplen su misión profética evangelizando, es decir, anunciando a Cristo con el testimonio de la vida y con la palabra en los ambientes cotidianos del mundo.'),
  ('CIC 916', 'cic', 'Catecismo de la Iglesia Católica · N.° 916', 'Primera Parte · La vida consagrada', 'El estado de vida consagrada manifiesta de modo especial la íntima naturaleza de la vocación cristiana y la aspiración de toda la Iglesia Esposa hacia la unión con su único Esposo.'),
  ('CIC 927', 'cic', 'Catecismo de la Iglesia Católica · N.° 927', 'Primera Parte · Órdenes y familias religiosas', 'Todos los religiosos, exentos o no, se cuentan entre los colaboradores del obispo diocesano en su misión pastoral, enriqueciendo la Iglesia con la diversidad de sus carismas de oración, estudio y servicio.'),
  ('CIC 931', 'cic', 'Catecismo de la Iglesia Católica · N.° 931', 'Primera Parte · Entrega a Dios y servicio a los hermanos', 'Quien por la vida consagrada se entrega a Dios amado sobre todas las cosas se ordena al servicio de Dios y al bien de la Iglesia en la misión, la educación, la contemplación y la caridad.'),
  ('CIC 963', 'cic', 'Catecismo de la Iglesia Católica · N.° 963', 'Primera Parte · María, Madre de la Iglesia', 'La Virgen María es reconocida y honrada como verdadera Madre de Dios y del Redentor, y al mismo tiempo es verdaderamente Madre de los miembros de Cristo, es decir, Madre de la Iglesia.'),
  ('CIC 964', 'cic', 'Catecismo de la Iglesia Católica · N.° 964', 'Primera Parte · María unida a Cristo en la Cruz', 'La unión de la Madre con el Hijo en la obra de la salvación se manifiesta desde la concepción virginal hasta la muerte de Cristo; al pie de la cruz, Jesús la entregó como Madre al discípulo amado.'),
  ('CIC 966', 'cic', 'Catecismo de la Iglesia Católica · N.° 966', 'Primera Parte · La Asunción de María', 'Finalmente, la Virgen Inmaculada, terminado el curso de su vida terrena, fue llevada en cuerpo y alma a la gloria del cielo y enaltecida por el Señor como Reina del universo.'),
  ('CIC 971', 'cic', 'Catecismo de la Iglesia Católica · N.° 971', 'Primera Parte · El culto a la Santísima Virgen', '«Me llamarán bienaventurada todas las generaciones». La piedad de la Iglesia hacia la Santísima Virgen es un elemento intrínseco del culto cristiano; es un culto especial de veneración, esencialmente distinto del culto de adoración debido solo a Dios.'),
  ('CIC 1040', 'cic', 'Catecismo de la Iglesia Católica · N.° 1040', 'Primera Parte · El Juicio Final', 'El Juicio Final sucederá cuando vuelva Cristo glorioso. Solo el Padre conoce el día y la hora; entonces conoceremos el sentido último de toda la obra de la creación y de la salvación.'),
  ('CIC 1042', 'cic', 'Catecismo de la Iglesia Católica · N.° 1042', 'Primera Parte · La esperanza de los cielos nuevos', 'Al fin de los tiempos el Reino de Dios llegará a su plenitud. Después del juicio universal, los justos reinarán para siempre con Cristo, glorificados en cuerpo y alma, y el universo mismo será renovado.'),
  ('CIC 1045', 'cic', 'Catecismo de la Iglesia Católica · N.° 1045', 'Primera Parte · La nueva Jerusalén', 'Para el hombre, esta consumación será la realización final de la unidad del género humano querida por Dios: la Ciudad Santa, la nueva Jerusalén, donde Dios enjugará toda lágrima.'),
  ('CIC 1062', 'cic', 'Catecismo de la Iglesia Católica · N.° 1062', 'Primera Parte · Significado de «Amén»', 'En hebreo, «amén» pertenece a la misma raíz que la palabra «creer». Esta raíz expresa la solidez, la fiabilidad, la fidelidad. Decir «Amén» significa «así es» y «creo firmemente».'),
  ('CIC 1094', 'cic', 'Catecismo de la Iglesia Católica · N.° 1094', 'Segunda Parte · Tipología bíblica en la Liturgia', 'La catequesis de la Iglesia desvela en los acontecimientos del Antiguo Testamento —como el Éxodo y el maná— las figuras de lo que Cristo realizó en la plenitud de los tiempos.'),
  ('CIC 1128', 'cic', 'Catecismo de la Iglesia Católica · N.° 1128', 'Segunda Parte · Eficacia «ex opere operato»', 'Los sacramentos obran «ex opere operato», es decir, en virtud de la obra salvífica de Cristo realizada de una vez por todas; sin embargo, los frutos dependen también de las disposiciones de quien los recibe.'),
  ('CIC 1131', 'cic', 'Catecismo de la Iglesia Católica · N.° 1131', 'Segunda Parte · Definición de sacramento', 'Los sacramentos son signos eficaces de la gracia, instituidos por Cristo y confiados a la Iglesia por los cuales nos es dispensada la vida divina.'),
  ('CIC 1137', 'cic', 'Catecismo de la Iglesia Católica · N.° 1137', 'Segunda Parte · La liturgia celestial en el Apocalipsis', 'El Apocalipsis de san Juan, leído en la liturgia de la Iglesia, revela la liturgia eterna del cielo donde el Cordero inmolado y en pie es adorado por la multitud de los redimidos.'),
  ('CIC 1154', 'cic', 'Catecismo de la Iglesia Católica · N.° 1154', 'Segunda Parte · La Liturgia de la Palabra', 'La Liturgia de la Palabra es parte integrante de las celebraciones sacramentales. Para nutrir la fe de los creyentes, la Iglesia proclama los libros de la Escritura organizados en los ciclos del Leccionario.'),
  ('CIC 1168', 'cic', 'Catecismo de la Iglesia Católica · N.° 1168', 'Segunda Parte · El Triduo Pascual', 'A partir del Triduo Pascual, como de su fuente de luz, el tiempo nuevo de la Resurrección llena todo el año litúrgico con su resplandor.'),
  ('CIC 1175', 'cic', 'Catecismo de la Iglesia Católica · N.° 1175', 'Segunda Parte · Laudes y Vísperas', 'La Liturgia de las Horas está llamada a ser la oración de todo el Pueblo de Dios; los laicos también son invitados a celebrarla, especialmente Laudes por la mañana y Vísperas por la tarde.'),
  ('CIC 1221', 'cic', 'Catecismo de la Iglesia Católica · N.° 1221', 'Segunda Parte · Paso del mar Rojo y Bautismo', 'El paso del mar Rojo, verdadera liberación de Israel de la esclavitud de Egipto, es el acontecimiento que anuncia la liberación obrada por el Bautismo.'),
  ('CIC 1231', 'cic', 'Catecismo de la Iglesia Católica · N.° 1231', 'Segunda Parte · Catecumenado postbautismal', 'Allí donde el bautismo de niños ha llegado a ser la forma habitual, se hace indispensable un catecumenado postbautismal que permita el despliegue necesario de la gracia bautismal en el crecimiento de la persona.'),
  ('CIC 1236', 'cic', 'Catecismo de la Iglesia Católica · N.° 1236', 'Segunda Parte · Anuncio de la Palabra y Bautismo', 'El anuncio de la Palabra de Dios ilumina con la verdad revelada a los candidatos y a la asamblea y suscita la respuesta de la fe, inseparable del Bautismo.'),
  ('CIC 1240', 'cic', 'Catecismo de la Iglesia Católica · N.° 1240', 'Segunda Parte · Fórmula trinitaria del Bautismo', 'En la Iglesia latina, esta triple infusión de agua va acompañada de las palabras del ministro: «N., yo te bautizo en el nombre del Padre, y del Hijo, y del Espíritu Santo».'),
  ('CIC 1256', 'cic', 'Catecismo de la Iglesia Católica · N.° 1256', 'Segunda Parte · Ministro del Bautismo en necesidad', 'Son ministros ordinarios del Bautismo el obispo, el presbítero y el diácono. En caso de necesidad, cualquier persona, incluso no bautizada, puede bautizar si tiene la intención requerida y usa la fórmula bautismal trinitaria.'),
  ('CIC 1289', 'cic', 'Catecismo de la Iglesia Católica · N.° 1289', 'Segunda Parte · El nombre de cristiano', 'El nombre mismo de «cristiano» deriva de Cristo, a quien Dios ungió con el Espíritu Santo, y expresa nuestra participación en la unción y misión de Jesús.'),
  ('CIC 1329', 'cic', 'Catecismo de la Iglesia Católica · N.° 1329', 'Segunda Parte · Banquete del Señor', 'La Eucaristía se llama «Banquete del Señor» porque se trata de la Cena que el Señor celebró con sus discípulos y de la anticipación del banquete de bodas del Cordero en la Jerusalén celestial.'),
  ('CIC 1347', 'cic', 'Catecismo de la Iglesia Católica · N.° 1347', 'Segunda Parte · Emaús y la estructura de la Misa', 'En el camino de Emaús Jesús explicó las Escrituras a los discípulos y luego se sentó a la mesa, tomó el pan, lo bendijo, lo partió y se lo dio: es el mismo movimiento fundamental de toda Eucaristía.'),
  ('CIC 1376', 'cic', 'Catecismo de la Iglesia Católica · N.° 1376', 'Segunda Parte · La Transubstanciación', 'Por la consagración del pan y del vino se opera la conversión de toda la sustancia del pan en la sustancia del Cuerpo de Cristo y de toda la sustancia del vino en la sustancia de su Sangre. Esta conversión la Iglesia la llama justamente transubstanciación.'),
  ('CIC 1379', 'cic', 'Catecismo de la Iglesia Católica · N.° 1379', 'Segunda Parte · El Sagrario', 'El sagrario estaba primeramente destinado a guardar dignamente la Eucaristía para poder llevarla a los enfermos; profundizando la fe en la presencia real, la Iglesia fomentó la adoración silenciosa del Señor presente en el sagrario.'),
  ('CIC 1385', 'cic', 'Catecismo de la Iglesia Católica · N.° 1385', 'Segunda Parte · Preparación para comulgar', 'Quien tiene conciencia de estar en pecado grave debe recibir el sacramento de la Reconciliación antes de acercarse a comulgar, preparando su corazón con recogimiento y ayuno eucarístico.'),
  ('CIC 1391', 'cic', 'Catecismo de la Iglesia Católica · N.° 1391', 'Segunda Parte · Frutos de la Comunión', 'La comunión acrecienta nuestra unión con Cristo. Recibir la Eucaristía en la comunión da como fruto principal la unión íntima con Cristo Jesús: «El que come mi carne y bebe mi sangre permanece en mí y yo en él».'),
  ('CIC 1441', 'cic', 'Catecismo de la Iglesia Católica · N.° 1441', 'Segunda Parte · Solo Dios perdona los pecados', 'Solo Dios perdona el pecado. Porque Jesús es el Hijo de Dios, dice de sí mismo que tiene poder de perdonar los pecados en la tierra, y en virtud de su autoridad divina confiere este poder a los apóstoles para que lo ejerzan en su nombre.'),
  ('CIC 1450', 'cic', 'Catecismo de la Iglesia Católica · N.° 1450', 'Segunda Parte · Los actos del penitente', 'La penitencia mueve al pecador a soportarlo todo de buena gana: en su corazón la contrición, en su boca la confesión y en su obra toda humildad y fructífera satisfacción.'),
  ('CIC 1467', 'cic', 'Catecismo de la Iglesia Católica · N.° 1467', 'Segunda Parte · El sigilo sacramental', 'Dada la delicadeza y la grandeza de este ministerio, la Iglesia declara que todo sacerdote que oye confesiones está obligado a guardar un secreto absoluto sobre los pecados que sus penitentes le han confesado, bajo penas muy severas.'),
  ('CIC 1502', 'cic', 'Catecismo de la Iglesia Católica · N.° 1502', 'Segunda Parte · El enfermo ante Dios', 'El hombre del Antiguo Testamento vive la enfermedad de cara a Dios. Ante Él derrama su lamento y de Él implora la curación, como se refleja en los Salmos y en el libro de Job.'),
  ('CIC 1505', 'cic', 'Catecismo de la Iglesia Católica · N.° 1505', 'Segunda Parte · Sentido redentor del sufrimiento', 'En su Pasión y muerte en la Cruz, Cristo dio un sentido nuevo al sufrimiento: desde entonces nos configura con Él y nos une a su pasión redentora.'),
  ('CIC 1514', 'cic', 'Catecismo de la Iglesia Católica · N.° 1514', 'Segunda Parte · Quién recibe la Unción de los Enfermos', 'La Unción de los Enfermos no es un sacramento solo para quienes están a punto de morir. Por eso, el tiempo oportuno para recibirlo comienza cuando el cristiano empieza a estar en peligro por enfermedad grave o vejez.'),
  ('CIC 1551', 'cic', 'Catecismo de la Iglesia Católica · N.° 1551', 'Segunda Parte · El sacerdocio como servicio', 'El sacerdocio ministerial es enteramente un servicio en favor de los fieles, imitando al Buen Pastor que no vino a ser servido, sino a servir y dar su vida.'),
  ('CIC 1554', 'cic', 'Catecismo de la Iglesia Católica · N.° 1554', 'Segunda Parte · Los tres grados del Orden', 'El ministerio eclesiástico, de institución divina, es ejercido en diversos órdenes por aquellos que ya desde antiguo vienen llamándose obispos, presbíteros y diáconos.'),
  ('CIC 1623', 'cic', 'Catecismo de la Iglesia Católica · N.° 1623', 'Segunda Parte · Los ministros del Matrimonio', 'Según la tradición latina, los esposos, como ministros de la gracia de Cristo, se confieren mutuamente el sacramento del Matrimonio expresando ante la Iglesia su consentimiento.'),
  ('CIC 1641', 'cic', 'Catecismo de la Iglesia Católica · N.° 1641', 'Segunda Parte · La gracia propia del Matrimonio', 'En su modo y estado de vida, los cónyuges cristianos tienen su carisma propio en el Pueblo de Dios: la gracia del sacramento perfecciona su amor humano y los santifica en el camino hacia la vida eterna.'),
  ('CIC 1674', 'cic', 'Catecismo de la Iglesia Católica · N.° 1674', 'Segunda Parte · La piedad popular', 'Además de la liturgia sacramental, la vida cristiana se nutre de diversas formas de piedad popular enraizadas en las culturas, como las peregrinaciones, el Vía Crucis y el Santo Rosario.'),
  ('CIC 1716', 'cic', 'Catecismo de la Iglesia Católica · N.° 1716', 'Tercera Parte · Las Bienaventuranzas', 'Las Bienaventuranzas están en el centro de la predicación de Jesús. Recogen las promesas hechas al pueblo elegido y las perfeccionan ordenándolas ya no solo a la posesión de una tierra, sino al Reino de los cielos.'),
  ('CIC 1717', 'cic', 'Catecismo de la Iglesia Católica · N.° 1717', 'Tercera Parte · El rostro de Cristo en las Bienaventuranzas', 'Las Bienaventuranzas dibujan el rostro de Jesucristo y describen su caridad; expresan la vocación de los fieles asociados a la gloria de su Pasión y de su Resurrección.'),
  ('CIC 1815', 'cic', 'Catecismo de la Iglesia Católica · N.° 1815', 'Tercera Parte · Fe y obras de caridad', 'El don de la fe permanece en el que no ha pecado contra ella. Pero la fe sin obras está muerta: privada de la esperanza y de la caridad, la fe no une plenamente el fiel a Cristo.'),
  ('CIC 1817', 'cic', 'Catecismo de la Iglesia Católica · N.° 1817', 'Tercera Parte · La virtud de la esperanza', 'La esperanza es la virtud teologal por la que aspiramos al Reino de los cielos y a la vida eterna como felicidad nuestra, poniendo nuestra confianza en las promesas de Cristo y apoyándonos en la gracia del Espíritu Santo.'),
  ('CIC 1823', 'cic', 'Catecismo de la Iglesia Católica · N.° 1823', 'Tercera Parte · El mandamiento nuevo de la caridad', 'Jesús hace de la caridad el mandamiento nuevo. Amando a los suyos hasta el fin manifiesta el amor del Padre que ha recibido, y al amarse unos a otros los discípulos imitan el amor de Jesús.'),
  ('CIC 1831', 'cic', 'Catecismo de la Iglesia Católica · N.° 1831', 'Tercera Parte · Los siete dones del Espíritu Santo', 'Los siete dones del Espíritu Santo son: sabiduría, inteligencia, consejo, fortaleza, ciencia, piedad y temor de Dios. Completan y llevan a su perfección las virtudes de quienes los reciben.'),
  ('CIC 1832', 'cic', 'Catecismo de la Iglesia Católica · N.° 1832', 'Tercera Parte · Los frutos del Espíritu', 'Los frutos del Espíritu son perfecciones que forma en nosotros el Espíritu Santo como primicias de la gloria eterna: caridad, gozo, paz, paciencia, longanimidad, bondad, benignidad, mansedumbre, fidelidad, modestia, continencia y castidad.'),
  ('CIC 1932', 'cic', 'Catecismo de la Iglesia Católica · N.° 1932', 'Tercera Parte · Hacerse prójimo del necesitado', 'El deber de hacerse prójimo de los demás y de servirles activamente se hace más apremiante todavía cuando éstos están más necesitados en cualquier sector de la vida humana.'),
  ('CIC 2000', 'cic', 'Catecismo de la Iglesia Católica · N.° 2000', 'Tercera Parte · La gracia santificante', 'La gracia santificante es un don habitual, una disposición estable y sobrenatural que perfecciona al alma para hacerla capaz de vivir con Dios y obrar por su amor.'),
  ('CIC 2013', 'cic', 'Catecismo de la Iglesia Católica · N.° 2013', 'Tercera Parte · Llamada universal a la santidad', 'Todos los fieles, de cualquier estado o condición, están llamados a la plenitud de la vida cristiana y a la perfección de la caridad. Todos son llamados a la santidad en medio de sus ocupaciones cotidianas.'),
  ('CIC 2015', 'cic', 'Catecismo de la Iglesia Católica · N.° 2015', 'Tercera Parte · El camino de la perfección', 'El camino de la perfección pasa por la cruz y por la fidelidad alegre en los deberes de cada día. No hay santidad sin renuncia y sin combate espiritual sostenido por la gracia.'),
  ('CIC 2074', 'cic', 'Catecismo de la Iglesia Católica · N.° 2074', 'Tercera Parte · Permanecer en Cristo', 'Jesús dice: «Yo soy la vid; ustedes los sarmientos. El que permanece en mí y yo en él, ése da mucho fruto; porque separados de mí no pueden hacer nada». La vida moral cristiana nace de la unión con Cristo.'),
  ('CIC 2098', 'cic', 'Catecismo de la Iglesia Católica · N.° 2098', 'Tercera Parte · La virtud de la religión y la entrega', 'Los actos de fe, esperanza y caridad que ordena el primer mandamiento se realizan en la oración y en la ofrenda sincera del corazón al único Dios verdadero.'),
  ('CIC 2106', 'cic', 'Catecismo de la Iglesia Católica · N.° 2106', 'Tercera Parte · Libertad religiosa', 'Nadie debe ser forzado a obrar contra su conciencia ni impedido de actuar conforme a ella, en privado o en público, solo o asociado con otros, dentro de los límites debidos.'),
  ('CIC 2229', 'cic', 'Catecismo de la Iglesia Católica · N.° 2229', 'Tercera Parte · Educación de los hijos y jóvenes', 'Los padres son los primeros responsables de la educación de sus hijos, y tienen el derecho de elegir para ellos una formación que corresponda a sus convicciones cristianas.'),
  ('CIC 2305', 'cic', 'Catecismo de la Iglesia Católica · N.° 2305', 'Tercera Parte · Constructores de la paz', 'La paz terrenal es imagen y fruto de la paz de Cristo, el Príncipe de la Paz mesiánico. Quienes trabajan por la paz y la reconciliación son llamados hijos de Dios.'),
  ('CIC 2421', 'cic', 'Catecismo de la Iglesia Católica · N.° 2421', 'Tercera Parte · La Doctrina Social de la Iglesia', 'La doctrina social de la Iglesia se desarrolló en el siglo XIX —especialmente a partir de la encíclica Rerum Novarum de León XIII— cuando se encontró el Evangelio con la sociedad industrial moderna y sus desafíos laborales.'),
  ('CIC 2443', 'cic', 'Catecismo de la Iglesia Católica · N.° 2443', 'Tercera Parte · Amor preferencial por los pobres', 'Dios bendice a los que ayudan a los pobres y reprueba a los que se niegan a hacerlo. Jesús reconocerá a sus elegidos en lo que hayan hecho por los pobres.'),
  ('CIC 2447', 'cic', 'Catecismo de la Iglesia Católica · N.° 2447', 'Tercera Parte · Las obras de misericordia', 'Las obras de misericordia son las acciones caritativas mediante las cuales ayudamos a nuestro prójimo en sus necesidades corporales y espirituales. La limosna hecha a los pobres es uno de los principales testimonios de la caridad fraterna.'),
  ('CIC 2468', 'cic', 'Catecismo de la Iglesia Católica · N.° 2468', 'Tercera Parte · Vivir en la verdad', 'La verdad como rectitud de la acción y de la palabra humana tiene por nombre veracidad, sinceridad o franqueza. La veracidad consiste en mostrarse verdadero en los propios actos y en decir verdad en las palabras.'),
  ('CIC 2473', 'cic', 'Catecismo de la Iglesia Católica · N.° 2473', 'Tercera Parte · El martirio', 'El martirio es el supremo testimonio de la verdad de la fe; designa un testimonio que llega hasta la muerte. El mártir da testimonio de Cristo muerto y resucitado, al cual está unido por la caridad.'),
  ('CIC 2518', 'cic', 'Catecismo de la Iglesia Católica · N.° 2518', 'Tercera Parte · La pureza de corazón', 'La sexta bienaventuranza proclama: «Bienaventurados los limpios de corazón porque ellos verán a Dios». La pureza de corazón nos permite ver según Dios y acoger al prójimo con amor sincero.'),
  ('CIC 2544', 'cic', 'Catecismo de la Iglesia Católica · N.° 2544', 'Tercera Parte · Desprendimiento del corazón', 'Jesús ordena a sus discípulos preferirlo a Él respecto a todo y a todos y les propone renunciar a todos sus bienes por Él y por el Evangelio, poniendo su tesoro en Dios.'),
  ('CIC 2546', 'cic', 'Catecismo de la Iglesia Católica · N.° 2546', 'Tercera Parte · Los pobres de espíritu', '«Bienaventurados los pobres de espíritu». Las bienaventuranzas revelan un orden de felicidad y de gracia donde el Señor se compadece de los pobres y humildes que confían solo en Él.'),
  ('CIC 2568', 'cic', 'Catecismo de la Iglesia Católica · N.° 2568', 'Cuarta Parte · La oración en el Antiguo Testamento', 'La revelación de la oración en la economía de la salvación se inscribe en la historia fiel de Dios con su pueblo, desde los patriarcas hasta los profetas.'),
  ('CIC 2573', 'cic', 'Catecismo de la Iglesia Católica · N.° 2573', 'Cuarta Parte · El combate de la oración en Jacob', 'La tradición espiritual de la Iglesia ha tomado del combate nocturno de Jacob el símbolo de la oración como un combate de la fe y una victoria de la perseverancia.'),
  ('CIC 2580', 'cic', 'Catecismo de la Iglesia Católica · N.° 2580', 'Cuarta Parte · La oración de Salomón y el Templo', 'La oración de Salomón por la sabiduría y en la dedicación del Templo se apoya en la promesa de Dios y en su Alianza, convirtiendo el Templo en casa de oración para Israel y todos los pueblos.'),
  ('CIC 2583', 'cic', 'Catecismo de la Iglesia Católica · N.° 2583', 'Cuarta Parte · Elías en el monte Horeb', 'En el monte Horeb, Elías aprendió a discernir la presencia de Dios en «el susurro de una brisa suave», convirtiéndose en padre de los profetas y modelo de contemplación silenciosa.'),
  ('CIC 2612', 'cic', 'Catecismo de la Iglesia Católica · N.° 2612', 'Cuarta Parte · Velar y orar', 'En Jesús, el Reino de Dios está próximo; por eso llama a la conversión y a la fe, pero también a la vigilancia. En la oración, el discípulo vela atento a Aquel que es y que viene.'),
  ('CIC 2619', 'cic', 'Catecismo de la Iglesia Católica · N.° 2619', 'Cuarta Parte · El Magníficat', 'El cántico de María (el Magníficat) es a la vez el cántico de la Madre de Dios y el de la Iglesia; cántico de acción de gracias por la plenitud de gracias derramadas en la historia de la salvación.'),
  ('CIC 2638', 'cic', 'Catecismo de la Iglesia Católica · N.° 2638', 'Cuarta Parte · La oración de acción de gracias', 'Al igual que en la oración de petición, todo acontecimiento y toda necesidad pueden convertirse en ofrenda de acción de gracias. Las cartas de san Pablo comienzan y terminan frecuentemente dando gracias a Dios.'),
  ('CIC 2642', 'cic', 'Catecismo de la Iglesia Católica · N.° 2642', 'Cuarta Parte · La alabanza en el Apocalipsis', 'La revelación de lo que ha de suceder, el Apocalipsis, está sostenida por los cánticos de la liturgia celestial y por la alabanza de los redimidos que proclaman la santidad y grandeza de Dios.'),
  ('CIC 2676', 'cic', 'Catecismo de la Iglesia Católica · N.° 2676', 'Cuarta Parte · El Avemaría', 'El Avemaría retoma el saludo del ángel Gabriel («Alégrate, llena de gracia») y el saludo de Isabel («Bendita tú entre las mujeres y bendito el fruto de tu vientre»), contemplando en María la morada donde Dios quiso habitar.'),
  ('CIC 2677', 'cic', 'Catecismo de la Iglesia Católica · N.° 2677', 'Cuarta Parte · Ruega por nosotros', 'Al pedirle a María «ruega por nosotros pecadores, ahora y en la hora de nuestra muerte», nos abandonamos desde ahora a la voluntad de Dios y nos confiamos a su intercesión maternal.'),
  ('CIC 2678', 'cic', 'Catecismo de la Iglesia Católica · N.° 2678', 'Cuarta Parte · El Santo Rosario', 'La piedad medieval de Occidente desarrolló la oración del Rosario como sustitución popular de la Liturgia de las Horas: contemplar con María los misterios de la vida de Cristo.'),
  ('CIC 2684', 'cic', 'Catecismo de la Iglesia Católica · N.° 2684', 'Cuarta Parte · Familias de espiritualidad', 'En la comunión de los santos, a lo largo de la historia de las Iglesias, se han desarrollado diversos tipos de espiritualidad (benedictina, franciscana, dominica, carmelita, ignaciana y movimientos modernos) que reflejan la única y pura luz del Espíritu Santo.'),
  ('CIC 2708', 'cic', 'Catecismo de la Iglesia Católica · N.° 2708', 'Cuarta Parte · La meditación y la Lectio Divina', 'La meditación hace intervenir el pensamiento, la imaginación, la emoción y el deseo a partir de la Sagrada Escritura para confrontar nuestra vida con el Evangelio y crecer en el amor a Cristo.'),
  ('CIC 2709', 'cic', 'Catecismo de la Iglesia Católica · N.° 2709', 'Cuarta Parte · La oración de contemplación', '¿Qué es la oración de contemplación? Santa Teresa responde: «No es otra cosa oración mental, a mi parecer, sino tratar de amistad, estando muchas veces tratando a solas con quien sabemos nos ama».'),
  ('CIC 2761', 'cic', 'Catecismo de la Iglesia Católica · N.° 2761', 'Cuarta Parte · El Padrenuestro, resumen del Evangelio', 'La oración dominical es en verdad el resumen de todo el Evangelio (Tertuliano). Jesús nos dejó el Padrenuestro como modelo perfecto de toda oración filial al Padre.')
insert into public.daily_challenges (challenge_date, liturgical_day, title, subtitle, first_reading_ref, gospel_ref, source_label, is_custom, is_active, questions)
values
  ('2026-11-23'::date, 'Lunes · 34.ª Semana del Tiempo Ordinario', 'La ofrenda generosa del corazón', 'El cántico nuevo del Cordero y la viuda pobre que entregó todo lo que tenía.', 'Ap 14,1-5', 'Lc 21,1-4', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-23-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En la primera lectura del Apocalipsis, ¿sobre qué monte ve san Juan al Cordero rodeado de los redimidos?","options":["Monte Sinaí","Monte Sión","Monte Tabor","Monte Carmelo"],"correctIndex":1,"explanation":"El monte Sión simboliza la Jerusalén celestial donde Cristo, el Cordero victorioso, reúne a los fieles que llevan escrito su Nombre.","sourceRef":"Ap 14,1-5 · CIC 1137"},{"id":"dq-2026-11-23-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"Según la primera lectura, ¿qué rasgo caracteriza a quienes siguen al Cordero adondequiera que va?","options":["Acumulan riquezas en el templo","En su boca no se halló mentira y son intachables","Hablan en secretos ocultos","Viven aislados de toda comunidad"],"correctIndex":1,"explanation":"El Apocalipsis describe a los discípulos fieles por su sinceridad, fidelidad y entrega limpia a Cristo.","sourceRef":"Ap 14,1-5 · CIC 2468"},{"id":"dq-2026-11-23-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿cuántas monedas depositó la viuda pobre en la alcancía del Templo?","options":["Diez denarios","Dos moneditas de escaso valor","Cinco talentos","Una moneda de oro"],"correctIndex":1,"explanation":"Mientras los ricos echaban de lo que les sobraba, la viuda entregó dos pequeñas monedas, que eran todo lo que tenía para vivir.","sourceRef":"Lc 21,1-4 · CIC 2447"},{"id":"dq-2026-11-23-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Por qué afirmó Jesús que la viuda pobre dio más que todos los demás?","options":["Porque sus monedas eran las más antiguas","Porque ella dio de su indigencia todo lo que tenía para vivir","Porque fue la primera en llegar al Templo","Porque los sacerdotes se lo pidieron"],"correctIndex":1,"explanation":"Dios no mide la cantidad externa de nuestra ofrenda, sino la medida de amor y confianza con que nos entregamos.","sourceRef":"Lc 21,1-4 · CIC 2544"},{"id":"dq-2026-11-23-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué virtud une la fidelidad del Apocalipsis y el gesto silencioso de la viuda en el Evangelio?","options":["La búsqueda de reconocimiento público","La entrega total y confiada a Dios","El cumplimiento puramente externo","El temor al futuro"],"correctIndex":1,"explanation":"Tanto los redimidos que siguen al Cordero como la viuda del Templo ponen toda su seguridad y corazón en el Señor.","sourceRef":"Lc 21,1-4 · CIC 2098"}]'::jsonb),
  ('2026-11-24'::date, 'Martes · 34.ª Semana del Tiempo Ordinario', 'Vigilancia y discernimiento en la historia', 'La cosecha del Hijo del hombre y las palabras de Jesús ante el Templo de Jerusalén.', 'Ap 14,14-19', 'Lc 21,5-11', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-24-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"En la primera lectura, ¿cómo aparece sentado sobre una nube blanca aquel que lleva una corona de oro?","options":["Como un profeta del desierto","Como un Hijo de hombre","Como un sumo sacerdote","Como un rey de Babilonia"],"correctIndex":1,"explanation":"La imagen del \"Hijo de hombre\" sobre la nube retoma la profecía de Daniel y señala a Cristo Señor de la historia.","sourceRef":"Ap 14,14-19 · CIC 679"},{"id":"dq-2026-11-24-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué simboliza la siega madura de la tierra en la visión del Apocalipsis?","options":["El final de una estación agrícola","La plenitud del tiempo y el juicio justo de Dios sobre la historia","La construcción de una nueva ciudad terrena","Una parábola sobre el comercio"],"correctIndex":1,"explanation":"La cosecha expresa que la historia camina hacia su plenitud en Cristo, donde toda obra hecha por amor da fruto eterno.","sourceRef":"Ap 14,14-19 · CIC 1040"},{"id":"dq-2026-11-24-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿qué admiraban algunos oyentes cuando Jesús anunció que \"no quedará piedra sobre piedra\"?","options":["El palacio de Herodes","Las hermosas piedras y ofrendas votivas del Templo","Las murallas de Jericó","Las barcas del lago de Galilea"],"correctIndex":1,"explanation":"Jesús recuerda que toda obra material es pasajera y que solo su Palabra y su Reino permanecen para siempre.","sourceRef":"Lc 21,5-11 · CIC 586"},{"id":"dq-2026-11-24-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"Ante quienes anuncien falsamente \"Soy yo\" o \"El tiempo está cerca\", ¿qué advierte Jesús?","options":["\"Escúchenlos sin dudar\"","\"Tengan cuidado de no dejarse engañar; no los sigan\"","\"Huyan al desierto de inmediato\"","\"Guarden silencio por cuarenta días\""],"correctIndex":1,"explanation":"La Iglesia nos invita a vivir con esperanza serena y discernimiento, sin dejarnos llevar por miedos ni falsos mesianismos.","sourceRef":"Lc 21,5-11 · CIC 675"},{"id":"dq-2026-11-24-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"Cuando se escuchen noticias de guerras y conflictos, ¿qué actitud pide Jesús a sus discípulos?","options":["Desesperarse","No aterrarse, porque Dios sigue guiando la historia","Abandonar la oración","Calcular la fecha exacta del fin del mundo"],"correctIndex":1,"explanation":"El creyente afronta las pruebas con paz interior, confiando en la providencia de Cristo resucitado.","sourceRef":"Lc 21,5-11 · CIC 677"}]'::jsonb),
  ('2026-11-25'::date, 'Miércoles · 34.ª Semana del Tiempo Ordinario', 'Perseverancia que salva la vida', 'El cántico de Moisés y del Cordero, y la promesa de Jesús en medio de las pruebas.', 'Ap 15,1-4', 'Lc 21,12-19', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-25-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"En la primera lectura del Apocalipsis, ¿qué cántico entonan los vencedores junto al mar de cristal?","options":["El cántico de David y Salomón","El cántico de Moisés y el cántico del Cordero","El cántico de Débora","El cántico de Tobías"],"correctIndex":1,"explanation":"Uniendo a Moisés y al Cordero, la Escritura muestra que la liberación del Éxodo alcanza su plenitud en la Pascua de Jesús.","sourceRef":"Ap 15,1-4 · CIC 1094"},{"id":"dq-2026-11-25-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué proclama el himno de la primera lectura sobre las obras del Señor?","options":["\"Grandes y admirables son tus obras, Señor, Dios todopoderoso\"","\"El mundo se sostiene por sí mismo\"","\"Solo una nación conocerá tu nombre\"","\"Nadie puede cantar ante tu trono\""],"correctIndex":0,"explanation":"El cántico reconoce la santidad y justicia de Dios, a quien todas las naciones están llamadas a adorar.","sourceRef":"Ap 15,1-4 · CIC 2642"},{"id":"dq-2026-11-25-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, cuando los discípulos sean llevados ante tribunales por causa de Jesús, ¿en qué oportunidad se convertirá esa prueba?","options":["En motivo de rendición","En ocasión de dar testimonio de su fe","En señal de abandono de Dios","En excusa para ocultar el Evangelio"],"correctIndex":1,"explanation":"El testimonio fiel en la dificultad (\"martirio\" significa testigo) hace resplandecer la verdad y la fuerza del Evangelio.","sourceRef":"Lc 21,12-19 · CIC 2473"},{"id":"dq-2026-11-25-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué promete dar Jesús a sus discípulos cuando tengan que defenderse por causa de su Nombre?","options":["Riquezas para pagar fianzas","Una elocuencia y una sabiduría que nadie podrá resistir ni contradecir","Un ejército protector","Silencio absoluto"],"correctIndex":1,"explanation":"El Espíritu Santo asiste a quienes confían en Cristo en los momentos decisivos del testimonio.","sourceRef":"Lc 21,12-19 · CIC 1831"},{"id":"dq-2026-11-25-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Con qué célebre frase cierra Jesús el Evangelio de hoy?","options":["\"Con su perseverancia salvarán sus vidas\"","\"Quien huye primero vence\"","\"No habrá más dificultades en la tierra\"","\"El saber humano basta para todo\""],"correctIndex":0,"explanation":"La constancia humilde y confiada día a día —sostenida por la gracia— conduce a la salvación definitiva.","sourceRef":"Lc 21,12-19 · CIC 1808"}]'::jsonb),
  ('2026-11-26'::date, 'Jueves · 34.ª Semana del Tiempo Ordinario', 'Levanten la cabeza: se acerca su liberación', 'El banquete de bodas del Cordero y la esperanza firme ante la venida del Hijo del hombre.', 'Ap 18,1-2.21-23; 19,9', 'Lc 21,20-28', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-26-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"En la primera lectura, ¿qué bienaventuranza proclama el ángel que repetimos en cada Misa antes de comulgar?","options":["\"Felices los que construyen murallas\"","\"Felices los invitados al banquete de bodas del Cordero\"","\"Felices los que nunca pasan pruebas\"","\"Felices los mercaderes de Babilonia\""],"correctIndex":1,"explanation":"Cada Eucaristía nos anticipa el banquete celestial del Cordero; por eso el sacerdote cita estas palabras del Apocalipsis antes de la Comunión.","sourceRef":"Ap 19,9 · CIC 1329"},{"id":"dq-2026-11-26-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué simboliza la caída de \"Babilonia\" en la lectura del Apocalipsis?","options":["La desaparición de toda cultura","La fragilidad de todo poder injusto y orgulloso que se cierra a Dios","La ruina de los creyentes","El fin de la creación"],"correctIndex":1,"explanation":"Todo sistema basado en la idolatría y el abuso es pasajero; solo el Reino de justicia y paz de Dios permanece eternamente.","sourceRef":"Ap 18,21 · CIC 677"},{"id":"dq-2026-11-26-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿cómo verán venir al Hijo del hombre al final de los tiempos?","options":["Oculto en secreto en el desierto","Viniendo en una nube con gran poder y gloria","En un carro de guerra romano","Sin que nadie lo note"],"correctIndex":1,"explanation":"En el Credo profesamos nuestra fe en la segunda venida gloriosa de Cristo para juzgar a vivos y muertos.","sourceRef":"Lc 21,20-28 · CIC 668"},{"id":"dq-2026-11-26-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"Cuando comiencen a suceder estos signos, ¿qué gesto de esperanza pide Jesús a los suyos?","options":["\"Escondan el rostro con miedo\"","\"Enderecen el cuerpo y levanten la cabeza, porque se acerca su liberación\"","\"Dejen de servir al prójimo\"","\"Cierren las puertas de las casas\""],"correctIndex":1,"explanation":"Para el cristiano, el encuentro definitivo con el Señor no es motivo de terror sino de esperanza gozosa.","sourceRef":"Lc 21,20-28 · CIC 1817"},{"id":"dq-2026-11-26-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué virtud teologal nos sostiene para esperar el Reino de los Cielos con la cabeza en alto?","options":["La prudencia","La esperanza","La templanza","La curiosidad"],"correctIndex":1,"explanation":"La esperanza nos orienta hacia la vida eterna y nos protege del desaliento en los momentos de prueba.","sourceRef":"Rm 15,13 · CIC 1817"}]'::jsonb),
  ('2026-11-27'::date, 'Viernes · 34.ª Semana del Tiempo Ordinario', 'La Palabra que no pasa jamás', 'El cielo nuevo y la tierra nueva del Apocalipsis, y la parábola de la higuera.', 'Ap 20,11–21,2', 'Lc 21,29-33', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-27-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En la primera lectura, ¿qué contempla san Juan descender del cielo ataviada como una novia para su esposo?","options":["La torre de Babel","La Ciudad Santa, la nueva Jerusalén","El arca de Noé","La ciudad de Roma"],"correctIndex":1,"explanation":"La nueva Jerusalén representa a la Iglesia glorificada, unida para siempre a Cristo en el cielo nuevo y la tierra nueva.","sourceRef":"Ap 21,1-2 · CIC 1045"},{"id":"dq-2026-11-27-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué promete el Apocalipsis que hará Dios en la nueva creación respecto del universo entero?","options":["Lo destruirá sin dejar rastro","Lo renovará en un cielo nuevo y una tierra nueva","Lo dejará igual para siempre","Lo reservará solo para los ángeles"],"correctIndex":1,"explanation":"La fe cristiana espera la transfiguración del cosmos entero donde habitará la justicia y Dios será todo en todos.","sourceRef":"Ap 21,1-2 · CIC 1042"},{"id":"dq-2026-11-27-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿qué árbol pone Jesús como ejemplo para reconocer que el Reino de Dios está cerca?","options":["El cedro del Líbano","La higuera y todos los árboles cuando brotan","La palmera del desierto","El ciprés"],"correctIndex":1,"explanation":"Así como los brotes tiernos anuncian la cercanía del verano, los signos del Evangelio invitan a descubrir el Reino que ya brota.","sourceRef":"Lc 21,29-33 · CIC 541"},{"id":"dq-2026-11-27-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué afirma Jesús que jamás pasará, aunque pasen el cielo y la tierra?","options":["Los imperios de la tierra","Sus palabras","Los muros de las ciudades","Las modas de cada época"],"correctIndex":1,"explanation":"La Palabra de Cristo es eterna y firme como roca; edificar la vida sobre ella nos da estabilidad verdadera.","sourceRef":"Lc 21,29-33 · CIC 104"},{"id":"dq-2026-11-27-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Cómo nos alimenta la Iglesia cotidianamente con la Palabra de Dios que no pasa?","options":["Solo una vez al año en Pascua","En la Liturgia de la Palabra de la Misa y en la lectura orante de la Escritura","Únicamente en los concilios","Mediante fábulas populares"],"correctIndex":1,"explanation":"La Iglesia venera la Sagrada Escritura como venera el Cuerpo del Señor y la ofrece cada día en la liturgia.","sourceRef":"Sal 119,105 · CIC 103"}]'::jsonb),
  ('2026-11-28'::date, 'Sábado · 34.ª Semana del Tiempo Ordinario', '¡Ven, Señor Jesús! Vigilancia en la oración', 'El río de agua viva del Apocalipsis y la invitación de Jesús a orar en todo momento.', 'Ap 22,1-7', 'Lc 21,34-36', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-28-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En la primera lectura del último capítulo del Apocalipsis, ¿qué brota del trono de Dios y del Cordero?","options":["Un río de agua viva, resplandeciente como el cristal","Un viento del norte","Una nube de ceniza","Un camino de piedra"],"correctIndex":0,"explanation":"El río de agua viva simboliza la gracia abundante del Espíritu Santo que da vida eterna a los hijos de Dios.","sourceRef":"Ap 22,1-7 · CIC 1137"},{"id":"dq-2026-11-28-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Para qué sirven las hojas del árbol de la vida que crece a ambos lados del río en la visión de san Juan?","options":["Para construir tiendas","Para la curación de las naciones","Para adornar coronas","Para escribir leyes"],"correctIndex":1,"explanation":"La salvación de Cristo sana las heridas de toda la humanidad y abre la comunión plena con Dios.","sourceRef":"Ap 22,1-7 · CIC 1045"},{"id":"dq-2026-11-28-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿de qué nos pide Jesús que cuidemos nuestro corazón para que no se embote?","options":["Del estudio y el trabajo","De los excesos, la embriaguez y las preocupaciones de la vida","De la alegría compartida","De la amistad con los vecinos"],"correctIndex":1,"explanation":"La sobriedad y la confianza en el Padre mantienen el corazón despierto y disponible para el encuentro con Cristo.","sourceRef":"Lc 21,34-36 · CIC 2612"},{"id":"dq-2026-11-28-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué dos actitudes recomienda Jesús en el versículo final para mantenerse firmes ante el Hijo del hombre?","options":["Estén prevenidos y oren incesantemente","Acumulen bienes y descansen","Discutan y compitan","Duerman sin preocupación"],"correctIndex":0,"explanation":"La vigilancia y la oración constante nos dan fuerza para atravesar las pruebas y permanecer unidos a Cristo.","sourceRef":"Lc 21,34-36 · CIC 2612"},{"id":"dq-2026-11-28-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Con qué súplica llena de esperanza cierra el libro del Apocalipsis y resuena en la entrada al Adviento?","options":["\"¡Ven, Señor Jesús!\" (Marana tha)","\"Todo ha terminado en silencio\"","\"Esperemos otro siglo\"","\"Basta con la ley antigua\""],"correctIndex":0,"explanation":"La invocación \"¡Ven, Señor Jesús!\" expresa el deseo vivo de la Iglesia que aguarda la presencia del Señor cada día.","sourceRef":"Ap 22,20 · CIC 451"}]'::jsonb),
  ('2026-11-29'::date, 'Primer Domingo de Adviento', '¡Estén despiertos! Comienza el Adviento', 'El clamor del profeta Isaías al Padre alfarero y la llamada de Jesús a velar.', 'Is 63,16b-17; 64,2-7', 'Mc 13,33-37', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-2026-11-29-1","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":1,"prompt":"En la primera lectura de Isaías, ¿con qué imagen tierna compara el profeta a Dios y a su pueblo?","options":["Un rey y sus soldados","El alfarero y la arcilla modelada por sus manos","Un navegante y su brújula","Un mercader y sus perlas"],"correctIndex":1,"explanation":"\"Tú eres nuestro Padre; nosotros somos la arcilla y tú nuestro alfarero\": la lectura abre el Adviento con humilde confianza en Dios.","sourceRef":"Is 64,7 · CIC 239"},{"id":"dq-2026-11-29-2","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":1,"prompt":"¿Qué suplica el profeta Isaías al comienzo del Adviento anhelando la venida salvadora de Dios?","options":["\"¡Ojalá rasgaras el cielo y descendieras!\"","\"Envíanos un rey guerrero\"","\"Permanece lejos en las alturas\"","\"Multiplica el oro de Jerusalén\""],"correctIndex":0,"explanation":"Ese grito de anhelo se cumple en la Encarnación, cuando el Hijo de Dios desciende y habita entre nosotros.","sourceRef":"Is 63,19 · CIC 524"},{"id":"dq-2026-11-29-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de san Marcos, ¿a quién compara Jesús al creyente que aguarda el regreso del dueño de casa?","options":["Al centinela y a los servidores que cumplen su tarea y velan","Al invitado distraído","Al comerciante apurado","Al viajero que olvidó su destino"],"correctIndex":0,"explanation":"A cada discípulo el Señor le ha confiado una tarea concreta mientras espera vigilante su venida.","sourceRef":"Mc 13,33-37 · CIC 672"},{"id":"dq-2026-11-29-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Cuál es la palabra clave que Jesús repite tres veces en el Evangelio de hoy y dirige \"a todos\"?","options":["\"¡Corran!\"","\"¡Estén prevenidos / Velen!\"","\"¡Descansen!\"","\"¡Callen!\""],"correctIndex":1,"explanation":"Velar en Adviento significa vivir atentos a la presencia de Dios en la oración, la Eucaristía y el servicio al prójimo.","sourceRef":"Mc 13,33-37 · CIC 524"},{"id":"dq-2026-11-29-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué nuevo tiempo y color litúrgico inaugura la Iglesia en el Primer Domingo de Adviento?","options":["Cuaresma y color rojo","El Año Litúrgico (Adviento) con color morado","Tiempo Pascual con color blanco","Tiempo Ordinario con color verde"],"correctIndex":1,"explanation":"Con el primer domingo de Adviento comienza un nuevo año litúrgico y encendemos la primera vela de la corona de Adviento.","sourceRef":"IGMR 346 · CIC 524"}]'::jsonb),
  ('2026-12-08'::date, 'Solemnidad de la Inmaculada Concepción', 'Alégrate, llena de gracia', 'La promesa de salvación en el Génesis y el "Sí" de María en la Anunciación.', 'Gn 3,9-15.20', 'Lc 1,26-38', 'Solemnidad · Lectura + Evangelio', false, true, '[{"id":"dq-2026-12-08-1","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":2,"prompt":"¿Cómo llaman los Padres de la Iglesia al pasaje de Génesis 3,15 leído hoy, donde Dios anuncia la victoria sobre la serpiente?","options":["El Protoevangelio","El Decálogo","El Levítico","El Apocalipsis"],"correctIndex":0,"explanation":"El Protoevangelio (\"primer anuncio de la Buena Nueva\") profetiza la victoria de Cristo, descendiente de la Mujer, sobre el mal.","sourceRef":"Gn 3,15 · CIC 410"},{"id":"dq-2026-12-08-2","topicId":"11111111-1111-4111-8111-111111111106","topicSlug":"virgen-maria","difficulty":1,"prompt":"En el Evangelio de la solemnidad de hoy, ¿con qué saludo se dirige el ángel Gabriel a María en Nazaret?","options":["\"¡Alégrate, llena de gracia, el Señor está contigo!\"","\"¡La paz sea en Jerusalén!\"","\"¡Levántate y parte a Egipto!\"","\"¡Dichosa tú entre las profetisas!\""],"correctIndex":0,"explanation":"El título \"llena de gracia\" (Kecharitomene) revela que María fue colmada por Dios desde el primer instante de su existencia.","sourceRef":"Lc 1,28 · CIC 491"},{"id":"dq-2026-12-08-3","topicId":"11111111-1111-4111-8111-111111111106","topicSlug":"virgen-maria","difficulty":1,"prompt":"¿Qué aseguró el ángel Gabriel a María para disipar su asombro ante la maternidad divina?","options":["\"Porque para Dios nada es imposible\"","\"Porque los reyes te protegerán\"","\"Porque el Templo te proclamará\"","\"Porque nunca tendrás dificultades\""],"correctIndex":0,"explanation":"La obra de la Encarnación es fruto del poder creador del Espíritu Santo, ante el cual nada es imposible.","sourceRef":"Lc 1,26-38 · CIC 494"},{"id":"dq-2026-12-08-4","topicId":"11111111-1111-4111-8111-111111111106","topicSlug":"virgen-maria","difficulty":1,"prompt":"¿Cuál fue la respuesta libre y confiada de María al plan de Dios?","options":["\"Lo pensaré durante un año\"","\"He aquí la esclava del Señor; hágase en mí según tu palabra\"","\"Envía mejor a Isabel\"","\"Primero muéstrame una señal en el cielo\""],"correctIndex":1,"explanation":"El \"fiat\" (hágase) de María es el modelo supremo de obediencia en la fe para todo cristiano.","sourceRef":"Lc 1,26-38 · CIC 494"},{"id":"dq-2026-12-08-5","topicId":"11111111-1111-4111-8111-111111111106","topicSlug":"virgen-maria","difficulty":2,"prompt":"¿En virtud de qué méritos fue preservada María del pecado original desde su concepción?","options":["Por los méritos propios de su familia","En previsión de los méritos salvadores de su Hijo Jesucristo","Por haber nacido en Jerusalén","Por la ley antigua de Moisés"],"correctIndex":1,"explanation":"María fue redimida de un modo más sublime que nosotros: preservada del pecado por gracia anticipada de la Cruz de Cristo.","sourceRef":"Lc 1,28 · CIC 491"}]'::jsonb),
  ('2026-12-25'::date, 'Solemnidad de la Natividad del Señor', 'El Verbo se hizo carne y habitó entre nosotros', 'El mensajero de paz de Isaías y el prólogo del Evangelio según san Juan.', 'Is 52,7-10', 'Jn 1,1-18', 'Solemnidad · Lectura + Evangelio', false, true, '[{"id":"dq-2026-12-25-1","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":1,"prompt":"En la primera lectura de Navidad, ¿qué anuncia sobre las montañas el mensajero de Isaías?","options":["La paz, la Buena Noticia y la salvación: \"¡Tu Dios reina!\"","El inicio de un censo imperial","El cierre del Templo","Una nueva batalla en el desierto"],"correctIndex":0,"explanation":"El nacimiento de Jesús cumple la esperanza de Israel y lleva la alegría de la salvación hasta los confines de la tierra.","sourceRef":"Is 52,7 · CIC 525"},{"id":"dq-2026-12-25-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Con qué palabras comienza el célebre Prólogo del Evangelio de san Juan que se proclama en Navidad?","options":["\"En el principio existía la Palabra (el Verbo), y la Palabra estaba junto a Dios, y la Palabra era Dios\"","\"Libro de la genealogía de Abraham\"","\"En tiempos del emperador César Augusto\"","\"Dichosos los pobres de espíritu\""],"correctIndex":0,"explanation":"San Juan revela la divinidad eterna del Hijo antes de contemplar su humilde nacimiento entre nosotros.","sourceRef":"Jn 1,14 · CIC 461"},{"id":"dq-2026-12-25-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"Según el Evangelio de hoy, ¿qué poder concedió la Palabra hecha carne a todos los que la recibieron y creen en su Nombre?","options":["Gobernar reinos terrenos","Llegar a ser hijos de Dios","No envejecer nunca","Poseer tesoros ocultos"],"correctIndex":1,"explanation":"El Hijo de Dios se hizo hombre para que nosotros pudiéramos participar de la filiación divina.","sourceRef":"Jn 1,14 · CIC 460"},{"id":"dq-2026-12-25-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿En qué ciudad nació Jesús y fue acostado en un pesebre por María y José?","options":["Nazaret","Belén de Judea","Cafarnaúm","Jericó"],"correctIndex":1,"explanation":"Belén (\"casa del pan\"), la ciudad de David, acogió en pobreza al Salvador del mundo.","sourceRef":"Lc 2,4-7 · CIC 525"},{"id":"dq-2026-12-25-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué misterio central celebramos en la Navidad al proclamar \"Y la Palabra se hizo carne\"?","options":["La Ascensión","La Encarnación","Pentecostés","La Transfiguración"],"correctIndex":1,"explanation":"La Encarnación es el misterio de la unión admirable de la naturaleza divina y la naturaleza humana en la única Persona del Verbo.","sourceRef":"Jn 1,14 · CIC 461"}]'::jsonb),
  ('2026-11-30'::date, 'Lectura + Evangelio · El Buen Pastor', 'Yo soy el Buen Pastor', 'El pastor prometido por Dios y Jesús que conoce y da la vida por sus ovejas.', 'Ez 34,11-16', 'Jn 10,11-18', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-rot-pastor-1","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":1,"prompt":"En la primera lectura del profeta Ezequiel, ¿qué promete hacer Dios mismo con las ovejas perdidas y heridas?","options":["Dejarlas a su suerte","Buscar a la perdida, traer a la descarriada y vendar a la herida","Encargarle todo a los extranjeros","Cerrar el redil para siempre"],"correctIndex":1,"explanation":"Dios se revela como un Pastor tierno y cercano que sale personalmente al encuentro de quien sufre o se ha alejado.","sourceRef":"Ez 34,11-16 · CIC 754"},{"id":"dq-rot-pastor-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de san Juan, ¿qué distingue al Buen Pastor del asalariado cuando ve venir al lobo?","options":["El asalariado huye; el Buen Pastor da la vida por sus ovejas","El Buen Pastor pide refuerzos y se marcha","Ambos actúan igual","El asalariado construye una torre"],"correctIndex":0,"explanation":"Jesús no nos ama por interés sino con entrega total hasta la Cruz, para que tengamos vida en abundancia.","sourceRef":"Jn 10,11 · CIC 754"},{"id":"dq-rot-pastor-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué relación íntima describe Jesús entre Él y sus ovejas?","options":["\"Yo conozco a mis ovejas y ellas me conocen a mí\"","\"Solo las veo desde lejos\"","\"No importa si escuchan mi voz\"","\"Cada oveja camina sin guía\""],"correctIndex":0,"explanation":"El Señor nos llama a cada uno por nuestro nombre e invita a reconocer su voz en la Escritura y la oración.","sourceRef":"Jn 10,11 · CIC 754"},{"id":"dq-rot-pastor-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Qué expresa Jesús cuando dice: \"Tengo otras ovejas que no son de este redil... habrá un solo rebaño y un solo pastor\"?","options":["La vocación universal de la Iglesia a reunir a todos los pueblos en Cristo","Que solo Israel será salvado","Que las ovejas deben dividirse en muchos grupos rivales","Una metáfora agrícola sin sentido espiritual"],"correctIndex":0,"explanation":"La Iglesia es católica (universal) porque Cristo quiere congregar en la unidad del amor a toda la humanidad.","sourceRef":"Jn 17,21 · CIC 830"},{"id":"dq-rot-pastor-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿Cómo entrega Jesús su vida según el final del Evangelio de hoy?","options":["Forzado contra su voluntad","Libremente, por amor al Padre y a los hombres","Por un accidente imprevisto","Sin saber lo que sucedería"],"correctIndex":1,"explanation":"\"Nadie me quita la vida, sino que yo la doy por mí mismo\": la entrega de Cristo es el acto supremo de libertad y amor.","sourceRef":"Jn 10,11 · CIC 609"}]'::jsonb),
  ('2026-12-01'::date, 'Lectura + Evangelio · Las Bienaventuranzas', 'El camino de la verdadera felicidad', 'El pueblo humilde del profeta Sofonías y el Sermón de la Montaña.', 'Sof 2,3; 3,12-13', 'Mt 5,1-12', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-rot-bien-1","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":2,"prompt":"En la primera lectura del profeta Sofonías, ¿qué pueblo promete dejar el Señor en medio de Israel?","options":["Un pueblo poderoso y orgulloso","Un pueblo humilde y pobre que busca refugio en el nombre del Señor","Un ejército invencible","Una corte de sabios ricos"],"correctIndex":1,"explanation":"Los \"pobres de Yahvé\" (anawim) preparan el corazón para recibir el Evangelio de las Bienaventuranzas.","sourceRef":"Sof 3,12 · CIC 2546"},{"id":"dq-rot-bien-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Con qué primera bienaventuranza inicia Jesús el Sermón de la Montaña?","options":["\"Felices los que tienen alma de pobres, porque a ellos les pertenece el Reino de los Cielos\"","\"Felices los que acumulan grandes fortunas\"","\"Felices los que nunca lloran\"","\"Felices los que vencen a sus enemigos\""],"correctIndex":0,"explanation":"La pobreza de espíritu es la humildad de sabernos necesitados de Dios, abierta a recibir su gracia.","sourceRef":"Mt 5,1-12 · CIC 1716"},{"id":"dq-rot-bien-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"Según el Evangelio de hoy, ¿quiénes \"verán a Dios\"?","options":["Los que tienen el corazón puro","Los que hablan más fuerte","Los que conocen más lenguas","Los que gobiernan ciudades"],"correctIndex":0,"explanation":"La pureza de corazón nos permite ver según Dios, recibir al prójimo con amor limpio y contemplar al Señor.","sourceRef":"Mt 5,1-12 · CIC 2518"},{"id":"dq-rot-bien-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Cómo serán llamados quienes trabajan por la paz según las Bienaventuranzas?","options":["Reyes de la tierra","Hijos de Dios","Jueces de Israel","Maestros de la Ley"],"correctIndex":1,"explanation":"Quienes siembran reconciliación, diálogo y perdón reflejan el rostro mismo del Padre celestial.","sourceRef":"Mt 5,9 · CIC 2305"},{"id":"dq-rot-bien-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"Según el Catecismo, ¿qué dibujan las Bienaventuranzas en el corazón de la predicación de Jesús?","options":["El rostro mismo de Jesucristo y su caridad","Un código difícil e inalcanzable","Consejos opcionales solo para monjes","Reglas antiguas ya derogadas"],"correctIndex":0,"explanation":"Las Bienaventuranzas responden al deseo natural de felicidad que Dios puso en el corazón humano.","sourceRef":"Mt 5,1-12 · CIC 1717"}]'::jsonb),
  ('2026-12-02'::date, 'Lectura + Evangelio · El Pan de Vida', 'Yo soy el Pan vivo bajado del cielo', 'El maná en el desierto y el discurso eucarístico de Jesús en Cafarnaúm.', 'Éx 16,14-15', 'Jn 6,51-58', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-rot-pan-1","topicId":"11111111-1111-4111-8111-111111111101","topicSlug":"antiguo-testamento","difficulty":1,"prompt":"En la primera lectura del Éxodo, ¿cómo respondió Moisés al pueblo sorprendido ante el maná en el desierto?","options":["\"Es el pan que el Señor les da para comer\"","\"Guárdenlo durante un año entero\"","\"Es trigo traído de Egipto\"","\"Solo los ancianos pueden probarlo\""],"correctIndex":0,"explanation":"El maná alimentó diariamente a Israel en su peregrinación, enseñándole a confiar en la providencia cotidiana de Dios.","sourceRef":"Éx 16,14-15 · CIC 1094"},{"id":"dq-rot-pan-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿qué promete Jesús a quien come del Pan vivo bajado del cielo?","options":["Que vivirá eternamente","Que nunca trabajará más","Que será famoso en Galilea","Que tendrá muchas riquezas"],"correctIndex":0,"explanation":"La Eucaristía es prenda de la resurrección futura y alimento que sostiene nuestra vida espiritual hoy.","sourceRef":"Jn 6,51 · CIC 1324"},{"id":"dq-rot-pan-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué explica Jesús claramente que es el pan que Él dará para la vida del mundo?","options":["Un simple recuerdo literario","Su propia carne entregada por la vida del mundo","Las tablas de la Ley","El maná del Sinaí"],"correctIndex":1,"explanation":"Jesús anuncia con realismo el don de su Cuerpo y su Sangre que instituirá en la Última Cena.","sourceRef":"Jn 6,51 · CIC 1376"},{"id":"dq-rot-pan-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"Según Jesús en este pasaje, ¿qué unión profunda produce comulgar su Cuerpo y beber su Sangre?","options":["\"Permanece en mí y yo en él\"","\"Camina solo por su cuenta\"","\"Ya no necesita a la comunidad\"","\"Solo lo recuerda una vez al año\""],"correctIndex":0,"explanation":"El fruto principal de la Comunión es la unión íntima con Cristo Jesús y con todos los miembros de su Iglesia.","sourceRef":"Jn 6,51 · CIC 1391"},{"id":"dq-rot-pan-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"¿En qué lugar pronunció Jesús este discurso sobre el Pan de Vida?","options":["En la sinagoga de Cafarnaúm","En el monte Sinaí","En Belén","En la isla de Patmos"],"correctIndex":0,"explanation":"Al día siguiente de multiplicar los panes, Jesús reveló en Cafarnaúm que Él mismo es el verdadero alimento espiritual.","sourceRef":"Jn 6,9-13 · CIC 1335"}]'::jsonb),
  ('2026-12-03'::date, 'Lectura + Evangelio · La Vid y los sarmientos', 'Permanezcan en mi amor', 'La fidelidad de san Pablo en la fe y la unión vital con Cristo, verdadera Vid.', '1 Jn 3,18-24', 'Jn 15,1-8', 'Lectura + Evangelio del día', false, true, '[{"id":"dq-rot-vid-1","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En la primera lectura de la primera carta de san Juan, ¿cómo nos exhorta el apóstol a amar?","options":["Solo con palabras bonitas","No de palabra ni de labios afuera, sino con obras y de verdad","Únicamente a quienes piensan igual","En secreto sin ayudar a nadie"],"correctIndex":1,"explanation":"La caridad auténtica se verifica en gestos concretos de cercanía, servicio y compasión hacia el hermano.","sourceRef":"1 Jn 3,18 · CIC 1823"},{"id":"dq-rot-vid-2","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"En el Evangelio de hoy, ¿qué imagen usa Jesús para explicar nuestra unión vital con Él?","options":["\"Yo soy la vid verdadera, ustedes son los sarmientos\"","\"Yo soy el mar, ustedes son las olas\"","\"Yo soy la torre, ustedes son las puertas\"","\"Yo soy el reloj, ustedes son las horas\""],"correctIndex":0,"explanation":"Así como el sarmiento recibe la savia del tronco, el cristiano recibe la vida de la gracia permaneciendo unido a Cristo.","sourceRef":"Jn 15,1-8 · CIC 755"},{"id":"dq-rot-vid-3","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":1,"prompt":"¿Qué afirma Jesús sobre lo que podemos hacer separados de Él?","options":["\"Pueden lograr casi todo solos\"","\"Sin mí no pueden hacer nada\"","\"Solo necesitan esfuerzo humano\"","\"Conviene probar por separado\""],"correctIndex":1,"explanation":"Todo fruto espiritual duradero nace de la gracia de Dios actuando en colaboración con nuestra libertad.","sourceRef":"Jn 15,1-8 · CIC 2074"},{"id":"dq-rot-vid-4","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"En la alegoría de la vid, ¿quién es el viñador que poda los sarmientos para que den más fruto?","options":["El Padre celestial","San Pedro","Moisés","Los escribas"],"correctIndex":0,"explanation":"La \"poda\" simboliza la purificación que Dios realiza con paciencia en nosotros mediante su Palabra y las pruebas de la vida.","sourceRef":"Jn 15,1-8 · CIC 755"},{"id":"dq-rot-vid-5","topicId":"11111111-1111-4111-8111-111111111102","topicSlug":"nuevo-testamento","difficulty":2,"prompt":"Según el versículo final del Evangelio de hoy, ¿cómo es glorificado el Padre?","options":["En que demos fruto abundante y seamos discípulos de Jesús","En que compitamos unos con otros","En que guardemos el Evangelio oculto","En que evitemos cualquier compromiso"],"correctIndex":0,"explanation":"Una vida fecunda en caridad, alegría, paz y servicio manifiesta al mundo la gloria de Dios.","sourceRef":"Jn 15,1-8 · CIC 1832"}]'::jsonb)
