-- ============================================================================
-- Trivia Católica — Migración 006:
-- 1. Vinculación de preguntas a nivel específico (questions.level_id)
-- 2. Tabla administrable y programable public.daily_challenges (Lectura + Evangelio)
-- 3. 8 categorías (sumando Movimientos y Carismas + Historia de la Iglesia)
-- 4. 32 niveles y 160 preguntas doctrinales vinculadas a su nivel con citas completas
-- 5. Banco completo de textos de referencia (Biblia + CIC + IGMR) en reference_texts
-- 6. Desafíos diarios iniciales por Lectura + Evangelio del día
--
-- 100% idempotente: se puede correr más de una vez en el SQL Editor sin duplicar.
-- ============================================================================

-- 1. Vincular preguntas directamente a su nivel (cuestionario)
alter table public.questions
  add column if not exists level_id uuid references public.levels(id) on delete set null;

create index if not exists idx_questions_level
  on public.questions(level_id)
  where is_active = true;

-- 2. Tabla de Desafíos del Día (administrable por fecha + sincronización diaria)
create table if not exists public.daily_challenges (
  id uuid primary key default gen_random_uuid(),
  challenge_date date unique not null,
  liturgical_day text not null,
  title text not null,
  subtitle text,
  first_reading_ref text not null default '',
  gospel_ref text not null default '',
  source_label text not null default 'Lectura + Evangelio del día',
  is_custom boolean not null default false,
  is_active boolean not null default true,
  questions jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists idx_daily_challenges_date
  on public.daily_challenges(challenge_date desc)
  where is_active = true;

alter table public.daily_challenges enable row level security;

drop policy if exists "Lectura pública de desafíos diarios activos" on public.daily_challenges;
create policy "Lectura pública de desafíos diarios activos"
  on public.daily_challenges for select using (is_active = true);

-- 3. Categorías (8 en total: grilla pareja 4x2 en Inicio)
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  icon = excluded.icon,
  color_token = excluded.color_token,
  sort_order = excluded.sort_order;

-- 4. Niveles (32 cuestionarios en total)
on conflict (id) do update set
  slug = excluded.slug,
  level_number = excluded.level_number,
  global_order = excluded.global_order,
  title = excluded.title,
  subtitle = excluded.subtitle,
  difficulty = excluded.difficulty,
  questions_per_round = excluded.questions_per_round,
  is_premium = excluded.is_premium;

-- 5. Banco de 160 preguntas vinculadas 1 a 1 con su nivel y citas completas
with q_seed(topic_id, level_id, difficulty, prompt, options, correct_index, explanation, source_ref) as (
  values
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222101'::uuid, 1::smallint, '¿A quién le pidió Dios que construyera el arca antes del diluvio?', '["Moisés","Noé","Abraham","Elías"]'::jsonb, 1::smallint, 'Dios encomendó a Noé construir el arca para salvar a su familia y a los animales, prefigurando la salvación por el Bautismo.', 'Gn 6,14 · CIC 1219'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222101'::uuid, 1::smallint, '¿En qué monte recibió Moisés las tablas de los Diez Mandamientos?', '["Monte Carmelo","Monte Tabor","Monte Sinaí","Monte de los Olivos"]'::jsonb, 2::smallint, 'En el monte Sinaí Dios selló la Alianza con Israel y entregó a Moisés el Decálogo como camino de vida.', 'Éx 19,20; 20,1-17 · CIC 2056'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222101'::uuid, 1::smallint, '¿Quién es llamado en la Escritura el "padre de todos los creyentes"?', '["Isaac","Jacob","Abraham","David"]'::jsonb, 2::smallint, 'Abraham creyó en la promesa de Dios y partió hacia la tierra prometida, convirtiéndose en modelo de obediencia en la fe.', 'Gn 12,1-4 · CIC 145'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222101'::uuid, 1::smallint, '¿A imagen y semejanza de quién creó Dios al ser humano, varón y mujer?', '["De los ángeles","De Dios mismo","De las estrellas","De los profetas"]'::jsonb, 1::smallint, 'El libro del Génesis enseña que cada persona posee una dignidad inviolable por haber sido creada a imagen y semejanza de Dios.', 'Gn 1,27 · CIC 355'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222101'::uuid, 1::smallint, '¿Qué nombre nuevo recibió Jacob después de luchar con el ángel de Dios?', '["Israel","Judá","Josué","Samuel"]'::jsonb, 0::smallint, 'Dios cambió el nombre de Jacob por Israel ("el que es fuerte con Dios"), y de sus doce hijos nacieron las doce tribus del pueblo elegido.', 'Gn 32,29 · CIC 2573'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222102'::uuid, 2::smallint, '¿Qué rey de Israel compuso gran parte de los Salmos?', '["Saúl","David","Salomón","Josías"]'::jsonb, 1::smallint, 'La tradición bíblica atribuye al rey David la mayoría de los Salmos, oración inspirada de Israel y de la Iglesia.', '2 Sam 23,1-2 · CIC 2579'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222102'::uuid, 2::smallint, '¿Qué profeta anunció que una virgen concebiría y daría a luz a Emmanuel?', '["Jeremías","Ezequiel","Isaías","Daniel"]'::jsonb, 2::smallint, 'Isaías profetizó el nacimiento de Emmanuel, "Dios con nosotros", promesa cumplida plenamente en Jesucristo.', 'Is 7,14 · Mt 1,22-23 · CIC 497'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222102'::uuid, 2::smallint, '¿Qué pidió el joven rey Salomón a Dios cuando el Señor le ofreció concederle un don?', '["Riquezas y poder militar","Un corazón sabio para gobernar con justicia","Larga vida sin enfermedades","La conquista de Egipto"]'::jsonb, 1::smallint, 'Salomón pidió sabiduría y discernimiento para servir a su pueblo, y luego edificó el primer Templo de Jerusalén.', '1 Re 3,9 · CIC 2580'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222102'::uuid, 2::smallint, '¿En qué signo reconoció el profeta Elías la presencia de Dios en el monte Horeb?', '["En un huracán impetuoso","En un terremoto","En el susurro de una brisa suave","En una columna de fuego"]'::jsonb, 2::smallint, 'Dios no estaba en el viento, el terremoto ni el fuego, sino en el murmullo de una brisa suave, invitando a la escucha interior.', '1 Re 19,11-13 · CIC 2583'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222102'::uuid, 2::smallint, '¿Qué profeta fue preservado ileso en el foso de los leones por mantenerse fiel a la oración?', '["Oseas","Daniel","Amós","Jonás"]'::jsonb, 1::smallint, 'Daniel siguió orando tres veces al día al Dios verdadero pese al decreto del rey, y el Señor envió a su ángel para protegerlo.', 'Dn 6,17-23 · CIC 2568'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222103'::uuid, 3::smallint, '¿Qué libro deuterocanónico del Antiguo Testamento fundamenta la oración por los difuntos?', '["Segundo libro de los Macabeos","Libro de Rut","Eclesiastés","Lamentaciones"]'::jsonb, 0::smallint, 'En 2 Macabeos, Judas Macabeo ofrece sacrificios y oraciones por los caídos, gesto que la Iglesia cita para orar por los difuntos.', '2 Mac 12,43-46 · CIC 1032'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222103'::uuid, 3::smallint, '¿Cuántos libros componen el Antiguo Testamento en el canon de la Biblia católica?', '["39 libros","46 libros","27 libros","52 libros"]'::jsonb, 1::smallint, 'El canon católico reconoce 46 libros en el Antiguo Testamento (incluidos los 7 deuterocanónicos) y 27 en el Nuevo: 73 libros en total.', 'CIC 120'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222103'::uuid, 3::smallint, '¿Qué personaje del Antiguo Testamento es modelo de paciencia y confianza en Dios en medio del sufrimiento?', '["Job","Tobías","Nehemías","Esdras"]'::jsonb, 0::smallint, 'Aun en la prueba extrema, Job dialoga con Dios con sinceridad y proclama: "Yo sé que mi Redentor vive".', 'Job 19,25 · CIC 1502'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222103'::uuid, 3::smallint, 'Según el libro de los Proverbios, ¿cuál es "el principio de la sabiduría"?', '["El estudio de la astronomía","El temor del Señor","La elocuencia pública","La experiencia de los viajes"]'::jsonb, 1::smallint, 'El temor de Dios no es miedo, sino reverencia filial y amor respetuoso que orienta la vida hacia el bien.', 'Prov 9,10 · CIC 1831'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222103'::uuid, 3::smallint, '¿Qué arcángel acompaña y guía al joven Tobías en el libro deuterocanónico de Tobías?', '["San Miguel","San Gabriel","San Rafael","Uriel"]'::jsonb, 2::smallint, 'Rafael significa "Dios sana"; acompañó a Tobías en su viaje, devolvió la vista a su padre y reveló ser uno de los siete ángeles ante el Señor.', 'Tob 12,15 · CIC 332'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222104'::uuid, 2::smallint, '¿A través de qué signo se reveló Dios a Moisés diciendo "Yo soy el que soy"?', '["Una nube sobre el río Nilo","Una zarza que ardía sin consumirse","Un arco iris en el desierto","Una paloma sobre el altar"]'::jsonb, 1::smallint, 'En el Horeb, desde la zarza ardiente, Dios reveló su Nombre a Moisés y lo envió a liberar a Israel de la esclavitud en Egipto.', 'Éx 3,1-14 · CIC 206'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222104'::uuid, 2::smallint, '¿Con qué alimento milagroso sostuvo Dios a Israel durante los cuarenta años en el desierto?', '["Higos y miel","El maná","Pan ázimo de Egipto","Trigo del Jordán"]'::jsonb, 1::smallint, 'El maná caído del cielo cada mañana prefiguraba a Jesús, el verdadero Pan vivo bajado del cielo en la Eucaristía.', 'Éx 16,14-15 · Jn 6,31-35 · CIC 1094'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222104'::uuid, 2::smallint, '¿Qué signo prefiguraba el Bautismo cuando Israel salió de Egipto guiado por Moisés?', '["El paso del mar Rojo","La construcción de las pirámides","El sueño de Faraón","La venta de José"]'::jsonb, 0::smallint, 'Al atravesar las aguas del mar Rojo hacia la libertad, Israel vivió una figura del Bautismo que nos libera de la esclavitud del pecado.', 'Éx 14,21-22 · CIC 1221'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222104'::uuid, 2::smallint, '¿Quién sucedió a Moisés para conducir al pueblo de Israel hacia la Tierra Prometida?', '["Aarón","Josué","Gedeón","Sansón"]'::jsonb, 1::smallint, 'Josué (cuyo nombre hebreo significa "Dios salva", igual que Jesús) guió a Israel en el paso del río Jordán hacia Canaán.', 'Jos 1,1-6 · CIC 430'),
  ('11111111-1111-4111-8111-111111111101'::uuid, '22222222-2222-4222-8222-222222222104'::uuid, 2::smallint, '¿Qué cofre sagrado guardaba las tablas de la Ley y acompañaba a Israel como signo de la presencia de Dios?', '["El Arca de la Alianza","El Candelabro de los siete brazos","La Copa de Melquisedec","El Altar de Betel"]'::jsonb, 0::smallint, 'El Arca de la Alianza contenía las tablas del Decálogo; los Padres de la Iglesia ven en ella una figura de María, que llevó en su seno al Verbo hecho carne.', 'Éx 25,10-16 · CIC 2676'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222201'::uuid, 1::smallint, '¿Cuál fue el primer milagro público de Jesús narrado en el Evangelio de san Juan?', '["La multiplicación de los panes","Convertir el agua en vino en Caná","Caminar sobre las aguas","La resurrección de Lázaro"]'::jsonb, 1::smallint, 'A pedido de su Madre María en las bodas de Caná, Jesús transformó el agua en vino y manifestó su gloria.', 'Jn 2,1-11 · CIC 2618'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222201'::uuid, 1::smallint, '¿Con cuántos panes y peces alimentó Jesús a una multitud de cinco mil hombres?', '["Tres panes y un pez","Cinco panes y dos peces","Siete panes y cinco peces","Doce panes y dos peces"]'::jsonb, 1::smallint, 'Con cinco panes de cebada y dos peces Jesús sació a la multitud, prefigurando la sobreabundancia de la Eucaristía.', 'Jn 6,9-13 · CIC 1335'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222201'::uuid, 1::smallint, '¿A qué amigo suyo, hermano de Marta y María, resucitó Jesús en Betania después de cuatro días en el sepulcro?', '["Zaqueo","Lázaro","Bartimeo","Nicodemo"]'::jsonb, 1::smallint, 'Antes de llamar a Lázaro fuera de la tumba, Jesús se proclamó "la Resurrección y la Vida", anunciando su propia victoria sobre la muerte.', 'Jn 11,25-44 · CIC 640'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222201'::uuid, 1::smallint, 'Cuando diez leprosos fueron curados por Jesús, ¿cuántos regresaron a darle gracias?', '["Todos","Cinco","Tres","Solo uno, un samaritano"]'::jsonb, 3::smallint, 'Solo el samaritano volvió alabando a Dios y se postró a los pies de Jesús, enseñándonos la importancia de la gratitud en la fe.', 'Lc 17,11-19 · CIC 2638'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222201'::uuid, 1::smallint, '¿Qué le dijo Jesús al viento y al mar embravecido para calmar la tempestad desde la barca?', '["\"¡Silencio, cálmate!\"","\"¡Abran las redes!\"","\"¡Vuelvan a la orilla!\"","\"¡Sube a la montaña!\""]'::jsonb, 0::smallint, 'Con su sola palabra Jesús devolvió una gran calma, revelando su poder divino y pidiendo a los discípulos no tener miedo.', 'Mc 4,35-41 · CIC 547'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222202'::uuid, 2::smallint, '¿A qué apóstol le dijo Jesús: "Tú eres Pedro, y sobre esta piedra edificaré mi Iglesia"?', '["San Juan","Santiago","Simón Pedro","San Andrés"]'::jsonb, 2::smallint, 'Tras la confesión de fe de Simón en Cesarea de Filipo, Jesús le confió las llaves del Reino y el ministerio de unidad.', 'Mt 16,18-19 · CIC 552'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222202'::uuid, 2::smallint, '¿En qué Evangelio se encuentra la parábola del Hijo Pródigo?', '["San Mateo","San Marcos","San Lucas","San Juan"]'::jsonb, 2::smallint, 'El Evangelio de san Lucas recoge esta parábola en el capítulo 15 para mostrar la misericordia infinita del Padre.', 'Lc 15,11-32 · CIC 1439'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222202'::uuid, 2::smallint, 'En la parábola del Buen Samaritano, ¿qué nos enseña Jesús sobre quién es nuestro prójimo?', '["Solo los familiares y vecinos cercanos","Toda persona necesitada a quien nos acercamos con compasión","Únicamente quienes comparten la misma ciudad","Quienes pueden devolvernos el favor"]'::jsonb, 1::smallint, 'El samaritano se detuvo, vendó las heridas y cuidó al hombre asaltado; Jesús concluye: "Ve y haz tú lo mismo".', 'Lc 10,29-37 · CIC 1932'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222202'::uuid, 2::smallint, '¿Qué oficio tenía san Mateo antes de ser llamado por Jesús a seguirlo?', '["Pescador en Galilea","Recaudador de impuestos","Carpintero en Nazaret","Médico en Antioquía"]'::jsonb, 1::smallint, 'Jesús llamó a Mateo sentado en la mesa de recaudación y comió con pecadores para mostrar que vino a llamar a conversión.', 'Mt 9,9-13 · CIC 545'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222202'::uuid, 2::smallint, 'En la parábola del sembrador, ¿qué representa la semilla que cae en tierra buena?', '["Quien escucha la Palabra, la acoge y da fruto abundante","Quien acumula cosechas para sí mismo","Quien olvida la Palabra por las preocupaciones","Quien escucha sin poner en práctica"]'::jsonb, 0::smallint, 'La tierra buena simboliza el corazón dócil y perseverante donde la Palabra de Dios produce fruto al treinta, sesenta y ciento por uno.', 'Mt 13,1-23 · CIC 546'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222203'::uuid, 3::smallint, '¿Qué fiesta celebraban los discípulos cuando descendió el Espíritu Santo en lenguas de fuego?', '["Pascua","Pentecostés","Tabernáculos","Dedicación"]'::jsonb, 1::smallint, 'Cincuenta días después de la Resurrección, en Pentecostés, el Espíritu Santo fue derramado y la Iglesia comenzó su misión universal.', 'Hch 2,1-4 · CIC 731'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222203'::uuid, 3::smallint, '¿En qué carta escribió san Pablo el célebre himno a la caridad ("El amor es paciente, es servicial")?', '["Carta a los Romanos","Primera carta a los Corintios","Carta a los Efesios","Carta a los Gálatas"]'::jsonb, 1::smallint, 'En 1 Corintios 13, san Pablo enseña que la caridad es el mayor de todos los dones y el vínculo de la perfección.', '1 Cor 13,4-13 · CIC 1826'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222203'::uuid, 3::smallint, '¿Camino a qué ciudad tuvo Saulo de Tarso su encuentro con Cristo resucitado?', '["Antioquía","Damasco","Corinto","Éfeso"]'::jsonb, 1::smallint, 'Camino a Damasco Jesús le dijo: "Saulo, ¿por qué me persigues?", revelando la unión íntima entre Cristo y su Iglesia.', 'Hch 9,1-6 · CIC 795'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222203'::uuid, 3::smallint, '¿Qué enseña la Carta de Santiago sobre la relación entre la fe y las obras?', '["Que las obras no tienen valor alguno","Que la fe sin obras está muerta","Que solo importan las obras externas","Que la fe solo es para los apóstoles"]'::jsonb, 1::smallint, 'Santiago recuerda que la fe viva se manifiesta necesariamente en el amor concreto y en el servicio a los hermanos.', 'Sant 2,14-17 · CIC 1815'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222203'::uuid, 3::smallint, '¿En qué isla del mar Egeo recibió san Juan las visiones del libro del Apocalipsis?', '["Chipre","Creta","Patmos","Malta"]'::jsonb, 2::smallint, 'Desterrado en la isla de Patmos por su testimonio de Jesús, Juan escribió el Apocalipsis para alentar la esperanza de las comunidades.', 'Ap 1,9 · CIC 1137'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222204'::uuid, 2::smallint, '¿Qué gesto de humildad realizó Jesús con sus discípulos durante la Última Cena?', '["Les lavó los pies","Les entregó una túnica blanca","Los llevó al monte Tabor","Les impuso ceniza en la frente"]'::jsonb, 0::smallint, 'Al lavarles los pies, Jesús dio ejemplo de servicio humilde y les dejó el mandamiento nuevo: "Ámense los unos a los otros como yo los he amado".', 'Jn 13,12-15 · CIC 1823'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222204'::uuid, 2::smallint, '¿Quién fue obligado por los soldados romanos a ayudar a Jesús a cargar la cruz camino al Calvario?', '["José de Arimatea","Simón de Cirene","Nicodemo","Cleofás"]'::jsonb, 1::smallint, 'Simón de Cirene cargó la cruz detrás de Jesús, convirtiéndose en imagen de todo discípulo llamado a compartir la cruz de Cristo.', 'Lc 23,26 · CIC 618'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222204'::uuid, 2::smallint, '¿A quién se apareció primero Jesús resucitado junto al sepulcro vacío, según san Juan?', '["A Pedro","A María Magdalena","A Tomás","A Santiago"]'::jsonb, 1::smallint, 'Jesús llamó por su nombre a María Magdalena y la envió a anunciar la Resurrección a los apóstoles; por eso la tradición la llama "apóstol de los apóstoles".', 'Jn 20,11-18 · CIC 641'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222204'::uuid, 2::smallint, '¿En qué gesto reconocieron a Jesús resucitado los dos discípulos camino de Emaús?', '["Al multiplicar los peces","Al partir el pan","Al caminar sobre el lago","Al entrar en el Templo"]'::jsonb, 1::smallint, 'Después de explicarles las Escrituras, Jesús se sentó a la mesa y al partir el pan se les abrieron los ojos: imagen de la Santa Misa.', 'Lc 24,30-35 · CIC 1347'),
  ('11111111-1111-4111-8111-111111111102'::uuid, '22222222-2222-4222-8222-222222222204'::uuid, 2::smallint, '¿Qué profesión de fe exclamó el apóstol Tomás al ver a Jesús resucitado?', '["\"¡Señor mío y Dios mío!\"","\"¡Hágase tu voluntad!\"","\"¡Tú eres el Rey de Israel!\"","\"¡Hosanna en las alturas!\""]'::jsonb, 0::smallint, 'La exclamación de Tomás es una de las confesiones más claras de la divinidad de Cristo en todo el Nuevo Testamento.', 'Jn 20,28 · CIC 448'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222301'::uuid, 1::smallint, '¿Qué santo de Asís compuso el "Cántico de las Criaturas" y abrazó la pobreza evangélica?', '["San Antonio de Padua","San Francisco de Asís","Santo Domingo de Guzmán","San Benito"]'::jsonb, 1::smallint, 'San Francisco de Asís vivió radicalmente el Evangelio y alabó a Dios a través de toda la creación.', 'Mt 19,21 · CIC 344'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222301'::uuid, 1::smallint, '¿Qué santa carmelita es conocida por su "caminito" de confianza espiritual y es patrona de las misiones?', '["Santa Teresa de Ávila","Santa Teresita del Niño Jesús","Santa Clara de Asís","Santa Faustina Kowalska"]'::jsonb, 1::smallint, 'Santa Teresa de Lisieux mostró que la santidad está al alcance de todos mediante los pequeños actos hechos con gran amor.', 'Mt 18,3 · CIC 2011'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222301'::uuid, 1::smallint, '¿Quién fue el esposo de la Virgen María y padre adoptivo de Jesús?', '["San Joaquín","San Zacarías","San José","San Simeón"]'::jsonb, 2::smallint, 'San José, hombre justo y custodio de la Sagrada Familia, es venerado como patrono de la Iglesia universal.', 'Mt 1,19-24 · CIC 437'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222301'::uuid, 1::smallint, '¿Qué fraile franciscano de origen portugués es célebre predicador y se le suele representar con el Niño Jesús en brazos?', '["San Antonio de Padua","San Pío de Pietrelcina","San Isidro Labrador","San Martín de Porres"]'::jsonb, 0::smallint, 'San Antonio de Padua (1195-1231) fue declarado Doctor Evangélico por su profundo conocimiento de la Escritura y su amor a los pobres.', 'Lc 4,18 · CIC 828'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222301'::uuid, 1::smallint, '¿Qué sacerdote italiano del siglo XIX fundó los Salesianos dedicados a educar y acompañar a los jóvenes más pobres?', '["San Juan Bosco","San Felipe Neri","San Alfonso María de Ligorio","San Camilo de Lelis"]'::jsonb, 0::smallint, 'Don Bosco creó el Sistema Preventivo basado en razón, religión y amabilidad para formar "buenos cristianos y honrados ciudadanos".', 'Mc 10,14 · CIC 2229'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222302'::uuid, 2::smallint, '¿Qué Doctor de la Iglesia escribió las "Confesiones" y fue obispo de Hipona?', '["San Agustín","Santo Tomás de Aquino","San Jerónimo","San Ambrosio"]'::jsonb, 0::smallint, 'San Agustín narró su conversión en las Confesiones: "Nos hiciste, Señor, para ti, y nuestro corazón está inquieto hasta que descanse en ti".', 'Sal 63,2 · CIC 30'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222302'::uuid, 2::smallint, '¿Qué santo escribió la "Suma Teológica" y compuso himnos eucarísticos como el Pange Lingua?', '["San Buenaventura","Santo Tomás de Aquino","San Alberto Magno","San Anselmo"]'::jsonb, 1::smallint, 'Santo Tomás de Aquino armonizó fe y razón y profundizó admirablemente el misterio de la presencia real en la Eucaristía.', 'Jn 6,51 · CIC 1381'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222302'::uuid, 2::smallint, '¿Qué Doctor de la Iglesia tradujo la Biblia al latín (la Vulgata) y afirmó que "desconocer las Escrituras es desconocer a Cristo"?', '["San Gregorio Magno","San Jerónimo","San Basilio Magno","San Juan Crisóstomo"]'::jsonb, 1::smallint, 'San Jerónimo dedicó su vida en Belén al estudio y traducción de los libros sagrados, legado citado por el Vaticano II y el Catecismo.', '2 Tim 3,16 · CIC 133'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222302'::uuid, 2::smallint, '¿Qué santa mística española, reformadora del Carmelo, fue proclamada Doctora de la Iglesia y escribió "Las Moradas"?', '["Santa Teresa de Jesús (de Ávila)","Santa Hildegarda de Bingen","Santa Brígida de Suecia","Santa Gertrudis"]'::jsonb, 0::smallint, 'Santa Teresa de Ávila enseñó que la oración mental es "tratar de amistad, estando muchas veces tratando a solas con quien sabemos nos ama".', 'Jn 15,15 · CIC 2709'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222302'::uuid, 2::smallint, '¿Qué laica dominica del siglo XIV, Doctora de la Iglesia, trabajó incansablemente para que el Papa regresara de Aviñón a Roma?', '["Santa Catalina de Siena","Santa Rita de Casia","Santa Clara de Asís","Santa Ángela de Mérici"]'::jsonb, 0::smallint, 'Santa Catalina de Siena unió profunda vida mística con un amor valiente a la Iglesia y es copatrona de Europa.', 'Ef 4,3-4 · CIC 2013'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222303'::uuid, 3::smallint, '¿Quién fue la primera santa canonizada nacida en el continente americano?', '["Santa Mariana de Jesús","Santa Rosa de Lima","Santa Laura Montoya","Santa Kateri Tekakwitha"]'::jsonb, 1::smallint, 'Santa Rosa de Lima (1586-1617), terciaria dominica peruana, fue canonizada en 1671 y es patrona de América y Filipinas.', '1 Cor 12,31 · CIC 2013'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222303'::uuid, 3::smallint, '¿Qué sacerdote argentino recorrió a lomo de mula las sierras de Córdoba evangelizando y promoviendo caminos, escuelas y ejercicios espirituales?', '["San José Gabriel del Rosario Brochero","San Alberto Hurtado","San Roque González","San Toribio de Mogrovejo"]'::jsonb, 0::smallint, 'El Cura Brochero (1840-1914) se hizo "gaucho con los gauchos" y entregó su vida sirviendo a los más alejados hasta contraer lepra.', 'Jn 10,11 · CIC 1551'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222303'::uuid, 3::smallint, '¿Qué religioso dominico peruano, hijo de español y liberta africana, es patrono de la justicia social y célebre por su caridad hacia pobres y enfermos?', '["San Juan Macías","San Martín de Porres","San Francisco Solano","San Pedro Claver"]'::jsonb, 1::smallint, 'San Martín de Porres (1579-1639) sirvió en Lima como barbero, enfermero y limosnero, dando testimonio de humildad y fraternidad sin distinciones.', 'Mt 25,40 · CIC 2443'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222303'::uuid, 3::smallint, '¿Qué jesuita chileno fundó el "Hogar de Cristo" y animaba a preguntarse: "¿Qué haría Cristo en mi lugar?"?', '["San Alberto Hurtado","San Felipe de Jesús","San Rafael Guízar","San Pedro de Betancur"]'::jsonb, 0::smallint, 'San Alberto Hurtado (1901-1952) dedicó su ministerio a los jóvenes, los trabajadores y las personas en situación de calle.', 'Sant 2,14-17 · CIC 2447'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222303'::uuid, 3::smallint, '¿Qué papa del siglo XX convocó las Jornadas Mundiales de la Juventud y proclamó el Domingo de la Divina Misericordia?', '["San Pío X","San Juan XXIII","San Pablo VI","San Juan Pablo II"]'::jsonb, 3::smallint, 'San Juan Pablo II (1920-2005) impulsó la nueva evangelización, el diálogo con los jóvenes y promulgó el Catecismo de la Iglesia Católica en 1992.', 'Mt 28,19-20 · CIC 882'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222304'::uuid, 1::smallint, '¿Qué joven italiano llamó a la Eucaristía "mi autopista hacia el cielo" y creó una exposición digital sobre los milagros eucarísticos?', '["San Carlo Acutis","San Luis Gonzaga","San Estanislao de Kostka","San Tarcisio"]'::jsonb, 0::smallint, 'Carlo Acutis (1991-2006) usó la informática para evangelizar y vivió una profunda devoción diaria a la Santa Misa y a los pobres.', 'Jn 6,51 · CIC 1324'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222304'::uuid, 1::smallint, '¿Qué joven alpinista turinés, terciario dominico, hizo famosa la frase "Verso l’alto" ("Hacia lo alto") y ayudaba en secreto a las familias pobres?', '["San Pier Giorgio Frassati","San Gabriel de la Dolorosa","San Domingo Savio","San Juan Berchmans"]'::jsonb, 0::smallint, 'Pier Giorgio Frassati (1901-1925) unió alegría juvenil, amor a la montaña, adoración eucarística y servicio silencioso a los más necesitados.', 'Col 3,1-2 · CIC 2013'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222304'::uuid, 1::smallint, '¿Qué alumno de san Juan Bosco, fallecido a los 14 años, tenía como lema "Antes morir que pecar"?', '["San Domingo Savio","San Tarsicio","San Pancracio","San Casimiro"]'::jsonb, 0::smallint, 'San Domingo Savio (1842-1857) demostró en el oratorio de Turín que la santidad consiste en "estar siempre alegres" cumpliendo los deberes diarios.', 'Flp 4,4 · CIC 2015'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222304'::uuid, 1::smallint, '¿Qué joven mexicano de 14 años murió mártir en 1928 proclamando "¡Viva Cristo Rey y Santa María de Guadalupe!"?', '["San José Sánchez del Río","San Juan Diego","San Miguel Agustín Pro","San Cristóbal Magallanes"]'::jsonb, 0::smallint, 'San José Sánchez del Río se negó a renunciar a su fe durante la persecución cristera y perdonó a sus verdugos antes de morir.', 'Mt 10,32 · CIC 2473'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222304'::uuid, 1::smallint, '¿Qué joven laica italiana del Movimiento de los Focolares ofreció su enfermedad a los 18 años diciendo: "Si tú lo quieres, Jesús, yo también lo quiero"?', '["Beata Chiara Luce Badano","Santa María Goretti","Santa Josefina Bakhita","Santa Gianna Beretta Molla"]'::jsonb, 0::smallint, 'Chiara Luce Badano (1971-1990) vivió el cáncer con una serenidad luminosa y donó sus córneas para que otros pudieran ver.', 'Lc 22,42 · CIC 1505'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222305'::uuid, 2::smallint, '¿Quién fue el primer mártir cristiano, uno de los siete diáconos, que murió apedreado perdonando a quienes lo mataban?', '["San Lorenzo","San Esteban","San Ignacio de Antioquía","San Policarpo"]'::jsonb, 1::smallint, 'En los Hechos de los Apóstoles, san Esteban muere rezando como Jesús: "Señor, no les tengas en cuenta este pecado".', 'Hch 7,55-60 · CIC 2473'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222305'::uuid, 2::smallint, '¿Qué fraile franciscano polaco ofreció voluntariamente su vida en Auschwitz para salvar a un padre de familia?', '["San Maximiliano Kolbe","San Juan Nepomuceno","San Estanislao","San Casimiro"]'::jsonb, 0::smallint, 'San Maximiliano Kolbe (1894-1941), fundador de la Milicia de la Inmaculada, fue canonizado como "mártir de la caridad".', 'Jn 15,13 · CIC 2473'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222305'::uuid, 2::smallint, '¿Qué misionero jesuita llevó el Evangelio hasta la India y Japón, y es copatrono de las misiones junto con santa Teresita?', '["San Francisco Javier","San Ignacio de Loyola","San Pedro Canisio","San Roberto Belarmino"]'::jsonb, 0::smallint, 'San Francisco Javier (1506-1552) recorrió miles de kilómetros en Asia bautizando y anunciando a Cristo incansablemente.', 'Mc 16,15 · CIC 849'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222305'::uuid, 2::smallint, '¿Qué arzobispo de San Salvador fue asesinado mientras celebraba la Santa Misa en 1980 por defender a los pobres y la justicia?', '["San Óscar Arnulfo Romero","San José María de Yermo","San Ezequiel Moreno","San Rafael Arnáiz"]'::jsonb, 0::smallint, 'San Óscar Romero entregó su vida como pastor fiel; la Iglesia lo reconoce mártir por odio a la fe vivida en la caridad.', 'Jn 10,11 · CIC 2443'),
  ('11111111-1111-4111-8111-111111111103'::uuid, '22222222-2222-4222-8222-222222222305'::uuid, 2::smallint, '¿Qué santa fundó en Calcuta las Misioneras de la Caridad para servir a "los más pobres entre los pobres"?', '["Santa Teresa de Calcuta","Santa Bakhita","Santa Edith Stein","Santa Isabel de Hungría"]'::jsonb, 0::smallint, 'La Madre Teresa de Calcuta (1910-1997) reconocía el rostro de Cristo sufriente en cada enfermo abandonado y moribundo.', 'Mt 25,40 · CIC 2447'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222601'::uuid, 1::smallint, '¿Qué ángel le anunció a María que sería la Madre del Salvador?', '["Miguel","Rafael","Gabriel","Uriel"]'::jsonb, 2::smallint, 'El ángel Gabriel fue enviado a Nazaret, y María respondió con fe: "Hágase en mí según tu palabra".', 'Lc 1,26-38 · CIC 494'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222601'::uuid, 1::smallint, '¿A qué pariente visitó María después de la Anunciación?', '["A Ana, su madre","A su prima Isabel","A Marta de Betania","A María Magdalena"]'::jsonb, 1::smallint, 'En la Visitación, Isabel la saludó: "¡Bendita tú entre las mujeres y bendito el fruto de tu vientre!", palabras que rezamos en el Avemaría.', 'Lc 1,39-45 · CIC 2676'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222601'::uuid, 1::smallint, '¿En qué celebración Jesús hizo su primer milagro a pedido de María?', '["En la Pascua en Jerusalén","En la presentación en el Templo","En las bodas de Caná","En la multiplicación de los panes"]'::jsonb, 2::smallint, 'En Caná, María dijo a los sirvientes "Hagan todo lo que él les diga", y Jesús convirtió el agua en vino.', 'Jn 2,1-11 · CIC 2618'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222601'::uuid, 1::smallint, '¿Cómo se llama el cántico de alabanza que proclamó María en casa de Isabel ("Mi alma canta la grandeza del Señor")?', '["Benedictus","Magníficat","Gloria","Te Deum"]'::jsonb, 1::smallint, 'El Magníficat es el cántico de María y de toda la Iglesia; se reza cada tarde en las Vísperas de la Liturgia de las Horas.', 'Lc 1,46-55 · CIC 2619'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222601'::uuid, 1::smallint, 'Al pie de la cruz, ¿a qué discípulo confió Jesús el cuidado de su Madre diciendo "Mujer, ahí tienes a tu hijo"?', '["A Pedro","Al discípulo amado (san Juan)","A Santiago el Menor","A José de Arimatea"]'::jsonb, 1::smallint, 'Al entregar a María al discípulo amado, Jesús nos dio a su Madre como Madre espiritual de todos los creyentes.', 'Jn 19,25-27 · CIC 964'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222602'::uuid, 2::smallint, '¿Qué afirma el dogma de la Inmaculada Concepción?', '["Que Jesús fue concebido sin intervención de varón","Que María fue preservada del pecado original desde su concepción","Que María fue llevada al cielo en cuerpo y alma","Que María permaneció virgen toda su vida"]'::jsonb, 1::smallint, 'Pío IX lo proclamó en 1854: por singular gracia de Dios y en previsión de los méritos de Cristo, María fue preservada de toda mancha de pecado original.', 'Lc 1,28 · CIC 491'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222602'::uuid, 2::smallint, '¿Qué dogma mariano proclamó el papa Pío XII en 1950?', '["La Asunción","La Inmaculada Concepción","La Maternidad divina","La Virginidad perpetua"]'::jsonb, 0::smallint, 'La Virgen, terminado el curso de su vida terrena, fue asunta en cuerpo y alma a la gloria del cielo.', 'Ap 12,1 · CIC 966'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222602'::uuid, 2::smallint, '¿Cuántos son los dogmas marianos definidos solemnemente por la Iglesia católica?', '["Dos","Tres","Cuatro","Siete"]'::jsonb, 2::smallint, 'Los cuatro dogmas marianos son: Maternidad Divina, Virginidad Perpetua, Inmaculada Concepción y Asunción al cielo.', 'CIC 490-499 · CIC 966'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222602'::uuid, 2::smallint, '¿Qué enseña el dogma de la Virginidad perpetua de María?', '["Que permaneció virgen antes, durante y después del parto de Jesús","Que solo fue virgen hasta el nacimiento de Jesús","Que hizo voto temporal en el Templo","Que no se desposó con san José"]'::jsonb, 0::smallint, 'La Iglesia confiesa a María como "siempre Virgen" (Aeiparthenos): Jesús es su único Hijo, concebido por obra del Espíritu Santo.', 'Lc 1,34-35 · CIC 499'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222602'::uuid, 2::smallint, '¿En qué fecha celebra la Iglesia la solemnidad de la Inmaculada Concepción de María?', '["15 de agosto","8 de diciembre","1 de enero","25 de marzo"]'::jsonb, 1::smallint, 'El 8 de diciembre celebramos la Inmaculada Concepción (nueve meses antes del 8 de septiembre, Natividad de María).', 'Gn 3,15 · CIC 491'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222603'::uuid, 3::smallint, '¿Qué concilio proclamó a María "Theotokos", Madre de Dios, en el año 431?', '["Concilio de Nicea","Concilio de Éfeso","Concilio de Trento","Concilio Vaticano II"]'::jsonb, 1::smallint, 'Éfeso confirmó que María es verdaderamente Madre de Dios porque el Hijo que concibió es el Hijo eterno del Padre hecho hombre.', 'Lc 1,43 · CIC 495'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222603'::uuid, 3::smallint, '¿Con qué nombre llaman los Padres de la Iglesia a María al contrastar su obediencia con la desobediencia del Génesis?', '["Nueva Sara","Nueva Eva","Nueva Rut","Nueva Ester"]'::jsonb, 1::smallint, 'San Ireneo enseñó que "el nudo de la desobediencia de Eva fue desatado por la obediencia de María", abriendo el camino a la vida.', 'Gn 3,15 · CIC 494'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222603'::uuid, 3::smallint, '¿Qué diferencia enseña la Iglesia entre la adoración debida solo a Dios y el culto a la Virgen María?', '["Son exactamente iguales","Solo a Dios se le da adoración (latría); a María se le tributa una veneración especial (hiperdulía)","A María no se le rinde culto litúrgico","María recibe adoración en sus fiestas solemnes"]'::jsonb, 1::smallint, 'La veneración a María es esencialmente distinta de la adoración debida únicamente a la Santísima Trinidad, y siempre conduce a Cristo.', 'Lc 1,48 · CIC 971'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222603'::uuid, 3::smallint, '¿Qué papa proclamó solemnemente a María "Madre de la Iglesia" durante el Concilio Vaticano II en 1964?', '["San Juan XXIII","San Pablo VI","San Juan Pablo II","Benedicto XVI"]'::jsonb, 1::smallint, 'San Pablo VI proclamó este título en 1964, y el papa Francisco instituyó su memoria obligatoria el lunes después de Pentecostés.', 'Hch 1,14 · CIC 963'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222603'::uuid, 3::smallint, '¿En qué fecha celebra la Iglesia la Solemnidad de Santa María, Madre de Dios?', '["1 de enero","2 de febrero","13 de mayo","12 de diciembre"]'::jsonb, 0::smallint, 'El 1 de enero, octava de Navidad, comenzamos el año civil honrando a María como Madre de Dios y rezando por la paz mundial.', 'Gál 4,4-5 · CIC 495'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222604'::uuid, 1::smallint, '¿A qué santo indígena se le apareció Nuestra Señora de Guadalupe en el cerro del Tepeyac en 1531?', '["San Juan Diego Cuauhtlatoatzin","San Martín de Porres","San Felipe de Jesús","San José de Anchieta"]'::jsonb, 0::smallint, 'María le dijo a san Juan Diego: "¿No estoy yo aquí, que soy tu Madre?", y dejó su imagen impresa milagrosamente en su tilma.', 'Ap 12,1 · CIC 971'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222604'::uuid, 1::smallint, 'En 1858 en Lourdes, Francia, ¿cómo se presentó la Virgen María ante santa Bernardita Soubirous?', '["\"Yo soy la Reina del Rosario\"","\"Yo soy la Inmaculada Concepción\"","\"Yo soy la Estrella del Mar\"","\"Yo soy la Madre del Buen Consejo\""]'::jsonb, 1::smallint, 'Cuatro años después de proclamado el dogma por Pío IX, la Virgen confirmó ese título ante Bernardita e invitó a la oración y la penitencia.', 'Lc 1,28 · CIC 491'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222604'::uuid, 1::smallint, '¿Qué pedido central repitió la Virgen María en sus apariciones de Fátima (1917) a Lucía, Francisco y Jacinta?', '["Construir una universidad","Rezar el Rosario cada día por la paz y la conversión de los pecadores","Ayunar todos los domingos","Viajar a Jerusalén"]'::jsonb, 1::smallint, 'Nuestra Señora del Rosario de Fátima invitó a la conversión, la oración diaria del Rosario y la consagración a su Inmaculado Corazón.', 'Lc 18,1 · CIC 2678'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222604'::uuid, 1::smallint, '¿Qué advocación mariana, cuya carreta se detuvo milagrosamente en 1630, es patrona de Argentina, Uruguay y Paraguay?', '["Nuestra Señora del Pilar","Nuestra Señora de Luján","Nuestra Señora de Aparecida","Nuestra Señora de Copacabana"]'::jsonb, 1::smallint, 'La pequeña imagen de la Inmaculada Concepción que hoy veneramos en Luján fue custodiada fielmente por el Negro Manuel y convoca millones de peregrinos.', 'Lc 1,48 · CIC 971'),
  ('11111111-1111-4111-8111-111111111106'::uuid, '22222222-2222-4222-8222-222222222604'::uuid, 1::smallint, '¿A qué santa francesa se le apareció la Virgen en 1830 en la Rue du Bac (París) confiándole la Medalla Milagrosa?', '["Santa Catalina Labouré","Santa Margarita María Alacoque","Santa Juana de Arco","Santa Luisa de Marillac"]'::jsonb, 0::smallint, 'La medalla lleva la jaculatoria "Oh María, sin pecado concebida, ruega por nosotros que recurrimos a ti", recordando la intercesión maternal de María.', 'Jn 2,5 · CIC 2677'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222401'::uuid, 1::smallint, '¿Cuántos son los sacramentos instituidos por Jesucristo en la Iglesia católica?', '["Cinco","Seis","Siete","Nueve"]'::jsonb, 2::smallint, 'Los siete sacramentos abarcan todas las etapas de la vida cristiana: iniciación, curación y servicio a la comunión.', 'Mt 28,19-20 · CIC 1210'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222401'::uuid, 1::smallint, '¿Cuál es el sacramento que constituye el fundamento de toda la vida cristiana y nos hace hijos de Dios?', '["Confirmación","Bautismo","Reconciliación","Eucaristía"]'::jsonb, 1::smallint, 'El Bautismo es la puerta de la vida en el Espíritu, perdona el pecado original y nos incorpora a la Iglesia.', 'Jn 3,5 · CIC 1213'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222401'::uuid, 1::smallint, '¿Qué sacramento es llamado por el Catecismo "fuente y culmen de toda la vida cristiana"?', '["El Matrimonio","El Bautismo","La Eucaristía","El Orden Sagrado"]'::jsonb, 2::smallint, 'En la Eucaristía está contenido todo el bien espiritual de la Iglesia, es decir, Cristo mismo, nuestra Pascua.', 'Jn 6,51 · CIC 1324'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222401'::uuid, 1::smallint, '¿Cuál es el signo esencial del sacramento de la Confirmación?', '["La entrega de una vela encendida","La unción con el santo crisma y la imposición de la mano","La aspersión con agua bendita","La señal de la paz"]'::jsonb, 1::smallint, 'La Confirmación se confiere por la unción del santo crisma en la frente con la imposición de la mano y las palabras rituales.', 'Hch 8,14-17 · CIC 1300'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222401'::uuid, 1::smallint, '¿En el nombre de quién se administra válidamente el Bautismo según el mandato de Jesús?', '["En el nombre de los profetas y apóstoles","En el nombre del Padre, y del Hijo, y del Espíritu Santo","En el nombre de la Iglesia de Roma","En el nombre de la ley de Moisés"]'::jsonb, 1::smallint, 'Jesús resucitado mandó bautizar en el nombre de la Santísima Trinidad; con agua natural y esa fórmula se realiza el rito esencial.', 'Mt 28,19 · CIC 1240'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222402'::uuid, 2::smallint, '¿Cuáles son los dos sacramentos llamados "de curación"?', '["Bautismo y Confirmación","Penitencia (Reconciliación) y Unción de los Enfermos","Matrimonio y Orden Sagrado","Eucaristía y Reconciliación"]'::jsonb, 1::smallint, 'Cristo, médico de almas y cuerpos, quiso que su Iglesia continuara su obra de curación mediante la Reconciliación y la Unción de los Enfermos.', 'Sant 5,14-15 · CIC 1421'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222402'::uuid, 2::smallint, '¿Cuáles son los tres grados del sacramento del Orden Sagrado?', '["Lector, acólito y diácono","Episcopado (obispos), presbiterado (sacerdotes) y diaconado (diáconos)","Monje, fraile y párroco","Catequista, misionero y sacerdote"]'::jsonb, 1::smallint, 'Desde los tiempos apostólicos el ministerio ordenado se ejerce en tres grados: obispos, presbíteros y diáconos.', '1 Tim 3,1-13 · CIC 1554'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222402'::uuid, 2::smallint, 'En el rito latino, ¿quiénes son los ministros que se confieren mutuamente el sacramento del Matrimonio?', '["El sacerdote y los padrinos","Los propios esposos al expresar su consentimiento ante la Iglesia","Los padres de los novios","El obispo diocesano"]'::jsonb, 1::smallint, 'Los contrayentes son los ministros de la gracia matrimonial al intercambiar su consentimiento libre; el sacerdote o diácono asiste como testigo cualificado.', 'Ef 5,31-32 · CIC 1623'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222402'::uuid, 2::smallint, '¿Cuándo conviene recibir el sacramento de la Unción de los Enfermos?', '["Únicamente en el último instante de la muerte","Cuando un fiel comienza a estar en peligro por enfermedad grave o vejez","Solo una vez en toda la vida","Antes de cualquier viaje largo"]'::jsonb, 1::smallint, 'La Unción no es solo para agonizantes: fortalece, consuela, perdona los pecados y puede recibirse de nuevo si la enfermedad empeora o se presenta otra grave.', 'Sant 5,14-15 · CIC 1514'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222402'::uuid, 2::smallint, '¿Qué poder confió Jesús resucitado a los apóstoles al soplar sobre ellos diciendo "Reciban el Espíritu Santo"?', '["El poder de perdonar los pecados en su nombre","El poder de gobernar las naciones","El poder de construir templos","El poder de predecir fechas exactas"]'::jsonb, 0::smallint, 'Cristo confió a los apóstoles y a sus sucesores el ministerio de la reconciliación para perdonar los pecados en nombre de Dios.', 'Jn 20,22-23 · CIC 1441'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222403'::uuid, 3::smallint, '¿Qué tres sacramentos imprimen un "carácter" espiritual indeleble y por eso no se repiten?', '["Bautismo, Eucaristía y Matrimonio","Bautismo, Confirmación y Orden Sagrado","Confirmación, Reconciliación y Unción","Bautismo, Matrimonio y Orden Sagrado"]'::jsonb, 1::smallint, 'El Bautismo, la Confirmación y el Orden confieren un sello espiritual permanente que configura al fiel con Cristo de modo definitivo.', '2 Cor 1,21-22 · CIC 1121'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222403'::uuid, 3::smallint, '¿Qué significa que los sacramentos actúan "ex opere operato"?', '["Que su eficacia depende de la santidad personal del ministro","Que actúan por la fuerza misma de Cristo que obra en el rito válidamente celebrado","Que solo tienen efecto si el fiel entiende latín","Que requieren una ofrenda económica"]'::jsonb, 1::smallint, 'En todo sacramento es Cristo mismo quien actúa; los frutos recibidos dependen también de la fe y disposición de quien lo recibe.', '1 Cor 3,7 · CIC 1128'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222403'::uuid, 3::smallint, '¿Cómo define el Catecismo a los sacramentos de la Nueva Ley?', '["Recuerdos simbólicos de historias antiguas","Signos eficaces de la gracia, instituidos por Cristo y confiados a la Iglesia","Normas administrativas de cada parroquia","Tradiciones culturales de Europa"]'::jsonb, 1::smallint, 'Cada sacramento realiza realmente la gracia que significa, comunicando la vida divina al creyente.', 'Jn 1,16 · CIC 1131'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222403'::uuid, 3::smallint, 'En caso de peligro de muerte y ausencia de sacerdote, ¿quién puede bautizar válidamente?', '["Solo un obispo","Solo un diácono permanente","Cualquier persona, incluso no bautizada, si tiene la intención de hacer lo que hace la Iglesia","Nadie puede bautizar fuera del templo"]'::jsonb, 2::smallint, 'Por la voluntad salvífica universal de Dios, en caso de necesidad cualquier persona puede bautizar vertiendo agua y usando la fórmula trinitaria.', '1 Tim 2,4 · CIC 1256'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222403'::uuid, 3::smallint, '¿Qué es la gracia santificante que recibimos por primera vez en el Bautismo?', '["Un sentimiento pasajero de alegría","Un don habitual y estable que nos hace partícipes de la naturaleza divina y templos del Espíritu Santo","Una recompensa que se gana con méritos propios","Un título honorífico dentro de la parroquia"]'::jsonb, 1::smallint, 'La gracia santificante es participación real en la vida de Dios que perfecciona nuestra alma para vivir y obrar por amor a Él.', '2 P 1,4 · CIC 2000'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222404'::uuid, 2::smallint, '¿Con qué término expresa la Iglesia el cambio de toda la sustancia del pan y del vino en el Cuerpo y la Sangre de Cristo?', '["Consubstanciación","Transubstanciación","Transfiguración","Encarnación"]'::jsonb, 1::smallint, 'Por la consagración, mediante la palabra de Cristo y la acción del Espíritu Santo, el pan y el vino se convierten verdadera, real y sustancialmente en Cristo.', 'Lc 22,19-20 · CIC 1376'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222404'::uuid, 2::smallint, '¿Cuáles son los actos esenciales del penitente en el sacramento de la Reconciliación?', '["Ayuno, limosna y peregrinación","Contrición (arrepentimiento), confesión de los pecados y satisfacción (penitencia)","Lectura de tres salmos y silencio","Solo un propósito interior sin confesión"]'::jsonb, 1::smallint, 'El arrepentimiento sincero del corazón, la confesión ante el sacerdote y la reparación del daño preparan el alma para recibir la absolución de Dios.', '1 Jn 1,9 · CIC 1450'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222404'::uuid, 2::smallint, '¿Qué obligación absoluta tiene el sacerdote respecto de todo lo escuchado en la confesión?', '["Puede comentarlo solo con el obispo","Guardar el sigilo sacramental inviolable bajo toda circunstancia","Llevar un registro escrito confidencial","Puede revelarlo después de diez años"]'::jsonb, 1::smallint, 'El secreto de confesión no admite ninguna excepción; protege la dignidad del penitente y la libertad total del diálogo con Dios.', 'Jn 20,23 · CIC 1467'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222404'::uuid, 2::smallint, '¿Qué condición principal requiere la Iglesia antes de acercarse a recibir la Sagrada Comunión?', '["No haber hablado durante todo el día","Estar en estado de gracia (sin pecado mortal sin confesar) y guardar el ayuno eucarístico","Haber peregrinado a un santuario ese año","Saber de memoria el Evangelio del día"]'::jsonb, 1::smallint, 'Quien tiene conciencia de pecado grave debe recibir primero la Reconciliación antes de comulgar, además de guardar una hora de ayuno (excepto agua y medicinas).', '1 Cor 11,27-29 · CIC 1385'),
  ('11111111-1111-4111-8111-111111111104'::uuid, '22222222-2222-4222-8222-222222222404'::uuid, 2::smallint, '¿Cómo se llama el lugar sagrado del templo donde se reserva la Eucaristía para la adoración y para llevarla a los enfermos?', '["El ambón","El sagrario (tabernáculo)","La pila bautismal","La sacristía"]'::jsonb, 1::smallint, 'El sagrario guarda las especies consagradas; una lámpara encendida junto a él indica la presencia real de Jesús sacramentado.', 'Mt 28,20 · CIC 1379'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222501'::uuid, 1::smallint, '¿Cuáles son las dos grandes partes que forman un solo acto de culto en la Santa Misa?', '["Ritos iniciales y despedida","Liturgia de la Palabra y Liturgia Eucarística","Homilía y Comunión","Salmo y Credo"]'::jsonb, 1::smallint, 'La Misa se estructura en la mesa de la Palabra de Dios y la mesa del Cuerpo de Cristo, inseparablemente unidas.', 'Lc 24,27-35 · CIC 1346'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222501'::uuid, 1::smallint, '¿Qué tiempo litúrgico prepara durante cuatro semanas la celebración de la Navidad?', '["Cuaresma","Adviento","Tiempo Ordinario","Octava de Pascua"]'::jsonb, 1::smallint, 'El Adviento abre el año litúrgico y nos invita a esperar con alegría el nacimiento de Jesús y su venida gloriosa.', 'Is 40,3 · CIC 524'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222501'::uuid, 1::smallint, '¿Cuál es la celebración central de todo el año litúrgico cristiano?', '["La Epifanía","El Domingo de Pascua (Resurrección)","La Asunción","Todos los Santos"]'::jsonb, 1::smallint, 'La Pascua es la "Fiesta de las fiestas" porque celebra la resurrección de Cristo, fundamento de nuestra fe.', '1 Cor 15,14 · CIC 1169'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222501'::uuid, 1::smallint, '¿Cuál es el momento culminante de la Liturgia de la Palabra en la Santa Misa, que escuchamos de pie?', '["La primera lectura","La proclamación del Santo Evangelio","El salmo responsorial","Las moniciones iniciales"]'::jsonb, 1::smallint, 'Nos ponemos de pie y cantamos el Aleluya porque en la proclamación del Evangelio es Cristo mismo quien habla a su pueblo.', 'Jn 6,68 · IGMR 60'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222501'::uuid, 1::smallint, '¿Qué significa la palabra "Amén" que respondemos al recibir la Comunión y al cerrar las oraciones?', '["\"Hasta pronto\"","\"Así sea / Creo firmemente\"","\"Paz a todos\"","\"Gracias por venir\""]'::jsonb, 1::smallint, 'Al decir "Amén" ante "El Cuerpo de Cristo", expresamos nuestra adhesión libre y nuestra fe en su presencia real.', 'Ap 22,20 · CIC 1062'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222502'::uuid, 2::smallint, '¿Qué color litúrgico se usa habitualmente durante Adviento y Cuaresma?', '["Verde","Rojo","Morado","Blanco"]'::jsonb, 2::smallint, 'El color morado expresa conversión, espera vigilante y penitencia en Adviento y Cuaresma.', 'Jl 2,12-13 · IGMR 346'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222502'::uuid, 2::smallint, '¿En qué fiestas se emplea el color litúrgico rojo?', '["Domingos del Tiempo Ordinario","Pentecostés, Domingo de Ramos, Viernes Santo y mártires","Navidad y Pascua","Solemnidades de la Virgen María"]'::jsonb, 1::smallint, 'El rojo simboliza el fuego del Espíritu Santo y la sangre derramada por Cristo y sus mártires.', 'Hch 2,3-4 · IGMR 346'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222502'::uuid, 2::smallint, '¿Qué tres días forman el Triduo Pascual, corazón del año litúrgico?', '["Miércoles de Ceniza, Jueves y Viernes","Desde la Misa vespertina del Jueves Santo hasta las Vísperas del Domingo de Pascua","Navidad, San Esteban y San Juan","Ascensión, Pentecostés y Trinidad"]'::jsonb, 1::smallint, 'El Triduo Pascual celebra en una sola gran liturgia la Pasión, Muerte y Resurrección del Señor.', 'Rm 6,4 · CIC 1168'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222502'::uuid, 2::smallint, '¿Cuántos días dura el Tiempo Pascual, desde el Domingo de Resurrección hasta Pentecostés?', '["Treinta días","Cuarenta días","Cincuenta días","Veintiocho días"]'::jsonb, 2::smallint, 'Los cincuenta días de Pascua se celebran con alegría como un "gran domingo" que culmina con la efusión del Espíritu Santo.', 'Hch 2,1 · CIC 1169'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222502'::uuid, 2::smallint, '¿Qué color litúrgico simboliza la esperanza y se utiliza a lo largo del Tiempo Ordinario?', '["Blanco","Verde","Rosa","Celeste"]'::jsonb, 1::smallint, 'El verde evoca la vida que crece y la esperanza cristiana mientras meditamos la vida pública y las enseñanzas de Jesús.', 'Rm 15,13 · IGMR 346'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222503'::uuid, 3::smallint, '¿Cómo se llama la oración pública diaria de la Iglesia compuesta principalmente por salmos e himnos?', '["Vía Crucis","Liturgia de las Horas","Lectio Divina","Ángelus"]'::jsonb, 1::smallint, 'La Liturgia de las Horas (Oficio Divino) santifica el curso del día y de la noche uniendo a los fieles en la oración de Cristo.', 'Sal 119,164 · CIC 1174-1175'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222503'::uuid, 3::smallint, '¿Cuáles son las dos "horas principales" (quicios) de la Liturgia de las Horas?', '["Tercia y Sexta","Laudes (mañana) y Vísperas (tarde)","Completas y Nona","Oficio de Lectura y Ángelus"]'::jsonb, 1::smallint, 'Laudes consagra a Dios el comienzo del día y Vísperas le da gracias al caer la tarde; todos los fieles están invitados a rezarlas.', 'Sal 141,2 · CIC 1175'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222503'::uuid, 3::smallint, 'En el templo católico, ¿cómo se llama el atril elevado desde donde se proclama exclusivamente la Palabra de Dios?', '["El presbiterio","El ambón","La credencia","El púlpito lateral"]'::jsonb, 1::smallint, 'La dignidad de la Palabra de Dios exige un lugar adecuado —el ambón— desde donde se proclaman las lecturas, el salmo y la homilía.', 'Neh 8,4 · IGMR 309'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222503'::uuid, 3::smallint, '¿En cuántos ciclos dominicales (A, B y C) está organizado el Leccionario para leer los Evangelios sinópticos?', '["Un solo ciclo anual","Tres ciclos: A (Mateo), B (Marcos) y C (Lucas)","Dos ciclos: par e impar","Cuatro ciclos, uno por estación"]'::jsonb, 1::smallint, 'En tres años se recorre la riqueza de toda la Escritura; el Evangelio de san Juan se proclama especialmente en Pascua y en el ciclo B.', '2 Tim 3,16 · CIC 1154'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222503'::uuid, 3::smallint, '¿Qué simboliza el Cirio Pascual encendido en la Vigilia Pascual y junto a la pila bautismal?', '["El calendario solar de la primavera","A Cristo resucitado, Luz del mundo que vence las tinieblas","La antigüedad del templo","El inicio del Adviento"]'::jsonb, 1::smallint, 'Lleva la cruz, el Alfa y la Omega y el año en curso, proclamando que Cristo es el mismo ayer, hoy y siempre.', 'Jn 8,12 · CIC 1168'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222504'::uuid, 1::smallint, '¿Qué oración nos enseñó Jesús mismo y es llamada "el resumen de todo el Evangelio"?', '["El Credo","El Padrenuestro","El Gloria","La Salve"]'::jsonb, 1::smallint, 'El Padrenuestro contiene siete peticiones: tres orientadas a la gloria del Padre y cuatro que le presentan nuestras necesidades.', 'Mt 6,9-13 · CIC 2761'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222504'::uuid, 1::smallint, '¿Qué serie de misterios del Santo Rosario agregó san Juan Pablo II en 2002 para contemplar la vida pública de Jesús?', '["Misterios Gozosos","Misterios Luminosos (de la Luz)","Misterios Dolorosos","Misterios Gloriosos"]'::jsonb, 1::smallint, 'Los misterios luminosos contemplan el Bautismo en el Jordán, Caná, el anuncio del Reino, la Transfiguración y la institución de la Eucaristía.', 'Jn 8,12 · CIC 2678'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222504'::uuid, 1::smallint, '¿Qué práctica de oración antigua recorre en cuatro pasos (lectura, meditación, oración y contemplación) un pasaje bíblico?', '["Lectio Divina","Novena","Procesión","Letanía"]'::jsonb, 0::smallint, 'La Lectio Divina permite escuchar personalmente a Dios que nos habla en la Sagrada Escritura y responderle desde el corazón.', 'Sal 119,105 · CIC 2708'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222504'::uuid, 1::smallint, '¿Cuántas estaciones tradicionales recorre el Vía Crucis al meditar la Pasión del Señor?', '["Siete estaciones","Doce estaciones","Catorce estaciones","Veinte estaciones"]'::jsonb, 2::smallint, 'El Vía Crucis acompaña a Jesús desde la condena a muerte hasta su sepultura, fortaleciendo la compasión y la esperanza en la cruz.', 'Lc 9,23 · CIC 1674'),
  ('11111111-1111-4111-8111-111111111105'::uuid, '22222222-2222-4222-8222-222222222504'::uuid, 1::smallint, '¿Qué oración breve se reza tradicionalmente al mediodía recordando la Encarnación del Verbo (y se reemplaza en Pascua por el Regina Caeli)?', '["El Ángelus","El Te Deum","El Tantum Ergo","El Salve Regina"]'::jsonb, 0::smallint, 'El Ángelus comienza con "El ángel del Señor anunció a María" y nos ayuda a detenernos en medio del día para recordar que Dios se hizo hombre.', 'Jn 1,14 · CIC 2676'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222701'::uuid, 1::smallint, '¿Qué santo del siglo VI escribió la regla monástica resumida en el lema "Ora et labora" (Reza y trabaja)?', '["San Benito de Nursia","San Francisco de Asís","San Ignacio de Loyola","San Bruno"]'::jsonb, 0::smallint, 'San Benito fundó la Orden Benedictina y los monasterios que preservaron la fe, la liturgia y la cultura en Europa; es patrono de Europa.', '1 Tes 5,17 · CIC 927'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222701'::uuid, 1::smallint, '¿Quién fundó la Compañía de Jesús (los jesuitas) y redactó los célebres "Ejercicios Espirituales"?', '["San Vicente de Paúl","San Ignacio de Loyola","Santo Domingo de Guzmán","San Juan de la Cruz"]'::jsonb, 1::smallint, 'San Ignacio de Loyola (1491-1556) fundó la Compañía de Jesús con el lema "Ad maiorem Dei gloriam" (Para mayor gloria de Dios).', '1 Cor 10,31 · CIC 931'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222701'::uuid, 1::smallint, '¿Qué santo español fundó en el siglo XIII la Orden de Predicadores (dominicos) dedicada al estudio y la predicación de la verdad?', '["Santo Domingo de Guzmán","San Francisco de Sales","San Bernardo de Claraval","San José de Calasanz"]'::jsonb, 0::smallint, 'Santo Domingo de Guzmán dio a su orden el carisma de "contemplar y dar a los demás lo contemplado", formando grandes teólogos como santo Tomás de Aquino.', 'Rm 10,14-15 · CIC 927'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222701'::uuid, 1::smallint, '¿Qué santa, discípula espiritual de san Francisco de Asís, fundó la Orden de las Hermanas Pobres (Clarisas)?', '["Santa Clara de Asís","Santa Escolástica","Santa Rosa de Viterbo","Santa Rita de Casia"]'::jsonb, 0::smallint, 'Santa Clara vivió el privilegio de la pobreza radical y una ardiente devoción eucarística en el monasterio de San Damián.', 'Mt 19,21 · CIC 916'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222701'::uuid, 1::smallint, '¿Qué familia religiosa, vinculada al monte Carmelo y a la devoción del Escapulario, fue renovada por santa Teresa de Ávila y san Juan de la Cruz?', '["Los Cartujos","La Orden del Carmelo (carmelitas)","Los Agustinos","Los Mercedarios"]'::jsonb, 1::smallint, 'El carisma carmelita une contemplación silenciosa, fraternidad y amor a la Virgen del Carmen como guía hacia Cristo.', '1 Re 19,11-13 · CIC 2684'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222702'::uuid, 2::smallint, '¿Qué santo fundó el Opus Dei en 1928 recordando que todos los bautizados están llamados a la santidad en el trabajo ordinario?', '["San Josemaría Escrivá de Balaguer","San Pío de Pietrelcina","San Manuel González","San Pedro Poveda"]'::jsonb, 0::smallint, 'San Josemaría predicó la santificación del trabajo profesional y de la vida cotidiana mucho antes de que el Vaticano II proclamara la llamada universal a la santidad.', 'Col 3,23 · CIC 2013'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222702'::uuid, 2::smallint, '¿Qué movimiento apostólico internacional fundó el padre José Kentenich en 1914 en torno a la Alianza de Amor con María en un santuario?', '["Movimiento de Schoenstatt","Acción Católica","Regnum Christi","Comunidad de Taizé"]'::jsonb, 0::smallint, 'Schoenstatt promueve la educación de la libertad, la santidad en la vida diaria y la Alianza de Amor con la Madre Tres Veces Admirable.', 'Jn 19,25-27 · CIC 900'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222702'::uuid, 2::smallint, '¿Qué laica italiana inició en Trento durante la Segunda Guerra Mundial el Movimiento de los Focolares centrado en la unidad ("Que todos sean uno")?', '["Chiara Lubich","Carmen Hernández","Adrienne von Speyr","Concepción Cabrera"]'::jsonb, 0::smallint, 'Chiara Lubich (1920-2008) impulsó la espiritualidad de la comunión, el amor recíproco y el diálogo ecuménico e interreligioso.', 'Jn 17,21 · CIC 813'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222702'::uuid, 2::smallint, '¿Qué sacerdote italiano fundó el movimiento Comunión y Liberación proponiendo el cristianismo como un encuentro vivo que responde al deseo del corazón?', '["Siervo de Dios Luigi Giussani","San Luis Orione","Don Primo Mazzolari","San José Moscati"]'::jsonb, 0::smallint, 'Don Luigi Giussani (1922-2005) educó a generaciones de estudiantes y laicos en la razonabilidad de la fe y la presencia cristiana en la cultura.', 'Jn 1,39 · CIC 900'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222702'::uuid, 2::smallint, '¿Cómo describe el Catecismo a los carismas y movimientos suscitados por el Espíritu Santo en la Iglesia?', '["Grupos independientes de los obispos","Gracias ordenadas a la edificación y utilidad común de toda la Iglesia","Asociaciones reservadas solo a consagrados","Costumbres temporales sin valor eclesial"]'::jsonb, 1::smallint, 'Los carismas, extraordinarios o sencillos, son dones del Espíritu Santo para el bien de los hombres y la edificación de la Iglesia, siempre en comunión con los pastores.', '1 Cor 12,7 · CIC 799-800'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222703'::uuid, 2::smallint, '¿Qué corriente de gracia surgida en 1967 promueve la experiencia personal de Pentecostés, la oración de alabanza y los dones del Espíritu Santo?', '["Renovación Carismática Católica","Orden del Císter","Caballeros de Colón","Cofradía del Santo Entierro"]'::jsonb, 0::smallint, 'La Renovación Carismática nació tras un retiro universitario en Duquesne (EE. UU.) y hoy reúne millones de fieles en todo el mundo bajo el servicio CHARIS.', 'Hch 2,1-4 · CIC 799-800'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222703'::uuid, 2::smallint, '¿Qué itinerario de formación católica postbautismal nació en las barracas de Madrid en 1964 por iniciativa de Kiko Argüello y Carmen Hernández?', '["El Camino Neocatecumenal","La Obra de Kolping","Los Equipos de Nuestra Señora","El Movimiento Juvenil Salesiano"]'::jsonb, 0::smallint, 'Aprobado por la Santa Sede, el Camino Neocatecumenal ayuda a redescubrir el Bautismo en pequeñas comunidades parroquiales y envía familias en misión.', 'Mt 28,19-20 · CIC 1231'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222703'::uuid, 2::smallint, '¿Qué movimiento nacido en Mallorca (España) en 1949 anuncia el primer anuncio cristiano a través de un retiro de tres días y el lema "¡De colores!"?', '["Cursillos de Cristiandad","Comunidad de Sant’Egidio","Legión de María","Encuentro Matrimonial"]'::jsonb, 0::smallint, 'Los Cursillos de Cristiandad buscan renovar los ambientes cotidianos con el Evangelio mediante la amistad, la piedad, el estudio y la acción.', 'Mc 16,15 · CIC 905'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222703'::uuid, 2::smallint, '¿Qué movimiento de espiritualidad conyugal fundó el padre Henri Caffarel en Francia para ayudar a los matrimonios a caminar juntos hacia la santidad?', '["Equipos de Nuestra Señora","Juventud Obrera Cristiana","Talleres de Oración y Vida","Adoración Nocturna"]'::jsonb, 0::smallint, 'Los Equipos de Nuestra Señora acompañan a parejas de esposos mediante la oración en común, el diálogo conyugal y el apoyo mutuo en pequeños equipos.', 'Ef 5,31-32 · CIC 1641'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222703'::uuid, 2::smallint, '¿Qué sacerdote capuchino fundó los "Talleres de Oración y Vida" para enseñar de modo práctico a orar y tratar con Dios como amigo?', '["Padre Ignacio Larrañaga","Padre Pío","San Leopoldo Mandic","Padre Cantalamessa"]'::jsonb, 0::smallint, 'El padre Ignacio Larrañaga (1928-2013) difundió los Talleres de Oración y Vida en decenas de países, acercando la oración contemplativa a miles de laicos.', 'Lc 11,1 · CIC 2709'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222704'::uuid, 3::smallint, '¿Qué organización laical mariana fue fundada por Frank Duff en Dublín en 1921 para evangelizar puerta a puerta y acompañar a enfermos y alejados?', '["La Legión de María","La Milicia de la Inmaculada","El Apostolado de la Oración","Las Hijas de María"]'::jsonb, 0::smallint, 'La Legión de María reúne semanalmente a sus miembros en "praesidia" para rezar el Rosario y realizar un trabajo apostólico concreto en la parroquia.', 'Lc 1,39-45 · CIC 900'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222704'::uuid, 3::smallint, '¿Qué movimiento laical nacido en Roma en 1968 se distingue por la oración vespertina, la amistad con los pobres y la mediación por la paz?', '["Comunidad de Sant’Egidio","Orden de Malta","Movimiento Palestra","Vida Ascendente"]'::jsonb, 0::smallint, 'Iniciada por jóvenes estudiantes en Trastevere, Sant’Egidio une escucha diaria del Evangelio, servicio a ancianos y pobres, y trabajo diplomático por la paz.', 'Mt 5,9 · CIC 2443'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222704'::uuid, 3::smallint, '¿Qué joven laico francés fundó en 1833 la Sociedad de San Vicente de Paúl (Conferencias Vicentinas) para visitar y socorrer personalmente a familias pobres?', '["Beato Federico Ozanam","San Juan María Vianney","San Luis de Montfort","Beato Carlos de Foucauld"]'::jsonb, 0::smallint, 'Federico Ozanam, con solo 20 años, respondió a quienes cuestionaban la fe mostrando una caridad activa y cercana inspirada en san Vicente de Paúl.', 'Sant 2,14-17 · CIC 2447'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222704'::uuid, 3::smallint, '¿Qué organización oficial de la Iglesia coordina la acción caritativa y social en diócesis y parroquias de todo el mundo?', '["Cáritas","Propaganda Fide","Rota Romana","Academia Pontificia"]'::jsonb, 0::smallint, 'Cáritas (del latín "caridad / amor") expresa el compromiso concreto de toda la Iglesia por la dignidad humana y los más vulnerables.', '1 Cor 13,4-13 · CIC 2443'),
  ('11111111-1111-4111-8111-111111111107'::uuid, '22222222-2222-4222-8222-222222222704'::uuid, 3::smallint, '¿Qué institución laical promueve desde el siglo XIX la formación integral de los laicos y su colaboración directa con los pastores en parroquias y diócesis?', '["Acción Católica","Orden Teutónica","Congregación del Oratorio","Hermanos Maristas"]'::jsonb, 0::smallint, 'El Concilio Vaticano II destacó el valor de la Acción Católica como escuela de apostolado laical en comunión directa con la diócesis y la parroquia.', '1 P 2,9 · CIC 900'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222801'::uuid, 1::smallint, '¿En qué ciudad fueron llamados "cristianos" por primera vez los discípulos de Jesús?', '["Jerusalén","Roma","Antioquía","Alejandría"]'::jsonb, 2::smallint, 'Los Hechos de los Apóstoles narran que en Antioquía de Siria, donde predicaron Bernabé y Pablo, se usó por primera vez el nombre de "cristianos".', 'Hch 11,26 · CIC 1289'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222801'::uuid, 1::smallint, '¿Qué documento promulgado en el año 313 por el emperador Constantino concedió libertad religiosa a los cristianos tras siglos de persecución?', '["Edicto de Milán","Paz de Westfalia","Concordato de Worms","Carta Magna"]'::jsonb, 0::smallint, 'El Edicto de Milán puso fin a las persecuciones romanas y permitió a los cristianos construir templos y celebrar la fe públicamente.', '1 Tim 2,1-2 · CIC 2106'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222801'::uuid, 1::smallint, '¿Qué obispo mártir del siglo II usó por primera vez por escrito la expresión "Iglesia Católica" en su carta a los de Esmirna?', '["San Ignacio de Antioquía","San Ireneo de Lyon","San Justino","San Clemente Romano"]'::jsonb, 0::smallint, 'San Ignacio escribió rumbo al martirio en Roma: "Donde está Cristo Jesús, allí está la Iglesia Católica", mostrando su universalidad desde el inicio.', 'Mt 28,19 · CIC 830'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222801'::uuid, 1::smallint, '¿Por qué eran usados los peces ("Ichthys") como símbolo secreto entre los primeros cristianos?', '["Porque solo pescaban los domingos","Porque sus letras griegas formaban el acrónimo \"Jesucristo, Hijo de Dios, Salvador\"","Porque era el escudo de Roma","Porque recordaba el mar Rojo"]'::jsonb, 1::smallint, 'Las iniciales griegas I-Ch-Th-Y-S significan Iesous Christos Theou Yios Soter, una breve profesión de fe cristiana grabada en las catacumbas.', 'Mt 16,16 · CIC 452'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222801'::uuid, 1::smallint, '¿Qué primer gran encuentro de los apóstoles en Jerusalén (hacia el año 49) decidió que los gentiles no debían circuncidarse para ser cristianos?', '["Concilio de Jerusalén","Concilio de Nicea","Sínodo de Cartago","Concilio de Éfeso"]'::jsonb, 0::smallint, 'Narrado en Hechos 15, el Concilio de Jerusalén inauguró el discernimiento colegial de la Iglesia bajo la guía del Espíritu Santo.', 'Hch 15,28 · CIC 884'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222802'::uuid, 2::smallint, '¿Qué primer concilio ecuménico del año 325 afirmó que Jesús es "consustancial al Padre" frente a la herejía de Arrio?', '["Concilio de Nicea I","Concilio de Calcedonia","Concilio de Letrán IV","Concilio de Constanza"]'::jsonb, 0::smallint, 'El Concilio de Nicea formuló la base del Credo que rezamos los domingos, confesando a Jesucristo como "Dios verdadero de Dios verdadero".', 'Jn 10,30 · CIC 465'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222802'::uuid, 2::smallint, '¿Qué definió el Concilio de Calcedonia en el año 451 sobre la persona de Jesucristo?', '["Que Jesús tiene dos naturalezas (divina y humana) unidas en una sola Persona divina","Que Jesús era solo un profeta humano","Que el Espíritu Santo procede solo del Padre","Que los Evangelios eran tres"]'::jsonb, 0::smallint, 'Calcedonia confesó que Cristo es verdadero Dios y verdadero hombre, en dos naturalezas "sin confusión, sin cambio, sin división, sin separación".', 'Jn 1,14 · CIC 467'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222802'::uuid, 2::smallint, '¿Qué Padre de la Iglesia, obispo de Alejandría, defendió incansablemente la divinidad de Cristo contra el arrianismo y sufrió cinco destierros?', '["San Atanasio","San Ambrosio","San León Magno","San Cipriano"]'::jsonb, 0::smallint, 'San Atanasio (295-373) resumió la Encarnación con una frase célebre: "El Hijo de Dios se hizo hombre para hacernos Dios".', '2 P 1,4 · CIC 460'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222802'::uuid, 2::smallint, '¿En qué siglo se produjo el Gran Cisma de Oriente (1054) que lamentablemente separó a la Iglesia católica y a las Iglesias ortodoxas?', '["Siglo IV","Siglo XI","Siglo XVI","Siglo XIX"]'::jsonb, 1::smallint, 'Desde 1965, con el abrazo entre san Pablo VI y el patriarca Atenágoras, católicos y ortodoxos rezan y dialogan activamente por la plena unidad.', 'Jn 17,21 · CIC 817'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222802'::uuid, 2::smallint, '¿Qué gran obispo de Milán del siglo IV fue maestro y bautizador de san Agustín?', '["San Ambrosio","San Hilario","San Gregorio Nacianceno","San Efrén"]'::jsonb, 0::smallint, 'La predicación bíblica y el testimonio valiente de san Ambrosio tocaron el corazón de san Agustín, quien recibió de él el Bautismo en el año 387.', 'Rm 10,17 · CIC 1236'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222803'::uuid, 3::smallint, '¿Qué concilio del siglo XVI (1545-1563) impulsó la reforma católica, creó los seminarios y clarificó la doctrina sobre los sacramentos y el canon bíblico?', '["Concilio de Trento","Concilio de Lyon","Concilio de Florencia","Concilio Vaticano I"]'::jsonb, 0::smallint, 'El Concilio de Trento renovó profundamente la vida pastoral, la formación de los sacerdotes y la predicación doctrinal de la Iglesia.', '2 Tim 1,14 · CIC 120'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222803'::uuid, 3::smallint, '¿Qué encíclica del papa León XIII (1891) inauguró la Doctrina Social de la Iglesia moderna defendiendo los derechos de los trabajadores?', '["Rerum Novarum","Lumen Gentium","Dei Verbum","Humanae Vitae"]'::jsonb, 0::smallint, 'Rerum Novarum ("De las cosas nuevas") defendió el salario justo, el descanso dominical y el derecho de asociación de los obreros.', 'Sant 5,4 · CIC 2421'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222803'::uuid, 3::smallint, '¿Qué papa convocó el Concilio Vaticano II (1962-1965) para abrir la Iglesia al diálogo pastoral con el mundo contemporáneo?', '["Pío XII","San Juan XXIII","San Pío X","Benedicto XV"]'::jsonb, 1::smallint, 'San Juan XXIII inauguró el Vaticano II en 1962 y san Pablo VI lo clausuró en 1965, renovando la liturgia, el protagonismo de los laicos y el ecumenismo.', 'Hch 15,28 · CIC 884'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222803'::uuid, 3::smallint, '¿Cuál de estas constituciones del Concilio Vaticano II trata sobre la Iglesia como Pueblo de Dios y la llamada universal a la santidad?', '["Lumen Gentium","Sacrosanctum Concilium","Dei Verbum","Gaudium et Spes"]'::jsonb, 0::smallint, 'Lumen Gentium ("Luz de las gentes") recuerda que todos los fieles, en cualquier estado de vida, están llamados a la plenitud de la caridad.', '1 P 2,9 · CIC 2013'),
  ('11111111-1111-4111-8111-111111111108'::uuid, '22222222-2222-4222-8222-222222222803'::uuid, 3::smallint, '¿En qué año se publicó el actual Catecismo de la Iglesia Católica, fruto del Sínodo de 1985 y promulgado por san Juan Pablo II?', '["1965","1978","1992","2005"]'::jsonb, 2::smallint, 'Promulgado en 1992 mediante la constitución Fidei Depositum, el CIC expone de modo orgánico el Credo, los Sacramentos, la Moral y la Oración.', '2 Tim 1,14 · CIC 11')
), updated as (
  update public.questions q
  set
    level_id = s.level_id,
    difficulty = s.difficulty,
    explanation = s.explanation,
    source_ref = s.source_ref,
    is_active = true
  from q_seed s
  where q.topic_id = s.topic_id and q.prompt = s.prompt
  returning q.topic_id, q.prompt
)
select s.topic_id, s.level_id, s.difficulty, s.prompt, s.options, s.correct_index, s.explanation, s.source_ref
from q_seed s
where not exists (
  select 1 from public.questions q where q.topic_id = s.topic_id and q.prompt = s.prompt
);

-- 6. Textos de referencia (Biblia Católica, CIC e IGMR: 316 entradas)
on conflict (ref_key) do update set
  source_type = excluded.source_type,
  title = excluded.title,
  book_or_section = excluded.book_or_section,
  body = excluded.body;

-- 7. Desafíos del Día iniciales (13 días con Lectura + Evangelio)
on conflict (challenge_date) do nothing;
